import React from "react";
import classNames from "classnames/bind";

/** Distinct Feather icon per luxury summary surface (extend when adding pages). */
export const LUX_SUMMARY_EYEBROW_ICONS = {
  "bid-requests": "fe-trending-up",
  "purchase-contracts": "fe-award",
  projects: "fe-layers",
  employees: "fe-users",
  invoices: "fe-credit-card",
  timesheet: "fe-clock",
  attendance: "fe-user-check",
  "team-capacity": "fe-bar-chart-2",
  "planning-alerts": "fe-alert-triangle",
  accounts: "fe-briefcase",
  notes: "fe-book-open",
  reports: "fe-pie-chart",
  feedback: "fe-message-square",
  deliverables: "fe-package",
  "work-items": "fe-check-square",
  taskboard: "fe-layout",
  "file-manager": "fe-folder",
  chat: "fe-message-circle",
  "user-calendar": "fe-calendar",
  settings: "fe-settings",
  "work-item-activities": "fe-activity",
  "planner-timeline": "fe-sliders",
  "planner-gantt": "fe-git-merge",
  "planner-roster": "fe-grid",
};

function resolveEyebrowIcon(icon, variant) {
  const raw = icon || (variant && LUX_SUMMARY_EYEBROW_ICONS[variant]) || "fe-activity";
  if (typeof raw !== "string") return "fe-activity";
  const trimmed = raw.trim();
  if (trimmed.startsWith("fe ")) {
    const parts = trimmed.split(/\s+/);
    return parts[1] || "fe-activity";
  }
  if (trimmed.startsWith("fe-")) return trimmed;
  return `fe-${trimmed}`;
}

/** Shared kicker above luxury page summary panels (icon + label). */
function LuxSummaryEyebrow({ children, className, variant, icon }) {
  if (!children) return null;

  const resolvedIcon = resolveEyebrowIcon(icon, variant);

  return (
    <span
      className={classNames(
        "lux-summary-eyebrow",
        variant && `lux-summary-eyebrow--${variant}`,
        className
      )}
    >
      <i className={classNames("fe", resolvedIcon, "lux-summary-eyebrow__icon")} aria-hidden="true" />
      <span className="lux-summary-eyebrow__label">{children}</span>
    </span>
  );
}

export default LuxSummaryEyebrow;
