function buildLineItems(item) {
  if (!item) return [];

  const rows = [];
  const userCount = getUserCount(item);
  const billingMonth = item.invoiceMonthYear
    ? dateUtils
        .convertDateStringToMoment(item.invoiceMonthYear)
        .format(dateUtils.DATE_MONTH_FORMAT)
    : "—";

  rows.push({
    key: "monthly-fee",
    title: `Monthly User fee (${billingMonth})`,
    description: `Recurring monthly licence fee for ${item.numberOfUsers || userCount} users.`,
    unitPrice: 400,
    quantity: userCount,
    total: parseAmountSafe(item.totalAmount),
  });

  if (item.additionalItems && item.additionalItems.items) {
    item.additionalItems.items.forEach((additionalItem, index) => {
      rows.push({
        key: `additional-${index}`,
        title: additionalItem.name,
        description: additionalItem.description,
        unitPrice: null,
        quantity: null,
        total: parseAmountSafe(additionalItem.totalAmount),
      });
    });
  }

  return rows;
}

function parseAmountSafe(value) {
  const num = Number(value);
  return Number.isFinite(num) ? num : 0;
}

