import React from "react";
import classNames from "classnames/bind";

import PageInnerHeaderTeamsSelectionMenu from "views/common/fragments/PageInnerHeaderTeamsSelectionMenu";

export default function ProjectDashboardTeamScopeBar({
  userTeams,
  baseTeams,
  managerTeamMode,
  teamScopeLabel,
  canSwitchTeams,
  onTeamModeChange,
  onUserTeamsSelection,
}) {
  const totalTeams = baseTeams && baseTeams.length ? baseTeams.length : 0;
  const selectedTeamsCount = userTeams
    ? userTeams.filter((t) => t.isChecked).length
    : 0;

  if (!canSwitchTeams) {
    return (
      <div className="lux-hrms-dash__scope-bar">
        <div className="lux-hrms-dash__scope-main">
          <span className="lux-hrms-dash__scope-eyebrow">Team scope</span>
          <strong className="lux-hrms-dash__scope-label">{teamScopeLabel}</strong>
        </div>
      </div>
    );
  }

  return (
    <div className="lux-hrms-dash__scope-bar">
      <div className="lux-hrms-dash__scope-main">
        <span className="lux-hrms-dash__scope-eyebrow">Team scope</span>
        <strong className="lux-hrms-dash__scope-label">{teamScopeLabel}</strong>
      </div>

      <div className="lux-hrms-dash__scope-actions">
        <div className="lux-hrms-dash__scope-group" role="group" aria-label="Team scope">
          <button
            type="button"
            className={classNames("lux-hrms-dash__scope-chip", {
              "is-active": managerTeamMode === "selected",
            })}
            onClick={() => onTeamModeChange && onTeamModeChange("selected")}
          >
            Selected teams{" "}
            {selectedTeamsCount ? `(${selectedTeamsCount})` : ""}
          </button>

          <button
            type="button"
            className={classNames("lux-hrms-dash__scope-chip", {
              "is-active": managerTeamMode === "all",
            })}
            onClick={() => onTeamModeChange && onTeamModeChange("all")}
          >
            All teams {totalTeams ? `(${totalTeams})` : ""}
          </button>
        </div>

        {managerTeamMode === "selected" && (
          <PageInnerHeaderTeamsSelectionMenu
            userTeams={userTeams}
            enabled={canSwitchTeams}
            isLoading={false}
            handleUserTeamsSelection={onUserTeamsSelection}
          />
        )}
      </div>
    </div>
  );
}

