import React, { Component } from "react";
import { connect } from "react-redux";
import { checklistActions } from "_actions";
import { store } from "_helpers";
import RecurringSelectionWindow from "./modal/RecurringSelectionWindow";
import ItemCommentsSection from "./fragments/ItemCommentsSection";
import ConfigureChecklistSidebar from "./modal/ConfigureChecklistSidebar";
import ProjectDetailsTabShell from "./ProjectDetailsTabShell";
import DeliverableDetailsSummaryStats from "./DeliverableDetailsSummaryStats";
import DeliverableDetailsRightRail from "./DeliverableDetailsRightRail";
import { LuxDelFact, LuxDelFactGroup, LuxDelSection } from "./DeliverableLuxBlocks";
import { getDeliverableOverviewStats } from "./deliverableDetailsTab.utils";

class DeliverableDetailsGeneral extends Component {
  handleUpdateChecklist = (checklistData) => {
    store.dispatch(
      this.props.updateItemChecklistData(checklistData, this.props.item.id, "TASK")
    );
  };

  renderAccessControl = (item) => {
    const hasTeams =
      item.restrictedByUserTeamDetails && item.restrictedByUserTeamDetails.length > 0;
    const hasSkills =
      item.restrictedByEmployeeSkills && item.restrictedByEmployeeSkills.length > 0;
    const hasEmployees =
      item.restrictedByEmployeeDetails && item.restrictedByEmployeeDetails.length > 0;
    if (!hasTeams && !hasSkills && !hasEmployees) return null;

    return (
      <details className="lux-del-collapsible">
        <summary className="lux-del-collapsible__summary">
          <i className="fe fe-shield" aria-hidden="true" />
          <span>Access control</span>
          <i className="fe fe-chevron-down lux-del-collapsible__chevron" aria-hidden="true" />
        </summary>
        <div className="lux-del-collapsible__body">
          <div className="lux-del-fact-grid">
            {hasTeams && (
              <LuxDelFact
                wide
                label="Restricted by teams"
                value={item.restrictedByUserTeamDetails.map((t) => t.name).join(", ")}
              />
            )}
            {hasSkills && (
              <LuxDelFact
                wide
                label="Restricted by skills"
                value={item.restrictedByEmployeeSkills.join(", ")}
              />
            )}
            {hasEmployees && (
              <LuxDelFact
                wide
                label="Restricted by employees"
                value={item.restrictedByEmployeeDetails.map((e) => e.name).join(", ")}
              />
            )}
          </div>
        </div>
      </details>
    );
  };

  render() {
    const item = this.props.item;
    if (!item) return null;

    const { readOnly, permission } = this.props;
    const project = item.projectInfo || {};
    const tabStats = getDeliverableOverviewStats(
      item,
      this.props.workItemStatisticsByCategory
    );

    return (
      <div className="pd-workspace lux-del-overview">
        <main className="pd-workspace__main lux-del-overview__main">
        <ProjectDetailsTabShell
          icon="fe fe-layers"
          eyebrow="Deliverable"
          title="Overview"
          subtitle="Description, delivery attributes, project context, schedules, and team conversation."
          stats={tabStats}
        >
          <div className="lux-settings-tab__stack lux-del-overview__stack">
            {!readOnly && (
              <DeliverableDetailsSummaryStats
                items={this.props.workItemStatisticsByCategory}
                loadData={this.props.getWorkItemStatisticsByCategory}
                itemId={item.id}
              />
            )}

            <LuxDelSection
              icon="fe fe-align-left"
              title="About this deliverable"
              subtitle="What the team is expected to produce"
            >
              <p className="lux-del-about">
                {item.description ||
                  "No description yet — add context so your team knows what to deliver."}
              </p>
            </LuxDelSection>

            <LuxDelFactGroup tone="delivery" emoji="🎯" title="Delivery">
              <LuxDelFact label="Delivery category" value={item.category} />
              <LuxDelFact label="Task type" value={item.taskType} icon="fe fe-book-open" />
              <LuxDelFact label="Complexity" value={item.complexity} icon="fe fe-layers" />
              <LuxDelFact label="Priority" value={item.priority} icon="fe fe-flag" />
            </LuxDelFactGroup>

            <LuxDelFactGroup tone="project" emoji="💼" title="Project context">
              <LuxDelFact label="Project" value={project.name} icon="fe fe-briefcase" />
              <LuxDelFact label="Project category" value={project.category} />
              <LuxDelFact label="Project type" value={project.projectType} />
              <LuxDelFact
                label="Proposal no."
                value={project.proposalNumber}
                icon="fe fe-file-minus"
              />
              <LuxDelFact
                label="PO number"
                value={project.purchaseOrderNumber}
                icon="fe fe-target"
              />
              <LuxDelFact
                label="Order book ref"
                value={project.orderBookRef}
                icon="fe fe-bookmark"
              />
              <LuxDelFact label="Account" value={project.accountName} icon="fe fe-briefcase" />
              <LuxDelFact label="Team" value={project.teamName} icon="fe fe-users" />
              <LuxDelFact
                label="Clients"
                value={project.clientNames && project.clientNames.join(", ")}
              />
              <LuxDelFact label="Client partner" value={project.clientPartner} />
              <LuxDelFact label="Location" value={project.location} icon="fe fe-map-pin" />
              <LuxDelFact label="Capex / Opex" value={project.capexOpex} />
              <LuxDelFact label="Product" value={project.productName} />
            </LuxDelFactGroup>

            {!readOnly && (
              <>
                <LuxDelSection
                  icon="fe fe-repeat"
                  title="Recurring delivery"
                  subtitle="Automatically create work items for assignees on a repeating cadence"
                  flush
                >
                  <RecurringSelectionWindow
                    luxury
                    userTeamId={item.userTeamId}
                    itemId={item.id}
                    type="TASK"
                    scheduleType="ITEM_RECURRING"
                    readOnly={readOnly}
                  />
                </LuxDelSection>
                {this.renderAccessControl(item)}
              </>
            )}

            <LuxDelSection
              icon="fe fe-message-square"
              title="Comments & activity"
              subtitle="Discussion and audit trail for this deliverable"
              flush
            >
              <ItemCommentsSection itemId={item.id} subType="TASK" isReadOnly={readOnly} />
            </LuxDelSection>
          </div>
        </ProjectDetailsTabShell>
        </main>

        <DeliverableDetailsRightRail
          item={item}
          readOnly={readOnly}
          permission={permission}
          onUpdateChecklist={this.handleUpdateChecklist}
        />

        <ConfigureChecklistSidebar
          type="TASK"
          show={this.props.showChecklistModel}
          showConfigWindow={this.props.showChecklistModel}
          showChecklistQuestionsWindow={false}
        />
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  showChecklistModel: state.checklist.isShowConfigureChecklistSidebar,
});

const mapDispatchToProps = () => ({
  updateItemChecklistData: checklistActions.updateItemChecklistData,
});

export default connect(mapStateToProps, mapDispatchToProps)(DeliverableDetailsGeneral);
