import React, { Component } from "react";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { resolveLegacyEmptyPreset } from "views/common/fragments/luxEmptyStateLegacy.utils";

class ItemNotFoundSection extends Component {
  render() {
    const { items, isLoading, imgurl, text, description, eyebrow, hints, variant, className } =
      this.props;

    if ((items && items.length > 0) || isLoading) {
      return null;
    }

    const legacy = resolveLegacyEmptyPreset(imgurl);
    const resolvedVariant = variant || (legacy && legacy.variant) || "bid-requests";
    const resolvedEyebrow = eyebrow || (legacy && legacy.eyebrow);
    const resolvedHints = hints && hints.length ? hints : legacy && legacy.hints;

    return (
      <LuxRegisterEmptyState
        className={["lux-register-empty--compact", className].filter(Boolean).join(" ")}
        variant={resolvedVariant}
        eyebrow={resolvedEyebrow}
        title={text}
        description={description}
        hints={resolvedHints}
      />
    );
  }
}

export default ItemNotFoundSection;
