import React from "react";
import classNames from "classnames/bind";

export default function ProjectDetailsTabShell({ icon, eyebrow, title, subtitle, stats, children, className }) {
  return (
    <section className={classNames("lux-settings-tab", "lux-pd-tab", className)}>
      <header className="lux-settings-tab__head">
        <span className="lux-settings-tab__icon" aria-hidden="true">
          <i className={icon} />
        </span>
        <div className="lux-settings-tab__copy">
          {eyebrow && <span className="lux-settings-tab__eyebrow">{eyebrow}</span>}
          <h3 className="lux-settings-tab__title">{title}</h3>
          {subtitle && <p className="lux-settings-tab__subtitle">{subtitle}</p>}
        </div>
      </header>

      {stats && stats.length > 0 && (
        <div className="lux-settings-tab__stats" role="list" aria-label="Tab summary">
          {stats.map((stat) => (
            <article
              key={stat.key}
              className={classNames("lux-settings-tab__stat", stat.tone && `is-${stat.tone}`)}
              role="listitem"
            >
              <span className="lux-settings-tab__stat-label">{stat.label}</span>
              <strong className="lux-settings-tab__stat-value">{stat.value}</strong>
              {stat.hint && <span className="lux-settings-tab__stat-hint">{stat.hint}</span>}
            </article>
          ))}
        </div>
      )}

      <div className="lux-settings-tab__body lux-pd-tab__body">{children}</div>
    </section>
  );
}
