import React, { Component } from "react";
import Skeleton from "react-loading-skeleton";
import { createPortal } from "react-dom";
import { connect } from "react-redux";
import Select from "react-select";
import classNames from "classnames/bind";
import { store } from "_helpers";
import { commonUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";
import { projectActions } from "_actions";
import { workItemActions } from "_actions";
import { appConfigActions } from "_actions";

const TYPE_OPTIONS = [
  {
    value: "project",
    label: "Project",
    title: "Billable project",
    hint: "Log client or delivery project time",
    icon: "fe-briefcase",
    tone: "green",
  },
  {
    value: "nonProject",
    label: "Non Billable",
    title: "Non-billable",
    hint: "Leave, holiday, or internal work",
    icon: "fe-layers",
    tone: "blue",
  },
];

class TimesheetAddEntryModal extends Component {
  constructor() {
    super();
    this.state = {
      typeSelectionOption: null,
      categorySelectionOption: null,
      projectSelectionOption: null,
      nonBillableCategoryLoaded: false,
      reloadProjectAlways: true,
      startOfTheWeek: null,
    };
  }

  componentDidMount() {
    this.setState({ startOfTheWeek: this.props.startOfTheWeek });
    document.addEventListener("keydown", this.handleKeyDown);
    if (this.props.show) {
      this.lockPageScroll(true);
    }
  }

  componentDidUpdate(prevProps) {
    if (this.props.show !== prevProps.show) {
      this.lockPageScroll(this.props.show);
    }
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.handleKeyDown);
    this.lockPageScroll(false);
  }

  lockPageScroll = (lock) => {
    if (typeof document === "undefined") return;
    const body = document.body;
    if (lock) {
      this.scrollbarGap = window.innerWidth - document.documentElement.clientWidth;
      body.classList.add("lux-ts-add-entry-open");
      if (this.scrollbarGap > 0) {
        body.style.paddingRight = `${this.scrollbarGap}px`;
      }
    } else {
      body.classList.remove("lux-ts-add-entry-open");
      body.style.paddingRight = "";
    }
  };

  handleKeyDown = (event) => {
    if (event.key === "Escape" && this.props.show) {
      this.handleCancel();
    }
  };

  reloadProjectListService = () => {
    if (
      this.state.startOfTheWeek !== this.props.startOfTheWeek ||
      !this.props.projectsForTimesheet ||
      this.state.reloadProjectAlways
    ) {
      const selectedCurrentUserId = this.props.selectedEmployee.id;
      const selectedUserTeamId = this.props.selectedEmployee.userTeamId;
      const dateMoment = dateUtils.toDateToMoment(this.props.startOfTheWeek);
      const startDate = dateMoment.format(dateUtils.SERVER_DATE_FORMAT);
      const endDate = dateUtils.addXDays(dateMoment, 7).format(dateUtils.SERVER_DATE_FORMAT);
      const isOnlyUserTeams = this.props.permission.listOnlyCurrentTeamProject;
      store.dispatch(
        this.props.getProjectList({
          userTeamIds: [selectedUserTeamId],
          currentUserId: selectedCurrentUserId,
          startDate,
          endDate,
          isOnlyUserTeams,
        })
      );
      this.setState({ startOfTheWeek: this.props.startOfTheWeek });
    }
  };

  onTypeSelectionOption = (typeSelectionOption) => {
    this.setState({
      typeSelectionOption,
      categorySelectionOption: null,
      projectSelectionOption: null,
    });
    if (typeSelectionOption.value === "project") {
      this.reloadProjectListService();
    } else if (this.state.nonBillableCategoryLoaded === false) {
      store.dispatch(
        this.props.initializeNonProjectWorkItem(
          this.props.permission.timeSheetNonBillableShowAllAccountsEnabled === true,
          this.props.selectedEmployee.userTeamId
        )
      );
      store.dispatch(appConfigActions.getAllTeams(true));
      this.setState({ nonBillableCategoryLoaded: true });
    }
  };

  onChangeCategorySelection = (categorySelectionOption) => {
    this.setState({ categorySelectionOption });
  };

  onChangeProjectSelection = (projectSelectionOption) => {
    this.setState({ projectSelectionOption });
  };

  handleAddProjectForTimeEntry = () => {
    this.props.handleAddProjectForTimeEntry(
      this.state.typeSelectionOption,
      this.state.categorySelectionOption,
      this.state.projectSelectionOption
    );
    this.setState({
      projectSelectionOption: null,
      categorySelectionOption: null,
      typeSelectionOption: null,
    });
    this.props.cancelShowSelectionWindow();
  };

  handleCancel = () => {
    this.props.cancelShowSelectionWindow();
  };

  getCategoryOptions = () => {
    if (!this.props.nonProjectAppConfig) return [];
    const config = this.props.nonProjectAppConfig.find((item) => item.name === "taskActCategory");
    return [
      { value: "HOLIDAY", label: "Holiday" },
      { value: "LEAVE", label: "Leave" },
      ...(config ? commonUtils.convertConfigListToSelectObject(config.value) : []),
    ];
  };

  renderTypeCards = () => (
    <div className="lux-ts-add-entry__type-grid" role="radiogroup" aria-label="Entry type">
      {TYPE_OPTIONS.map((option) => {
        const isActive =
          this.state.typeSelectionOption && this.state.typeSelectionOption.value === option.value;
        return (
          <button
            key={option.value}
            type="button"
            role="radio"
            aria-checked={isActive}
            className={classNames("lux-ts-add-entry__type-card", `is-${option.tone}`, {
              "is-active": isActive,
            })}
            onClick={() => this.onTypeSelectionOption({ value: option.value, label: option.label })}
          >
            <span className="lux-ts-add-entry__type-icon" aria-hidden="true">
              <i className={`fe ${option.icon}`} />
            </span>
            <strong>{option.title}</strong>
            <span>{option.hint}</span>
          </button>
        );
      })}
    </div>
  );

  render() {
    if (!this.props.show) return null;
    if (typeof document === "undefined") return null;

    const { selectedEmployee, projectsForTimesheet } = this.props;
    const typeValue =
      this.state.typeSelectionOption && this.state.typeSelectionOption.value;
    const canAdd = !!(this.state.categorySelectionOption || this.state.projectSelectionOption);
    const employeeLabel =
      (selectedEmployee && (selectedEmployee.name || selectedEmployee.empName)) || "Employee";

    return createPortal(
      <div className="lux-ts-add-entry" role="dialog" aria-modal="true" aria-label="Add time entry">
        <button
          type="button"
          className="lux-ts-add-entry__backdrop"
          onClick={this.handleCancel}
          aria-label="Close add time entry"
        />
        <div className="lux-ts-add-entry__panel">
          <header className="lux-ts-add-entry__head">
            <div>
              <span className="lux-ts-add-entry__kicker">
                <i className="fe fe-plus-circle" aria-hidden="true" />
                New row
              </span>
              <h3 className="lux-ts-add-entry__title">Add time entry</h3>
              <p className="lux-ts-add-entry__sub">
                Choose what to log for <strong>{employeeLabel}</strong> this week
              </p>
            </div>
            <button
              type="button"
              className="lux-ts-add-entry__close"
              onClick={this.handleCancel}
              aria-label="Close"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <div className="lux-ts-add-entry__body">
            <section className="lux-ts-add-entry__section">
              <span className="lux-ts-add-entry__step">Step 1</span>
              <h4 className="lux-ts-add-entry__section-title">What are you logging?</h4>
              {this.renderTypeCards()}
            </section>

            {typeValue === "project" && (
              <section className="lux-ts-add-entry__section">
                <span className="lux-ts-add-entry__step">Step 2</span>
                <h4 className="lux-ts-add-entry__section-title">Select project</h4>
                <div className="lux-ts-add-entry__field">
                  <label className="lux-ts-add-entry__label" htmlFor="lux-ts-add-entry-project">
                    Project
                  </label>
                  <Select
                    inputId="lux-ts-add-entry-project"
                    isSearchable
                    isClearable={false}
                    placeholder="Search and select a project…"
                    classNamePrefix="custom-select"
                    isMulti={false}
                    menuPlacement="auto"
                    menuPortalTarget={document.body}
                    styles={{ menuPortal: (base) => ({ ...base, zIndex: 1000003 }) }}
                    value={this.state.projectSelectionOption}
                    onChange={this.onChangeProjectSelection}
                    options={
                      projectsForTimesheet &&
                      commonUtils.convertObjectToSelectObject(projectsForTimesheet)
                    }
                  />
                  {!projectsForTimesheet && (
                    <div className="lux-ts-add-entry__hint" aria-busy="true">
                      <Skeleton height={36} borderRadius={10} />
                    </div>
                  )}
                </div>
              </section>
            )}

            {typeValue === "nonProject" && this.props.nonProjectAppConfig && (
              <section className="lux-ts-add-entry__section">
                <span className="lux-ts-add-entry__step">Step 2</span>
                <h4 className="lux-ts-add-entry__section-title">Select category</h4>
                <div className="lux-ts-add-entry__field">
                  <label className="lux-ts-add-entry__label" htmlFor="lux-ts-add-entry-category">
                    Category
                  </label>
                  <Select
                    inputId="lux-ts-add-entry-category"
                    isSearchable
                    isClearable={false}
                    placeholder="Leave, holiday, or non-billable category…"
                    classNamePrefix="custom-select"
                    isMulti={false}
                    menuPlacement="auto"
                    menuPortalTarget={document.body}
                    styles={{ menuPortal: (base) => ({ ...base, zIndex: 1000003 }) }}
                    value={this.state.categorySelectionOption}
                    onChange={this.onChangeCategorySelection}
                    options={this.getCategoryOptions()}
                  />
                </div>
              </section>
            )}
          </div>

          <footer className="lux-ts-add-entry__foot">
            <p className="lux-ts-add-entry__foot-note">
              {canAdd
                ? "A new row will appear in the grid below — enter hours per day after adding."
                : "Pick a type, then choose a project or category to continue."}
            </p>
            <div className="lux-ts-add-entry__actions">
              <button type="button" className="lux-ts-add-entry__btn lux-ts-add-entry__btn--ghost" onClick={this.handleCancel}>
                Cancel
              </button>
              <button
                type="button"
                className="lux-ts-add-entry__btn lux-ts-add-entry__btn--primary"
                disabled={!canAdd}
                onClick={this.handleAddProjectForTimeEntry}
              >
                <i className="fe fe-plus" aria-hidden="true" />
                Add to timesheet
              </button>
            </div>
          </footer>
        </div>
      </div>,
      document.body
    );
  }
}

const mapStateToProps = (state) => ({
  projectsForTimesheet: state.projects.projectsForTimesheet,
  nonProjectAppConfig: state.workItem.nonProjectAppConfig,
});

const mapDispatchToProps = (dispatch) => ({
  getProjectList: projectActions.getProjectListForTimesheet,
  initializeNonProjectWorkItem: workItemActions.initializeNonProjectWorkItem,
});

export default connect(mapStateToProps, mapDispatchToProps)(TimesheetAddEntryModal);
