import React, { Component } from "react";
import Menu from "./fragments/Menu";
import BrandNameLogo from "./fragments/BrandNameLogo";
import envConfig from "env.config";
import { commonUtils } from "_helpers";

class PageLeftMenu extends Component {
  activeRoute(routeName) {
    return this.props.location.pathname.indexOf(routeName) > -1 ? "active" : "";
  }

  getCompanyLabel = () => {
    const user = commonUtils.getCurrentUser && commonUtils.getCurrentUser();
    const teamName = user && user.defaultUserTeamDetails && user.defaultUserTeamDetails.name;
    return teamName ? teamName : (envConfig.APP_LABEL || "Workspace");
  };

  render() {
    return (
      <div id="left-sidebar" className="sidebar no-print lux-sidebar">
        <div className="lux-sidebar__top">
          <div className="lux-sidebar__brand lux-sidebar__brand--logo">
            <BrandNameLogo />
          </div>
          <button
            type="button"
            className="d-none link menu_option lux-sidebar__grid-toggle"
            data-ga-action="menu_grid_list_toggle"
            data-ga-category="navigation"
            data-ga-label="Grid & List Toggle"
            title="Grid & List Toggle"
          >
            <i className="icon-grid font-16" data-toggle="tooltip" data-placement="left" title="Grid & List Toggle" />
          </button>
        </div>

        <div className="lux-company-chip">
          <span className="lux-company-chip__icon" aria-hidden="true">✦</span>
          <span className="lux-company-chip__label">{this.getCompanyLabel()}</span>
        </div>

        <nav id="left-sidebar-nav" className="sidebar-nav lux-sidebar__nav">
          <ul className="metismenu lux-nav">
            <li className="g_heading lux-nav__heading">Directories</li>
            {this.props.menuAccessControl && this.props.menuAccessControl.hrmsModules.active === true &&
              <Menu {...this.props} routes={this.props.routes} menuName={"HRMS"} layoutName="/hrms" icon={"fa fa-users"} />
            }
            {this.props.menuAccessControl && this.props.menuAccessControl.salesModules.active === true &&
              <Menu {...this.props} routes={this.props.routes} menuName={"Sales"} layoutName="/sales" icon={"icon-briefcase"} />
            }
            {this.props.menuAccessControl && this.props.menuAccessControl.projectModules.active === true &&
              <Menu {...this.props} routes={this.props.routes} menuName={"Project"} layoutName="/project" icon={"icon-rocket"} />
            }
          </ul>
        </nav>
      </div>
    );
  }
}

export default PageLeftMenu;
