import React, { Component } from "react";
import Select from "react-select";
import { connect } from "react-redux";
import { commonUtils } from "_helpers";
import ProjectEstimateAddLineModal from "../modal/ProjectEstimateAddLineModal";
import ProjectEstimateTeam from "./ProjectEstimateTeam";
import {
    getMonthRangeOptions,
    getAllTeamsGrandTotal,
    getTeamGrandTotal,
    countTeamLines,
    countTeamMonths,
} from "./projectEstimate.utils";

class ProjectEstimateInput extends Component {
    constructor() {
        super();
        this.state = {
            showEditor: false,
            showAddTeamOption: false,
            selectedTeamOption: null,
            draftEstimateRequest: null,
        };
    }

    getMonthOptions = () => getMonthRangeOptions(
        this.props.projectInfo.estStartTime,
        this.props.projectInfo.estCompletionTime
    );

    getEstimateData = () => this.state.draftEstimateRequest || this.props.projectEstimateRequest || {};

    openEditor = () => {
        this.setState({
            showEditor: true,
            draftEstimateRequest: this.props.projectEstimateRequest
                ? JSON.parse(JSON.stringify(this.props.projectEstimateRequest))
                : {},
        });
    };

    closeEditor = () => {
        this.setState({ showEditor: false, draftEstimateRequest: null, showAddTeamOption: false, selectedTeamOption: null });
    };

    syncDraft = (draft) => {
        this.setState({ draftEstimateRequest: draft }, () => {
            this.props.onChange(this.props.name, draft);
        });
    };

    onAddTeamsMonthlyEstimate = (teamId, teamEstimate) => {
        const draft = { ...this.getEstimateData(), [teamId]: { ...teamEstimate } };
        this.syncDraft(draft);
    };

    removeTeamFromEstimate = (teamIdToBeDeleted) => {
        const draft = { ...this.getEstimateData() };
        delete draft[teamIdToBeDeleted];
        this.syncDraft(draft);
    };

    handleSave = () => {
        this.props.handleUpdateEstimate();
        this.closeEditor();
    };

    toggleAddTeamOption = (isShow) => {
        this.setState({ showAddTeamOption: isShow, selectedTeamOption: null });
    };

    addTeamForEstimate = () => {
        if (this.state.selectedTeamOption) {
            this.onAddTeamsMonthlyEstimate(this.state.selectedTeamOption.value, {
                teamName: this.state.selectedTeamOption.label,
                estimates: {},
            });
        }
        this.setState({ selectedTeamOption: null, showAddTeamOption: false });
    };

    getAvailableTeams = () => {
        const data = this.getEstimateData();
        const teams = this.props.userTeams || [];
        return teams.filter((userTeam) => !data[userTeam.id]);
    };

    renderSummary = () => {
        const data = this.props.projectEstimateRequest;
        const monthOptions = this.getMonthOptions();
        const teamIds = data ? Object.keys(data) : [];
        const grandTotal = getAllTeamsGrandTotal(data, "estimate", monthOptions);
        const { projectItem, readOnly } = this.props;

        return (
            <article className="pd-estimates">
                <header className="pd-estimates__head">
                    <span className="pd-estimates__icon"><i className="fe fe-pie-chart" /></span>
                    <div className="pd-estimates__titles">
                        <h2 className="pd-estimates__title">Team estimates</h2>
                        <p className="pd-estimates__subtitle">Monthly resource planning by team</p>
                    </div>
                    {!readOnly &&
                        <button type="button" className="lux-estimate-btn lux-estimate-btn--primary lux-estimate-btn--sm" onClick={this.openEditor}>
                            <i className="fe fe-edit-2" /> Manage
                        </button>
                    }
                </header>

                <div className="pd-estimates__hero-stat">
                    <span className="pd-estimates__hero-value">{grandTotal}</span>
                    <span className="pd-estimates__hero-label">Total estimated hours</span>
                </div>

                {teamIds.length === 0 &&
                    <div className="pd-estimates__empty">
                        <i className="fe fe-layers" />
                        <p>No team estimates yet</p>
                        {!readOnly &&
                            <button type="button" className="lux-estimate-btn lux-estimate-btn--ghost" onClick={this.openEditor}>
                                Add first estimate
                            </button>
                        }
                    </div>
                }

                {teamIds.length > 0 &&
                    <div className="pd-estimates__teams">
                        {teamIds.map((teamId) => {
                            const team = data[teamId];
                            const total = getTeamGrandTotal(team, "estimate", monthOptions);
                            return (
                                <div key={teamId} className="pd-estimates__team-row">
                                    <div className="pd-estimates__team-info">
                                        <span className="pd-estimates__team-name">{team.teamName}</span>
                                        <span className="pd-estimates__team-meta">
                                            {countTeamMonths(team)} months · {countTeamLines(team)} lines
                                        </span>
                                    </div>
                                    <span className="pd-estimates__team-hours">{total}h</span>
                                </div>
                            );
                        })}
                    </div>
                }

                {projectItem.automationEnabled && teamIds.length > 0 &&
                    <div className="pd-estimates__extra">
                        <span>With tool: {getAllTeamsGrandTotal(data, "estimateAutomation", monthOptions)}h</span>
                        {projectItem.revisedEstEnabled &&
                            <span>Revised: {getAllTeamsGrandTotal(data, "estimateRevised", monthOptions)}h</span>
                        }
                    </div>
                }
            </article>
        );
    };

    renderEditor = () => {
        if (!this.state.showEditor) return null;

        const draft = this.getEstimateData();
        const teamIds = Object.keys(draft);
        const availableTeams = this.getAvailableTeams();

        return (
            <div className={`right_sidebar lux-estimate-sidebar ${this.state.showEditor ? "open" : ""}`}>
                <div className="lux-estimate-sidebar__shell">
                    <header className="lux-estimate-sidebar__head">
                        <div>
                            <span className="lux-estimate-sidebar__kicker">Resource planning</span>
                            <h2 className="lux-estimate-sidebar__title">Team estimates</h2>
                        </div>
                        <button type="button" className="pd-icon-btn link" onClick={this.closeEditor} aria-label="Close">
                            <i className="fe fe-x" />
                        </button>
                    </header>

                    <div className="lux-estimate-sidebar__body">
                        {teamIds.length === 0 &&
                            <div className="pd-estimates__empty pd-estimates__empty--sidebar">
                                <i className="fe fe-users" />
                                <p>Add a team to start building monthly estimates</p>
                            </div>
                        }

                        {teamIds.map((teamId) =>
                            <ProjectEstimateTeam
                                key={teamId}
                                editable
                                projectInfo={this.props.projectInfo}
                                teamProjectEstimate={draft[teamId]}
                                teamId={teamId}
                                onAddTeamEstimate={this.onAddTeamsMonthlyEstimate}
                                removeTeamFromEstimate={this.removeTeamFromEstimate}
                                projectItem={this.props.projectItem}
                                userTeams={this.props.userTeams}
                            />
                        )}

                        {this.state.showAddTeamOption && availableTeams.length > 0 &&
                            <div className="lux-estimate-add-team">
                                <label className="lux-estimate-field__label">Add team</label>
                                <Select
                                    isSearchable
                                    isClearable
                                    placeholder="Select team"
                                    classNamePrefix="custom-select"
                                    menuPlacement="auto"
                                    value={this.state.selectedTeamOption}
                                    onChange={(opt) => this.setState({ selectedTeamOption: opt })}
                                    options={commonUtils.convertObjectToSelectObject(availableTeams)}
                                />
                                <div className="lux-estimate-add-team__actions">
                                    <button type="button" className="lux-estimate-btn lux-estimate-btn--primary lux-estimate-btn--sm" onClick={this.addTeamForEstimate}>
                                        Add team
                                    </button>
                                    <button type="button" className="lux-estimate-btn lux-estimate-btn--ghost lux-estimate-btn--sm" onClick={() => this.toggleAddTeamOption(false)}>
                                        Cancel
                                    </button>
                                </div>
                            </div>
                        }

                        {!this.state.showAddTeamOption && availableTeams.length > 0 &&
                            <button type="button" className="lux-estimate-add-team-btn" onClick={() => this.toggleAddTeamOption(true)}>
                                <i className="fe fe-plus-circle" /> Add another team
                            </button>
                        }
                    </div>

                    <footer className="lux-estimate-sidebar__foot">
                        <button type="button" className="lux-estimate-btn lux-estimate-btn--ghost" onClick={this.closeEditor}>
                            Cancel
                        </button>
                        <button type="button" className="lux-estimate-btn lux-estimate-btn--primary" onClick={this.handleSave}>
                            <i className="fe fe-check" /> Save estimates
                        </button>
                    </footer>
                </div>
            </div>
        );
    };

    render() {
        return (
            <>
                {this.renderSummary()}
                {this.renderEditor()}
            </>
        );
    }
}

export default connect()(ProjectEstimateInput);
