const CHART_FONT = "Inter, system-ui, sans-serif";

function toDonut(labels, series, colors) {
  return {
    type: "donut",
    height: 168,
    series,
    options: {
      chart: { toolbar: { show: false }, fontFamily: CHART_FONT },
      labels,
      colors,
      legend: { position: "bottom", fontSize: "11px" },
      dataLabels: { enabled: false },
      stroke: { width: 0 },
      plotOptions: { pie: { donut: { size: "68%" } } },
    },
  };
}

function toBar(categories, data, color = "#5b5ff4") {
  return {
    type: "bar",
    height: 168,
    series: [{ name: "Tasks", data }],
    options: {
      chart: { toolbar: { show: false }, fontFamily: CHART_FONT },
      plotOptions: { bar: { borderRadius: 6, columnWidth: "55%" } },
      colors: [color],
      xaxis: { categories, labels: { style: { fontSize: "10px" } } },
      legend: { show: false },
      grid: { borderColor: "rgba(148,163,184,0.12)" },
    },
  };
}

export function buildTaskBoardStageDonutChart(stat) {
  const labels = ["Planned", "To do", "In progress", "Done"];
  const data = [
    stat.byStage[1] || 0,
    stat.byStage[2] || 0,
    stat.byStage[3] || 0,
    stat.byStage[4] || 0,
  ];
  if (!data.some((v) => v > 0)) return null;
  return toDonut(labels, data, ["#94a3b8", "#0ea5e9", "#f59e0b", "#10b981"]);
}

export function buildTaskBoardTypeDonutChart(stat) {
  const labels = ["Billable", "Non-project", "Other"];
  const data = [stat.byType.PROJECT, stat.byType.NON_PROJECT, stat.byType.OTHER];
  if (!data.some((v) => v > 0)) return null;
  return toDonut(labels, data, ["#5b5ff4", "#14b8a6", "#94a3b8"]);
}

export function buildTaskBoardCategoryBarChart(stat) {
  const entries = stat.categoryEntries || [];
  if (!entries.length) return null;
  return toBar(
    entries.map(([k]) => (k.length > 14 ? `${k.slice(0, 12)}…` : k)),
    entries.map(([, v]) => v),
    "#6366f1"
  );
}

export function buildTaskBoardFlowBarChart(stat) {
  return buildTaskBoardStageDonutChart(stat)
    ? {
        type: "bar",
        height: 140,
        series: [
          {
            name: "Tasks",
            data: [stat.plannedCount, stat.todoCount, stat.inProgressCount, stat.completedCount],
          },
        ],
        options: {
          chart: { toolbar: { show: false }, fontFamily: CHART_FONT },
          plotOptions: { bar: { horizontal: true, borderRadius: 6, distributed: true } },
          colors: ["#94a3b8", "#0ea5e9", "#f59e0b", "#10b981"],
          xaxis: { categories: ["Planned", "To do", "In progress", "Done"] },
          legend: { show: false },
          dataLabels: { enabled: true, style: { fontSize: "11px" } },
        },
      }
    : null;
}
