import classNames from "classnames/bind";
import moment from "moment";
import React, { Component } from "react";
import { connect } from "react-redux";
import CreateHolidayModel from "views/project/components/modal/CreateHolidayModel";
import LuxActivityPanelEmptyState from "views/common/fragments/LuxActivityPanelEmptyState";
import { employeeActions } from "_actions";
import { employeeConstants } from "_constants";
import { commonUtils } from "_helpers";
import { accessUtils } from "_helpers";
import { store } from "_helpers";
import dateUtils from "_helpers/date.utils";
import {
  readPanelCollapsed,
  writePanelCollapsed,
} from "_helpers/panelCollapsedStorage";

const HOLIDAYS_COLLAPSED_STORAGE_KEY = "famstack-activity-holidays-collapsed";

function getHolidayDateMeta(holidayDate) {
    const date = moment(holidayDate);
    const today = moment().startOf("day");
    const diff = date.diff(today, "days");

    if (diff < 0) {
        return { tone: "slate", badge: "Past", relative: date.fromNow() };
    }
    if (diff === 0) {
        return { tone: "green", badge: "Today", relative: "Today" };
    }
    if (diff === 1) {
        return { tone: "amber", badge: "Tomorrow", relative: "Tomorrow" };
    }
    if (diff <= 7) {
        return { tone: "sky", badge: "This week", relative: `In ${diff} days` };
    }
    return { tone: "indigo", badge: "Upcoming", relative: `In ${diff} days` };
}

function summarizeHolidays(items) {
    const list = items || [];
    const today = moment().startOf("day");
    let upcoming = 0;
    let thisMonth = 0;
    let nextHoliday = null;

    list.forEach((item) => {
        const date = moment(item.holidayDate);
        if (date.isSameOrAfter(today, "day")) {
            upcoming += 1;
            if (!nextHoliday || date.isBefore(nextHoliday.date)) {
                nextHoliday = { date, name: item.name };
            }
        }
        if (date.isSame(today, "month")) {
            thisMonth += 1;
        }
    });

    return { total: list.length, upcoming, thisMonth, nextHoliday };
}

class HolidayListTable extends Component {
    constructor() {
        super();
        this.state = {
            permission: accessUtils.getHolidayAccessControl(),
            minimize: readPanelCollapsed(HOLIDAYS_COLLAPSED_STORAGE_KEY, true),
        };
    }

    onCreateItemClick = () => {
        this.setState({ editMode: false });
        store.dispatch(employeeActions.getModuleConfig(commonUtils.getCurrentUserTeamId()));
        store.dispatch({ type: employeeConstants.SHOW_HOLIDAY_CREATE_WINDOW });
    };

    onCloseCreateItem = () => {
        store.dispatch({ type: employeeConstants.CLOSE_HOLIDAY_CREATE_WINDOW });
    };

    handleDeleteHoliday = (holidayIdTobeDeleted, isDelete) => {
        store.dispatch(this.props.deleteHoliday(holidayIdTobeDeleted, isDelete));
    };

    handleEditHoliday = (holidayId) => {
        this.setState({ editMode: true });
        store.dispatch(this.props.getHolidayInfo(holidayId));
    };

    handleMinimizeHoliday = (minimize) => {
        this.setState({ minimize }, function () {
            writePanelCollapsed(HOLIDAYS_COLLAPSED_STORAGE_KEY, this.state.minimize);
        });
    };

    handleRemoveHoliday = (holidayId) => {
        store.dispatch(this.props.removeHoliday(holidayId));
    };

    handleSubmit = (holidayRequest, isEdtiMode, isCreateAnotherEnabled, callbackFunction) => {
        if (isEdtiMode) {
            store.dispatch(this.props.updateHoliday(holidayRequest));
        } else {
            store.dispatch(this.props.createHoliday(holidayRequest, isCreateAnotherEnabled, callbackFunction));
        }
    };

    render() {
        const items = this.props.items || [];
        const summary = summarizeHolidays(items);
        const sortedItems = [...items].sort((a, b) =>
            moment(a.holidayDate).valueOf() - moment(b.holidayDate).valueOf()
        );

        return (
            <section
                className={classNames("lux-activity-holidays", { "is-collapsed": this.state.minimize })}
                aria-label="Organization holidays"
            >
                <header className="lux-activity-holidays__head">
                    <div className="lux-activity-holidays__head-main">
                        <h3 className="lux-activity-holidays__title">
                            Organization Holidays
                            <span className="lux-activity-holidays__count">{summary.total}</span>
                        </h3>
                        {!this.state.minimize && summary.total > 0 && (
                            <div className="lux-activity-holidays__stats">
                                {summary.upcoming > 0 && (
                                    <span className="lux-activity-holidays__stat is-green">
                                        <i className="fe fe-calendar" aria-hidden="true" />
                                        {summary.upcoming} upcoming
                                    </span>
                                )}
                                {summary.thisMonth > 0 && (
                                    <span className="lux-activity-holidays__stat is-sky">
                                        {summary.thisMonth} this month
                                    </span>
                                )}
                                {summary.nextHoliday && (
                                    <span className="lux-activity-holidays__stat is-indigo" title={summary.nextHoliday.name}>
                                        Next {summary.nextHoliday.date.format("DD MMM")}
                                    </span>
                                )}
                            </div>
                        )}
                    </div>
                    <div className="lux-project-row__actions">
                        {!this.state.minimize && (
                            <button
                                type="button"
                                className="lux-project-row__action"
                                onClick={() => this.onCreateItemClick()}
                                title="Add holiday"
                                aria-label="Add holiday"
                                aria-haspopup="dialog"
                                aria-expanded={this.props.showCreateModel === true}
                            >
                                <i className="fe fe-plus" aria-hidden="true" />
                            </button>
                        )}
                        <button
                            type="button"
                            className="lux-project-row__action"
                            onClick={() => this.handleMinimizeHoliday(!this.state.minimize)}
                            aria-expanded={!this.state.minimize}
                            aria-label={this.state.minimize ? "Expand holidays" : "Collapse holidays"}
                        >
                            <i className={`fe ${this.state.minimize ? "fe-chevron-down" : "fe-chevron-up"}`} aria-hidden="true" />
                        </button>
                    </div>
                </header>

                {this.props.showCreateModel && (
                    <CreateHolidayModel
                        onCloseCreateItem={this.onCloseCreateItem}
                        show={this.props.showCreateModel}
                        editMode={this.state.editMode === true}
                        selectedHolidayInfo={this.props.selectedHolidayInfo}
                        handleSubmit={this.handleSubmit}
                    />
                )}

                {!this.state.minimize && (
                    <div className="lux-activity-holidays__body">
                        {sortedItems.length > 0 && (
                            <ul className="lux-activity-holidays__list">
                                {sortedItems.map((item) => (
                                    <HolidayItemInfo
                                        key={item.id}
                                        item={item}
                                        permission={this.state.permission}
                                        removeHoliday={this.handleRemoveHoliday}
                                    />
                                ))}
                            </ul>
                        )}

                        {sortedItems.length === 0 && (
                            <LuxActivityPanelEmptyState
                                variant="holidays"
                                eyebrow="Team calendar"
                                title="No holidays scheduled"
                                description="Organization-wide holidays appear here and on the activity calendar."
                                hints={[
                                    "Add holidays for your team locations",
                                    "Dates sync with the sidebar calendar",
                                    "Employees see holidays when booking time",
                                ]}
                            />
                        )}
                    </div>
                )}
            </section>
        );
    }
}

class HolidayItemInfo extends Component {
    constructor() {
        super();
        this.state = {
            confrimDelete: false,
        };
    }

    handleRemoveHoliday = (isConfrimDelete) => {
        if (isConfrimDelete) {
            this.props.removeHoliday(this.props.item.id);
        } else {
            this.setState({ confrimDelete: true });
        }
    };

    render() {
        const { item } = this.props;
        const holidayMoment = dateUtils.convertDateToMoment(item.holidayDate);
        const dateMeta = getHolidayDateMeta(item.holidayDate);
        const locationCount = (item.locations && item.locations.length) || 0;

        return (
            <li className="lux-activity-holidays__item">
                <div className={classNames("lux-activity-holidays__date", `is-${dateMeta.tone}`)}>
                    <span className="lux-activity-holidays__date-day">{holidayMoment.format("DD")}</span>
                    <span className="lux-activity-holidays__date-month">{holidayMoment.format("MMM")}</span>
                    <span className="lux-activity-holidays__date-week">{holidayMoment.format("ddd")}</span>
                </div>

                <div className="lux-activity-holidays__copy">
                    <div className="lux-activity-holidays__item-top">
                        <span className="lux-activity-holidays__name">{item.name}</span>
                        <span className={classNames("lux-activity-holidays__badge", `is-${dateMeta.tone}`)}>
                            {dateMeta.badge}
                        </span>
                    </div>
                    {item.description && (
                        <p className="lux-activity-holidays__desc">{item.description}</p>
                    )}
                    <div className="lux-activity-holidays__meta">
                        <span className="lux-activity-holidays__chip is-muted">{dateMeta.relative}</span>
                        {locationCount > 0 && (
                            <span className="lux-activity-holidays__chip">
                                <i className="fa fa-map-marker" aria-hidden="true" />
                                {locationCount === 1 ? item.locations[0] : `${locationCount} locations`}
                            </span>
                        )}
                    </div>
                    {locationCount > 1 && (
                        <div className="lux-activity-holidays__locations">
                            {item.locations.map((location) => (
                                <span key={location} className="lux-activity-holidays__location">
                                    <i className="fa fa-map-marker" aria-hidden="true" />
                                    {location}
                                </span>
                            ))}
                        </div>
                    )}
                </div>

                {this.props.permission.removeEnabled === true && (
                    <button
                        type="button"
                        className="lux-project-row__action is-danger"
                        title={this.state.confrimDelete ? "Confirm remove" : "Remove holiday"}
                        aria-label={this.state.confrimDelete ? "Confirm remove holiday" : "Remove holiday"}
                        onClick={() => this.handleRemoveHoliday(this.state.confrimDelete)}
                    >
                        {this.state.confrimDelete ? (
                            <i className="fe fe-check blink_text" aria-hidden="true" />
                        ) : (
                            <i className="fe fe-trash-2" aria-hidden="true" />
                        )}
                    </button>
                )}
            </li>
        );
    }
}

const mapStateToProps = (state) => ({
    items: state.employees.holidayItems,
    showCreateModel: state.employees.showHolidayCreateModel,
});

const mapDispatchToProps = (dispatch) => ({
    getHolidays: employeeActions.getHolidayLeavesForCalendar,
    createHoliday: employeeActions.createHolidayItem,
    removeHoliday: employeeActions.removeHolidayItem,
});

export default connect(mapStateToProps, mapDispatchToProps)(HolidayListTable);
