import React, { Component } from "react";
import PageInnerHeader from "views/common/PageInnerHeader";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxRegisterPagination from "views/common/fragments/LuxRegisterPagination";
import {
  paginateRegisterList,
  REGISTER_DEFAULT_PAGE_SIZE,
  REGISTER_PAGE_SIZE_OPTIONS,
} from "_helpers/registerPagination.utils";
import FileManagerPageSummary from "./components/filemanager/FileManagerPageSummary";
import FileManagerRecentStrip from "./components/filemanager/FileManagerRecentStrip";
import FileManagerToolbar from "./components/filemanager/FileManagerToolbar";
import FileManagerListTable from "./components/filemanager/FileManagerListTable";
import FileManagerGridView from "./components/filemanager/FileManagerGridView";
import {
  FILE_MANAGER_ROOT_ID,
  getAllFileManagerItems,
  getRecentFileManagerItems,
  getFolderBreadcrumb,
  filterFileManagerItems,
  buildFileManagerSummary,
} from "./components/filemanager/fileManager.utils";

class FileManagerPage extends Component {
  constructor() {
    super();
    this.allItems = getAllFileManagerItems();
    this.state = {
      currentFolderId: FILE_MANAGER_ROOT_ID,
      viewMode: "list",
      page: 1,
      pageSize: REGISTER_DEFAULT_PAGE_SIZE,
      filterOptions: {
        SHOW: {
          options: [
            { name: "ALL", label: "All" },
            { name: "FOLDERS", label: "Folders" },
            { name: "FILES", label: "Files" },
            { name: "SHARED", label: "Shared" },
            { name: "MINE", label: "Mine" },
          ],
          selected: "ALL",
        },
        SORT: {
          options: [
            { name: "NAME", label: "Name" },
            { name: "DATE", label: "Last updated" },
            { name: "SIZE", label: "Size" },
          ],
          selected: "NAME",
          directionUp: true,
        },
        filterText: null,
      },
    };
  }

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
  }

  getVisibleItems = () => {
    return filterFileManagerItems(this.allItems, {
      parentId: this.state.currentFolderId,
      filterOptions: this.state.filterOptions,
    });
  };

  getSummaryItems = () => {
    if (this.state.currentFolderId === FILE_MANAGER_ROOT_ID) {
      return this.allItems;
    }
    const descendants = new Set([this.state.currentFolderId]);
    let changed = true;
    while (changed) {
      changed = false;
      this.allItems.forEach((item) => {
        if (descendants.has(item.parentId) && !descendants.has(item.id)) {
          descendants.add(item.id);
          changed = true;
        }
      });
    }
    return this.allItems.filter((i) => descendants.has(i.id));
  };

  handleFilterChange = (filterOptions) => {
    this.setState({ filterOptions, page: 1 });
  };

  onFilterTextChange = (value) => {
    const next = {
      ...this.state.filterOptions,
      filterText: value,
    };
    this.handleFilterChange(next);
  };

  handleSummaryQuickFilter = (showValue) => {
    const next = {
      ...this.state.filterOptions,
      SHOW: { ...this.state.filterOptions.SHOW, selected: showValue },
    };
    this.handleFilterChange(next);
  };

  handlePageChange = (page) => {
    this.setState({ page });
  };

  handlePageSizeChange = (pageSize) => {
    this.setState({ pageSize, page: 1 });
  };

  handleNavigateFolder = (folderId) => {
    this.setState({ currentFolderId: folderId, page: 1 });
  };

  handleOpenItem = (item) => {
    if (item.type === "folder") {
      this.handleNavigateFolder(item.id);
    }
  };

  handleViewModeChange = (viewMode) => {
    this.setState({ viewMode });
  };

  handleUpload = () => {
    window.alert("Upload will connect to your document service when enabled.");
  };

  handleNewFolder = () => {
    window.alert("New folder creation will be available when document storage is connected.");
  };

  handleDownload = () => {
    window.alert("Download will be available when document storage is connected.");
  };

  handleShare = () => {
    window.alert("Sharing controls will be available when document storage is connected.");
  };

  handleRename = () => {
    window.alert("Rename will be available when document storage is connected.");
  };

  handleDelete = () => {
    window.alert("Remove will be available when document storage is connected.");
  };

  getCurrentFolderName = (breadcrumb) => {
    if (!breadcrumb || breadcrumb.length === 0) return "All files";
    return breadcrumb[breadcrumb.length - 1].name;
  };

  render() {
    const visibleItems = this.getVisibleItems();
    const summaryItems = this.getSummaryItems();
    const summaryStat = buildFileManagerSummary(summaryItems);
    const pagination = paginateRegisterList(visibleItems, this.state.page, this.state.pageSize);
    const pageItems = pagination.items;
    const breadcrumb = getFolderBreadcrumb(this.state.currentFolderId, this.allItems);
    const currentFolderName = this.getCurrentFolderName(breadcrumb);
    const recentItems =
      this.state.currentFolderId === FILE_MANAGER_ROOT_ID
        ? getRecentFileManagerItems(this.allItems)
        : getRecentFileManagerItems(visibleItems);

    const showRecent =
      this.state.currentFolderId === FILE_MANAGER_ROOT_ID &&
      !this.state.filterOptions.filterText &&
      this.state.filterOptions.SHOW.selected === "ALL";

    return (
      <div className="lux-file-manager lux-bid-requests">
        <PageInnerHeader
          showFilter
          stickytop={false}
          isLoading={false}
          showUserTeamMenu={false}
          filterOptions={this.state.filterOptions}
          handleFilterChange={this.handleFilterChange}
          onFilterTextChange={this.onFilterTextChange}
          showCreateMenu
          showCreateMenuText="Upload file"
          createItemHandler={this.handleUpload}
        />

        <FileManagerPageSummary
          stat={summaryStat}
          visibleCount={visibleItems.length}
          filterOptions={this.state.filterOptions}
          isLoading={false}
          currentFolderName={currentFolderName}
          onQuickFilter={this.handleSummaryQuickFilter}
        />

        {showRecent && recentItems.length > 0 && (
          <FileManagerRecentStrip items={recentItems} onOpenItem={this.handleOpenItem} />
        )}

        <FileManagerToolbar
          breadcrumb={breadcrumb}
          viewMode={this.state.viewMode}
          onViewModeChange={this.handleViewModeChange}
          onNavigate={this.handleNavigateFolder}
          onUpload={this.handleUpload}
          onNewFolder={this.handleNewFolder}
        />

        {visibleItems.length > 0 && (
          <div className="lux-register-list-section">
            {this.state.viewMode === "list" ? (
              <FileManagerListTable
                items={pageItems}
                totalCount={pagination.total}
                isLoading={false}
                pagination={pagination}
                onPageChange={this.handlePageChange}
                onPageSizeChange={this.handlePageSizeChange}
                onOpenItem={this.handleOpenItem}
                onDownload={this.handleDownload}
                onShare={this.handleShare}
                onRename={this.handleRename}
                onDelete={this.handleDelete}
              />
            ) : (
              <div className="lux-file-grid-wrap">
                <FileManagerGridView
                  items={pageItems}
                  onOpenItem={this.handleOpenItem}
                  onDownload={this.handleDownload}
                  onShare={this.handleShare}
                />
                {pagination.total > 0 && (
                  <LuxRegisterPagination
                    pagination={pagination}
                    onPageChange={this.handlePageChange}
                    onPageSizeChange={this.handlePageSizeChange}
                    pageSizeOptions={REGISTER_PAGE_SIZE_OPTIONS}
                    summaryLabel="items"
                    className="lux-register-list__pagination"
                  />
                )}
              </div>
            )}
          </div>
        )}

        {visibleItems.length === 0 && (
          <LuxRegisterEmptyState
            variant="files"
            eyebrow="File workspace"
            title="No files in this view"
            description="Nothing matches your filters or this folder is empty. Try another folder, clear search, or upload a file to get started."
            hints={[
              "Use quick filters in the summary to show shared or owned files",
              "Folders open in-place — breadcrumb shows your path",
              "Grid view offers a visual layout for folders and documents",
            ]}
            createLabel="Upload file"
            onCreate={this.handleUpload}
            showCreate
            secondaryLabel="New folder"
            onSecondary={this.handleNewFolder}
            showSecondary
            secondaryIcon="fe fe-folder-plus"
          />
        )}
      </div>
    );
  }
}

export default FileManagerPage;
