import React, { Component } from "react";
import classNames from "classnames/bind";
import { connect } from "react-redux";
import CronJobSelectionMenu from "views/common/fragments/CronJobSelectionMenu";
import CustomInput from "views/common/fragments/formfields/CustomInput";
import { taskActions } from "_actions";
import { employeeActions } from "_actions";
import { scheduleActions } from "_actions";
import { scheduleConstants } from "_constants";
import { commonUtils } from "_helpers";
import { store } from "_helpers";
import { validationUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";

class RecurringSelectionWindow extends Component {
    constructor() {
        super();
        this.state = {
            showCroDropdownMenu: false,
            cronValue: "0 05 0 ? * MON-FRI *",
            cronString: "At 12:05 AM, Monday Through Friday",
            formErrors: {}
        }
    }
    componentDidMount() {

        this.setState({
            scheduleRequest: {
                "userTeamId": this.props.userTeamId,
                "scheduleType": this.props.scheduleType,
                "itemId": this.props.itemId,
                "cronValue": "0 05 0 ? * MON-FRI",
                "cronString": "At 12:05 AM, Monday Through Friday",
                "recurringInfo": {
                    "type": this.props.type
                }
            }
        })
        this.handleGetAllProjectScheulers();
    }
    onCreateAnotherEnabled = (value) => {
        this.setState({
            createAnotherEnabled: value
        })
    }

    toggleEditOption = (value) => {
        if (value === true) {
            if(this.props.type === 'PROJECT') {
                store.dispatch(this.props.getAllRecurrableTasks({ projectId: this.props.itemId }));
            }
            if(this.props.type === 'TASK') {
                store.dispatch(this.props.getAllEmployees());
            }
        }
        store.dispatch({ type: value ? scheduleConstants.SHOW_CREATE_SCHEDULES_WINDOW : scheduleConstants.CLOSE_CREATE_SCHEDULES_WINDOW });
    }

    onFormError = (fieldName, hasError) => {
        this.setState(prevState => ({
            formErrors: {
                ...prevState.formErrors,
                [fieldName]: hasError
            }
        }))
    }

    onChange = (fieldName, value) => {
        this.setState(prevState => ({
            scheduleRequest: {
                ...prevState.scheduleRequest,
                [fieldName]: value
            }
        }))
    }

    onRecurringInfoChange = (fieldName, value) => {
        this.setState(prevState => ({
            scheduleRequest: {
                ...prevState.scheduleRequest,
                recurringInfo: {
                    ...prevState.scheduleRequest.recurringInfo,
                    [fieldName]: value
                }
            }
        }))
    }

    toggeleCronMenu = (isShow) => {
        this.setState(prevState => ({
            showCroDropdownMenu: isShow
        }))
    }

    onCronValueChange = (cronValue, cronString) => {
        this.setState(prevState => ({
            cronValue,
            cronString,
            scheduleRequest: {
                ...prevState.scheduleRequest,
                "cronString": cronString,
                "cronValue": cronValue.substr(0, cronValue.length - 1)
            }
        }))
        this.toggeleCronMenu(false);
    }
    handleGetAllProjectScheulers = () => {
        store.dispatch(this.props.getSchedules({ itemId: this.props.itemId, userTeamId: this.props.userTeamId, type: this.props.type, scheduleType: this.props.scheduleType }));
    }
    handleSubmit = () => {
        let isValid = validationUtils.isValidRequest(this.props.fieldConfig, this.state.scheduleRequest, this.state.formErrors);
        //console.log("Validating form  request, isValid - " + isValid);
        if (isValid) {
            store.dispatch(this.props.createScheule(this.state.scheduleRequest, this.props.scheduleType));
        }
    }

    handleEnable = (itemId, isEnabled) => {
        store.dispatch(this.props.enableSchedule({ itemId, isEnabled }));
    }
    handleRemove = (itemId) => {
        store.dispatch(this.props.removeSchedule({ itemId }));
    }

    getChildItemsLabel = () => {
        if (this.props.type === "PROJECT") {
            return { label: "Deliverables to include", placeholder: "Select deliverables…" };
        }
        return { label: "Assignees", hint: "8 hrs default per assignee", placeholder: "Select team members…" };
    };

    renderLuxuryCronPicker = () => (
        <div className="lux-recurring-panel__cron">
            <p className="lux-recurring-panel__field-label">
              Schedule <span className="form-required">*</span>
            </p>
            <div className="lux-feedback-config-cron lux-recurring-panel__cron-control">
              <button
                type="button"
                className="lux-feedback-config-cron__btn"
                onClick={() => this.toggeleCronMenu(!this.state.showCroDropdownMenu)}
                aria-label="Edit schedule"
              >
                <i className="fe fe-repeat" aria-hidden="true" />
              </button>
              <span
                className="lux-feedback-config-cron__value lux-recurring-panel__cron-value"
                role="button"
                tabIndex={0}
                onClick={() => this.toggeleCronMenu(!this.state.showCroDropdownMenu)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    this.toggeleCronMenu(!this.state.showCroDropdownMenu);
                  }
                }}
              >
                {this.state.cronString}
              </span>
              <CronJobSelectionMenu
                showDropDown={this.state.showCroDropdownMenu}
                closeDropDwonMenu={this.toggeleCronMenu}
                onChange={this.onCronValueChange}
                cronValue={this.state.cronValue}
              />
            </div>
        </div>
    );

    renderLuxuryComposer = () => {
        if (!this.props.editable || !this.state.scheduleRequest) return null;

        const childField = this.getChildItemsLabel();
        const inputProps = {
            fieldConfig: this.props.fieldConfig,
            onFormError: this.onFormError,
            menuPortal: true,
            menuPortalZIndex: 10150,
            datePortal: true,
            datePopperPlacement: "top-start",
        };

        return (
            <div className="lux-recurring-panel__composer">
                <p className="lux-recurring-panel__composer-title">New recurring schedule</p>
                <div className="lux-recurring-panel__composer-grid">
                    <CustomInput
                        inputtype="text"
                        label="Schedule name"
                        name="name"
                        mappingObject={this.state.scheduleRequest}
                        onChange={this.onChange}
                        placeholder="e.g. Weekly stand-up work items"
                        datatype="alpnumspl"
                        {...inputProps}
                    />
                    <div className="lux-recurring-panel__composer-cron">{this.renderLuxuryCronPicker()}</div>
                    {this.props.type === "PROJECT" && this.state.scheduleRequest.recurringInfo && (
                        <CustomInput
                            readOnly={this.props.readOnly}
                            type="select"
                            label={childField.label}
                            name="childItemsTobeRecurrent"
                            mappingObject={this.state.scheduleRequest.recurringInfo}
                            onChange={this.onRecurringInfoChange}
                            placeholder={childField.placeholder}
                            options={
                                this.props.taskItemsitems &&
                                commonUtils.convertObjectToSelectObject(this.props.taskItemsitems)
                            }
                            multi
                            {...inputProps}
                        />
                    )}
                    {this.props.type === "TASK" && this.state.scheduleRequest.recurringInfo && (
                        <div className="lux-recurring-panel__assignees">
                            <CustomInput
                                readOnly={this.props.readOnly}
                                type="select"
                                label={childField.label}
                                name="childItemsTobeRecurrent"
                                mappingObject={this.state.scheduleRequest.recurringInfo}
                                onChange={this.onRecurringInfoChange}
                                placeholder={childField.placeholder}
                                options={
                                    this.props.allEmployees &&
                                    commonUtils.convertObjectToSelectObject(this.props.allEmployees)
                                }
                                multi
                                {...inputProps}
                            />
                            {childField.hint && (
                                <p className="lux-recurring-panel__field-hint">{childField.hint}</p>
                            )}
                        </div>
                    )}
                    <CustomInput
                        readOnly={this.props.readOnly}
                        type="dateselect"
                        label="End date"
                        name="endDate"
                        mappingObject={this.state.scheduleRequest}
                        onChange={this.onChange}
                        time={false}
                        minDate={new Date()}
                        currentDate={new Date()}
                        {...inputProps}
                    />
                </div>
                <div className="lux-recurring-panel__composer-actions">
                    <button
                        type="button"
                        className="lux-recurring-panel__btn is-primary"
                        onClick={() => this.handleSubmit()}
                    >
                        <i className="fe fe-plus" aria-hidden="true" />
                        Add schedule
                    </button>
                    <button
                        type="button"
                        className="lux-recurring-panel__btn is-ghost"
                        onClick={() => this.toggleEditOption(false)}
                    >
                        Cancel
                    </button>
                </div>
            </div>
        );
    };

    renderLuxury = () => {
        const items = this.props.items || [];
        const hasItems = items.length > 0;
        const childLabel = this.props.type === "PROJECT" ? "deliverables" : "assignees";

        return (
            <section className="lux-recurring-panel" aria-label="Recurring schedules">
                <div className="lux-recurring-panel__toolbar">
                    <p className="lux-recurring-panel__toolbar-copy">
                        {hasItems
                            ? `${items.length} active schedule${items.length === 1 ? "" : "s"} — automate ${childLabel} on a cadence.`
                            : `Automate recurring work items and assign ${childLabel} on a schedule.`}
                    </p>
                    {!this.props.editable && !this.props.readOnly && (
                        <button
                            type="button"
                            className="lux-recurring-panel__btn is-primary is-compact"
                            onClick={() => this.toggleEditOption(true)}
                        >
                            <i className="fe fe-plus" aria-hidden="true" />
                            Add schedule
                        </button>
                    )}
                </div>

                {this.renderLuxuryComposer()}

                {!hasItems && !this.props.editable && (
                    <div className="lux-recurring-panel__empty" role="status">
                        <span className="lux-recurring-panel__empty-icon" aria-hidden="true">
                            <i className="fe fe-repeat" />
                        </span>
                        <h5>No recurring schedules yet</h5>
                        <p>
                            Create a schedule to automatically generate work items for this deliverable on
                            weekdays, weeks, or custom cadences.
                        </p>
                        {!this.props.readOnly && (
                            <button
                                type="button"
                                className="lux-recurring-panel__btn is-primary"
                                onClick={() => this.toggleEditOption(true)}
                            >
                                <i className="fe fe-plus" aria-hidden="true" />
                                Add first schedule
                            </button>
                        )}
                    </div>
                )}

                {hasItems && (
                    <ul className="lux-recurring-panel__list" role="list">
                        {items.map((item) => (
                            <RecurringSelectionWindowLineItem
                                key={item.id}
                                item={item}
                                luxury
                                handleEnable={this.handleEnable}
                                handleRemove={this.handleRemove}
                                readOnly={this.props.readOnly}
                            />
                        ))}
                    </ul>
                )}
            </section>
        );
    };

    renderLegacy = () => {
        return (
            <>
                <span className="subHeading col-12 section-banner">
                    <button className="link pr-2" ><i className="fa fa-chevron-down"></i></button>
                    Recurring
                    {!this.props.editable && !this.props.readOnly &&
                        <button
                            type="button"
                            onClick={() => this.toggleEditOption(true)}
                            className="create-link link pt-0  pl-3 pr-3 fsize12 colorblue text-capitalize font-weight-normal"
                        >
                            Edit
                        </button>
                    }
                </span>
                {this.props.editable && this.state.scheduleRequest &&
                    <div className="col-12 py-1 border">
                        <div className="row">
                            <div className="col-3">
                                <CustomInput inputtype='text'
                                    label="Name"
                                    name="name"
                                    fieldConfig={this.props.fieldConfig}
                                    mappingObject={this.state.scheduleRequest}
                                    onChange={this.onChange}
                                    onFormError={this.onFormError}
                                    placeholder="Name..."
                                    datatype='alpnumspl' />
                            </div>
                            <div className="col-4">
                                <label className="form-label text-muted">Schedule<span className="form-required">*</span></label>
                                <i className="fa fa-recycle pr-1 colorblue" onClick={() => this.toggeleCronMenu(!this.state.showCroDropdownMenu)} />
                                <CronJobSelectionMenu
                                    showDropDown={this.state.showCroDropdownMenu}
                                    closeDropDwonMenu={this.toggeleCronMenu}
                                    onChange={this.onCronValueChange}
                                    cronValue={this.state.cronValue}
                                />
                                <span className="fsize13 fweight600 menu-text-black mr-5" onClick={() => this.toggeleCronMenu(!this.state.showCroDropdownMenu)}>{this.state.cronString}</span>


                            </div>
                            {this.props.type === 'PROJECT' && this.state.scheduleRequest.recurringInfo &&
                                <div className="col-3">
                                    <CustomInput readOnly={this.props.readOnly}
                                        type='select'
                                        label="Delivierables To Be included"
                                        name="childItemsTobeRecurrent"
                                        fieldConfig={this.props.fieldConfig}
                                        mappingObject={this.state.scheduleRequest.recurringInfo}
                                        onChange={this.onRecurringInfoChange}
                                        placeholder="Deliverables..."
                                        onFormError={this.onFormError}
                                        options={this.props.taskItemsitems && commonUtils.convertObjectToSelectObject(this.props.taskItemsitems)}
                                        multi={true}
                                    />
                                </div>

                            }
                            {this.props.type === 'TASK' && this.state.scheduleRequest.recurringInfo &&
                                <div className="col-3">
                                    <CustomInput readOnly={this.props.readOnly}
                                        type='select'
                                        label="Assignees (8 Hrs Default)"
                                        name="childItemsTobeRecurrent"
                                        fieldConfig={this.props.fieldConfig}
                                        mappingObject={this.state.scheduleRequest.recurringInfo}
                                        onChange={this.onRecurringInfoChange}
                                        placeholder="Employees..."
                                        onFormError={this.onFormError}
                                        options={this.props.allEmployees && commonUtils.convertObjectToSelectObject(this.props.allEmployees)}
                                        multi={true}
                                    />
                                </div>
                            }
                            <div className="col-2">
                                <CustomInput readOnly={this.props.readOnly}
                                    type='dateselect'
                                    label="End date"
                                    name="endDate"
                                    fieldConfig={this.props.fieldConfig}
                                    mappingObject={this.state.scheduleRequest}
                                    onChange={this.onChange}
                                    time={false}
                                    onFormError={this.onFormError}
                                    minDate={new Date()}
                                    currentDate={new Date()}
                                />

                            </div>
                        </div>
                        <div className="row col-6">
                            <button onClick={() => this.handleSubmit()} className="plainbutton text-upper border fweight600 fsize13">
                                Add
                            </button>
                            <button onClick={() => this.toggleEditOption(false)} className="create-link link pt-0  pl-3 pr-3 fsize12 colorblue text-capitalize font-weight-normal">
                                Cancel
                            </button>
                        </div>
                    </div>
                }
                {this.props.items && this.props.items.map(item =>
                    <RecurringSelectionWindowLineItem
                        item={item} key={item.id}
                        handleEnable={this.handleEnable}
                        handleRemove={this.handleRemove}
                        readOnly={this.props.readOnly}
                    />
                )}
                {this.props.items && this.props.items.length === 0 &&
                    <span className="text-muted fsize12">This item is not scheduled, Please edit and add new schedules</span>
                }
            </>
        );
    };

    render() {
        if (this.props.luxury) {
            return this.renderLuxury();
        }
        return this.renderLegacy();
    }
}

class RecurringSelectionWindowLineItem extends Component {
    renderLuxury = () => {
        const { item } = this.props;
        const childCount =
            (item.recurringInfo &&
                item.recurringInfo.childItemsTobeRecurrent &&
                item.recurringInfo.childItemsTobeRecurrent.length) ||
            0;
        const childLabel = item.recurringInfo && item.recurringInfo.type === "PROJECT" ? "deliverables" : "assignees";

        return (
            <li
                className={classNames("lux-recurring-row", { "is-enabled": item.enabled, "is-paused": !item.enabled })}
            >
                <div className="lux-recurring-row__main">
                    <span className="lux-recurring-row__icon" aria-hidden="true">
                        <i className="fe fe-repeat" />
                    </span>
                    <div className="lux-recurring-row__copy">
                        <strong>{item.name}</strong>
                        <p className="lux-recurring-row__cron">{item.cronString}</p>
                        <p className="lux-recurring-row__meta">
                            <span>
                                {childCount} {childLabel}
                            </span>
                            {item.endDate && (
                                <>
                                    <span className="lux-recurring-row__dot">·</span>
                                    <span>
                                        Ends {dateUtils.convertDateFormat(item.endDate)}
                                    </span>
                                </>
                            )}
                        </p>
                    </div>
                </div>
                <div className="lux-recurring-row__aside">
                    {item.enabled && item.nextRun && (
                        <div className="lux-recurring-row__next">
                            <span className="lux-recurring-row__next-label">Next run</span>
                            <strong>{item.nextRun}</strong>
                        </div>
                    )}
                    {!this.props.readOnly && (
                        <div className="lux-recurring-row__actions">
                            <label className="lux-recurring-row__switch" title={item.enabled ? "Pause" : "Enable"}>
                                <input
                                    type="checkbox"
                                    checked={item.enabled === true}
                                    onChange={() =>
                                        this.props.handleEnable(item.id, !item.enabled)
                                    }
                                />
                                <span className="lux-recurring-row__switch-ui" />
                            </label>
                            <button
                                type="button"
                                className="lux-recurring-row__remove"
                                title="Remove schedule"
                                aria-label={`Remove ${item.name}`}
                                onClick={() => this.props.handleRemove(item.id)}
                            >
                                <i className="fe fe-trash-2" aria-hidden="true" />
                            </button>
                        </div>
                    )}
                </div>
            </li>
        );
    };

    renderLegacy = () => {
        return (
            <>
                <div className="col-12 py-1">

                    <span className="d-flex justify-content-between align-items-center">
                        <span className="mt-1 mx-0 px-0">
                            {this.props.item.enabled &&
                                <i className="fa fa-recycle pr-1 iconblueshadowanimated" />
                            }
                            {!this.props.item.enabled &&
                                <i className="fa fa-recycle pr-1 text-muted" />
                            }

                            <span className="fsize13 fweight600 menu-text-black mr-1">{this.props.item.name}</span>
                            <i className="fa fa-angle-double-right pr-1"></i>
                            <span className="fsize13 menu-text-black mr-1 colorblue">{this.props.item.cronString}</span>
                            <span className="fsize13 menu-text-black mr-1">With <span className="fweight600 colorblue">{this.props.item.recurringInfo.childItemsTobeRecurrent && this.props.item.recurringInfo.childItemsTobeRecurrent.length || '0'}</span> {this.props.item.recurringInfo.type === 'PROJECT' ? "deliverables" : "Assignees"}</span>
                            {this.props.item.endDate &&
                                <span className="fsize13 menu-text-black mr-0">Ends on <span className="colorred">{dateUtils.convertDateFormat(this.props.item.endDate)}</span></span>
                            }
                        </span>
                        <span className="mt-1 ml-4">
                            {this.props.item.enabled &&
                                <>
                                    <span className="fsize12 menu-text-black mr-2">Next Run : <span className="fweight600 colorblue">{this.props.item.nextRun}</span></span>
                                    <span className="fsize12 menu-text-black mr-2 d-none">Last Run :{this.props.item.lastRun}</span>
                                </>
                            }
                            {!this.props.readOnly &&
                                <>
                                    <span>
                                        <label className=" custom-switch custom-switch-sm m-0">
                                            <input type="checkbox" onChange={() => { }}
                                                onClick={e => this.props.handleEnable(this.props.item.id, !this.props.item.enabled)}
                                                checked={this.props.item.enabled ? true : false}
                                                className="custom-switch-input" />
                                            <span className="custom-switch-indicator" />
                                        </label>
                                    </span>
                                    <button type="button"
                                        onClick={(e) => this.props.handleRemove(this.props.item.id)}
                                        className="link pl-2" title="Remove"><i className="fa fa-times colorred" /></button>
                                </>
                            }
                        </span>
                    </span>
                </div>
            </>
        );
    };

    render() {
        if (this.props.luxury) {
            return this.renderLuxury();
        }
        return this.renderLegacy();
    }
}

const mapStateToProps = state => ({
    selectedTaskInfo: state.tasks.selectedTaskInfo,
    fieldConfig: state.schedules.fieldConfig,
    taskItemsitems: state.tasks.recurrableTaskItems,
    items: state.schedules.items,
    editable: state.schedules.showCreateModel,
    allEmployees: state.employees.allEmployees
});

const mapDispatchToProps = dispatch => ({
    createScheule: scheduleActions.createSchedule,
    getSchedules: scheduleActions.getSchedules,
    enableSchedule: scheduleActions.enableSchedule,
    removeSchedule: scheduleActions.removeSchedule,
    getAllRecurrableTasks: taskActions.getAllRecurrableTasks,
    getAllEmployees: employeeActions.getAllEmployees,
});

export default connect(
    mapStateToProps,
    mapDispatchToProps
)(RecurringSelectionWindow);

