import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import { formatCurrency, INVOICE_DASHBOARD_SCOPE } from "./invoice.utils";

class InvoiceOutstandingPanel extends PureComponent {
  renderSummaryPill = (label, count, amount, tone, canViewAmounts) => (
    <div className={classNames("lux-inv-outstanding__pill", tone && `is-${tone}`)}>
      <span>{label}</span>
      <strong>{count}</strong>
      <em>{canViewAmounts ? formatCurrency(amount, { compact: true }) : "—"}</em>
    </div>
  );

  renderInvoiceRow = (row, canViewAmounts, highlightPending) => (
    <article
      key={row.id}
      className={classNames("lux-inv-outstanding__row", {
        "is-pending": row.status === "PENDING",
        "is-highlight": highlightPending && row.status === "PENDING",
      })}
    >
      <div className="lux-inv-outstanding__row-main">
        <div className="lux-inv-outstanding__row-top">
          <span className="lux-inv-outstanding__number">#{row.invoiceNumber}</span>
          <span
            className={classNames(
              "lux-inv-outstanding__status",
              `is-${row.statusTone}`
            )}
          >
            {row.statusLabel}
          </span>
        </div>
        <Link to={`/hrms/invoice/details/${row.id}`} className="lux-inv-outstanding__title">
          {row.name}
          <i className="fe fe-arrow-up-right" aria-hidden="true" />
        </Link>
        {row.description && (
          <p className="lux-inv-outstanding__description">{row.description}</p>
        )}
      </div>

      <div className="lux-inv-outstanding__row-facts">
        <div>
          <span>Invoice date</span>
          <strong>{row.invoiceDate}</strong>
        </div>
        {row.billingPeriod && (
          <div>
            <span>Billing period</span>
            <strong>{row.billingPeriod}</strong>
          </div>
        )}
        <div>
          <span>Users</span>
          <strong>{row.userCount}</strong>
        </div>
        <div>
          <span>Amount</span>
          <strong className="lux-inv-outstanding__amount">
            {canViewAmounts ? formatCurrency(row.amount) : "—"}
          </strong>
        </div>
      </div>

      <div className="lux-inv-outstanding__row-action">
        <Link to={`/hrms/invoice/details/${row.id}`} className="lux-inv-outstanding__view-btn">
          View
        </Link>
        {row.status === "PENDING" && this.props.onFocusPending && (
          <button
            type="button"
            className="lux-inv-outstanding__filter-btn"
            onClick={() => this.props.onFocusPending()}
          >
            Filter list
          </button>
        )}
      </div>
    </article>
  );

  renderSection = (title, rows, tone, canViewAmounts, emptyText) => {
    if (!rows.length) {
      return (
        <div className="lux-inv-outstanding__subsection is-empty">
          <h4>{title}</h4>
          <p>{emptyText}</p>
        </div>
      );
    }

    return (
      <div className={classNames("lux-inv-outstanding__subsection", tone && `is-${tone}`)}>
        <h4>{title}</h4>
        <div className="lux-inv-outstanding__rows">
          {rows.map((row) => this.renderInvoiceRow(row, canViewAmounts, true))}
        </div>
      </div>
    );
  };

  render() {
    const { outstanding, isLoading, canViewAmounts, dashboardScope, onFocusPending } =
      this.props;

    if (!dashboardScope || dashboardScope === INVOICE_DASHBOARD_SCOPE.ALL) return null;

    if (isLoading) {
      return (
        <div className="lux-inv-outstanding">
          <SkeletonTheme baseColor="#f1f5f9" highlightColor="#e2e8f0">
            <Skeleton height={180} borderRadius={16} />
          </SkeletonTheme>
        </div>
      );
    }

    if (!outstanding) return null;

    return (
      <section className="lux-inv-outstanding" aria-label="Outstanding invoices">
        <div className="lux-inv-outstanding__head">
          <div>
            <div className="lux-inv-outstanding__eyebrow">
              <i className="fe fe-alert-circle" aria-hidden="true" />
              Action needed
            </div>
            <h3>
              {outstanding.fyLabel} open invoices
            </h3>
            <p>
              {outstanding.openCount} outstanding
              {canViewAmounts && outstanding.openAmount > 0 && (
                <> · {formatCurrency(outstanding.openAmount, { compact: true })} awaiting settlement</>
              )}
            </p>
          </div>
          {outstanding.pendingCount > 0 && onFocusPending && (
            <button type="button" className="lux-inv-outstanding__head-btn" onClick={onFocusPending}>
              Show pending in list
            </button>
          )}
        </div>

        <div className="lux-inv-outstanding__summary">
          {this.renderSummaryPill(
            "Pending",
            outstanding.pendingCount,
            outstanding.pendingAmount,
            "blue",
            canViewAmounts
          )}
          {this.renderSummaryPill(
            "Draft",
            outstanding.draftCount,
            outstanding.draftAmount,
            "slate",
            canViewAmounts
          )}
          {this.renderSummaryPill(
            "Approved",
            outstanding.approvedCount,
            outstanding.approvedAmount,
            "amber",
            canViewAmounts
          )}
        </div>

        {this.renderSection(
          `Pending invoices (${outstanding.pendingCount})`,
          outstanding.pending,
          "blue",
          canViewAmounts,
          "No pending invoices in this financial year."
        )}

        {(outstanding.draft.length > 0 || outstanding.approved.length > 0) && (
          <div className="lux-inv-outstanding__secondary">
            {outstanding.draft.length > 0 &&
              this.renderSection(
                `Draft invoices (${outstanding.draftCount})`,
                outstanding.draft,
                "slate",
                canViewAmounts,
                ""
              )}
            {outstanding.approved.length > 0 &&
              this.renderSection(
                `Approved — awaiting payment (${outstanding.approvedCount})`,
                outstanding.approved,
                "amber",
                canViewAmounts,
                ""
              )}
          </div>
        )}

        {outstanding.openCount === 0 && (
          <div className="lux-inv-outstanding__all-clear">
            <i className="fe fe-check-circle" aria-hidden="true" />
            <span>All invoices in {outstanding.fyLabel} are paid or closed.</span>
          </div>
        )}
      </section>
    );
  }
}

export default InvoiceOutstandingPanel;
