/** Default destination when return context is unknown */
export const DEFAULT_BACK_DESTINATION_LABEL = "previous page";

/**
 * @param {string} destinationLabel Page name only (e.g. "Projects"), not including "Back to".
 */
export function formatBackNavLabel(destinationLabel) {
  const raw = (destinationLabel || "").trim();
  if (!raw) {
    return `Back to ${DEFAULT_BACK_DESTINATION_LABEL}`;
  }
  if (/^back to /i.test(raw)) {
    return raw;
  }
  return `Back to ${raw}`;
}
