import React from "react";
import { createPortal } from "react-dom";
import Cropper from "react-easy-crop";
import { getCroppedImg, getRotatedImage } from "views/common/plugins/image/canvasUtils";
import { getOrientation } from "get-orientation/browser";
import {
  getStoredProfilePhoto,
  resolveEmployeeAvatarUrl,
} from "./profile/profilePhoto.storage";

const ORIENTATION_TO_ANGLE = {
  3: 180,
  6: 90,
  8: -90,
};

function writeStoredPhoto(employeeId, dataUrl) {
  if (!employeeId || !dataUrl) return;
  try {
    localStorage.setItem(`famstack-profile-photo-${employeeId}`, dataUrl);
  } catch (e) {
    /* ignore quota errors */
  }
}

class ImageUpload extends React.Component {
  constructor(props) {
    super(props);
    this.fileInputRef = React.createRef();
    this.state = {
      displaySrc: null,
      cropOpen: false,
      cropSrc: null,
      crop: { x: 0, y: 0 },
      zoom: 1,
      croppedAreaPixels: null,
      saving: false,
    };
  }

  componentDidMount() {
    this.syncDisplayFromStorage();
  }

  componentDidUpdate(prevProps) {
    if (prevProps.employeeId !== this.props.employeeId || prevProps.imageUrl !== this.props.imageUrl) {
      this.syncDisplayFromStorage();
    }
  }

  syncDisplayFromStorage = () => {
    const stored = getStoredProfilePhoto(this.props.employeeId);
    this.setState({
      displaySrc: stored || null,
    });
  };

  getDisplayUrl = () =>
    this.state.displaySrc ||
    this.props.imageUrl ||
    resolveEmployeeAvatarUrl({ id: this.props.employeeId });

  readFile = (file) =>
    new Promise((resolve) => {
      const reader = new FileReader();
      reader.addEventListener("load", () => resolve(reader.result), false);
      reader.readAsDataURL(file);
    });

  onPickFile = () => {
    if (this.props.readOnly || !this.fileInputRef.current) return;
    this.fileInputRef.current.click();
  };

  onFileChange = async (e) => {
    const files = e.target.files;
    if (!files || !files.length) return;

    const file = files[0];
    let imageSrc = await this.readFile(file);

    try {
      const orientation = await getOrientation(file);
      const rotation = ORIENTATION_TO_ANGLE[orientation];
      if (rotation) {
        imageSrc = await getRotatedImage(imageSrc, rotation);
      }
    } catch (err) {
      /* orientation optional */
    }

    this.setState({
      cropOpen: true,
      cropSrc: imageSrc,
      crop: { x: 0, y: 0 },
      zoom: 1,
      croppedAreaPixels: null,
    });

    e.target.value = "";
  };

  onCropChange = (crop) => {
    this.setState({ crop });
  };

  onCropComplete = (_croppedArea, croppedAreaPixels) => {
    this.setState({ croppedAreaPixels });
  };

  onZoomChange = (zoom) => {
    this.setState({ zoom });
  };

  closeCropModal = () => {
    this.setState({
      cropOpen: false,
      cropSrc: null,
      crop: { x: 0, y: 0 },
      zoom: 1,
      croppedAreaPixels: null,
      saving: false,
    });
  };

  onSaveCrop = async () => {
    const { cropSrc, croppedAreaPixels } = this.state;
    if (!cropSrc || !croppedAreaPixels) return;

    this.setState({ saving: true });
    try {
      const result = await getCroppedImg(cropSrc, croppedAreaPixels, 0);
      writeStoredPhoto(this.props.employeeId, result);
      this.setState({ displaySrc: result, saving: false });
      this.closeCropModal();
      if (typeof window !== "undefined" && this.props.employeeId) {
        window.dispatchEvent(
          new CustomEvent("famstack-profile-photo-updated", {
            detail: { employeeId: this.props.employeeId },
          })
        );
      }
      if (this.props.onImageSaved) {
        this.props.onImageSaved(result);
      }
    } catch (err) {
      console.error(err);
      this.setState({ saving: false });
    }
  };

  renderCropModal() {
    const { cropOpen, cropSrc, crop, zoom, saving, croppedAreaPixels } = this.state;
    if (!cropOpen || !cropSrc || typeof document === "undefined") return null;

    return createPortal(
      <div className="profile-photo-crop" role="dialog" aria-modal="true" aria-label="Crop profile photo">
        <button
          type="button"
          className="profile-photo-crop__backdrop"
          onClick={this.closeCropModal}
          aria-label="Cancel"
        />
        <div className="profile-photo-crop__panel">
          <header className="profile-photo-crop__head">
            <div>
              <span className="profile-photo-crop__kicker">
                <i className="fe fe-camera" aria-hidden="true" />
                Profile photo
              </span>
              <h3 className="profile-photo-crop__title">Crop and save</h3>
              <p className="profile-photo-crop__sub">Drag to reposition · use zoom to fit your face</p>
            </div>
            <button
              type="button"
              className="profile-photo-crop__close"
              onClick={this.closeCropModal}
              aria-label="Close"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <div className="profile-photo-crop__stage">
            <Cropper
              image={cropSrc}
              crop={crop}
              zoom={zoom}
              aspect={1}
              cropShape="round"
              showGrid={false}
              onCropChange={this.onCropChange}
              onCropComplete={this.onCropComplete}
              onZoomChange={this.onZoomChange}
            />
          </div>

          <div className="profile-photo-crop__zoom">
            <label className="profile-photo-crop__zoom-label" htmlFor="profile-photo-zoom">
              Zoom
            </label>
            <input
              id="profile-photo-zoom"
              type="range"
              min={1}
              max={3}
              step={0.05}
              value={zoom}
              onChange={(event) => this.onZoomChange(Number(event.target.value))}
            />
          </div>

          <footer className="profile-photo-crop__foot">
            <button type="button" className="profile-photo-crop__btn profile-photo-crop__btn--ghost" onClick={this.closeCropModal}>
              Cancel
            </button>
            <button
              type="button"
              className="profile-photo-crop__btn profile-photo-crop__btn--primary"
              onClick={this.onSaveCrop}
              disabled={saving || !croppedAreaPixels}
            >
              {saving ? "Saving…" : "Save photo"}
            </button>
          </footer>
        </div>
      </div>,
      document.body
    );
  }

  render() {
    const { readOnly } = this.props;
    const displayUrl = this.getDisplayUrl();

    return (
      <>
        <div className="profile-avatar-upload">
          <div className="profile-avatar-upload__frame crop-container">
            <img className="profileImgHolder" src={displayUrl} alt="" />
            {!readOnly && (
              <button
                type="button"
                className="profile-avatar-upload__trigger imageChangeButton"
                onClick={this.onPickFile}
                title="Change profile photo"
                aria-label="Change profile photo"
              >
                <i className="fe fe-camera" aria-hidden="true" />
              </button>
            )}
          </div>
          {!readOnly && (
            <input
              ref={this.fileInputRef}
              className="d-none"
              type="file"
              accept="image/*"
              onChange={this.onFileChange}
            />
          )}
        </div>
        {this.renderCropModal()}
      </>
    );
  }
}

export default ImageUpload;
