export function readPanelCollapsed(storageKey, defaultCollapsed) {
  if (defaultCollapsed === undefined) {
    defaultCollapsed = false;
  }
  try {
    const value = localStorage.getItem(storageKey);
    if (value === null) {
      return defaultCollapsed;
    }
    return value === "true";
  } catch (e) {
    return defaultCollapsed;
  }
}

export function writePanelCollapsed(storageKey, collapsed) {
  try {
    localStorage.setItem(storageKey, String(collapsed));
  } catch (e) {
    /* ignore */
  }
}
