const STORAGE_PATH_KEY = "tracopus:profileDetails:returnPath";
const STORAGE_LABEL_KEY = "tracopus:profileDetails:returnLabel";

const PROFILE_PATH_RE = /^\/hrms\/profile\//;

const RETURN_LABEL_RULES = [
  { test: (p) => p.startsWith("/hrms/employees"), label: "Employees" },
  { test: (p) => p.startsWith("/hrms/dashboard"), label: "Dashboard" },
  { test: (p) => p.startsWith("/hrms/attendance"), label: "Attendance" },
  { test: (p) => p.startsWith("/hrms/timesheet"), label: "Timesheet" },
  { test: (p) => p.startsWith("/hrms/holidays"), label: "Holidays" },
  { test: (p) => p.startsWith("/hrms/leaves"), label: "Leaves" },
  { test: (p) => p.startsWith("/hrms/"), label: "HRMS" },
  { test: (p) => p.startsWith("/project/"), label: "Projects" },
  { test: (p) => p.startsWith("/sales/"), label: "Sales" },
];

const DEFAULT_RETURN = { path: "/hrms/employees", label: "Employees" };

export function isProfileDetailsPath(pathname = "") {
  return PROFILE_PATH_RE.test(pathname);
}

function isSafeReturnPath(path) {
  if (!path || typeof path !== "string" || !path.startsWith("/")) return false;
  const pathname = path.split("?")[0];
  if (isProfileDetailsPath(pathname)) return false;
  return /^\/(hrms|project|sales)\//.test(pathname);
}

export function getReturnLabelForPath(path) {
  const pathname = (path || "").split("?")[0];
  const rule = RETURN_LABEL_RULES.find((r) => r.test(pathname));
  return rule ? rule.label : "previous page";
}

export function captureProfileDetailsReturn(fromPathname, fromSearch = "") {
  const path = `${fromPathname || ""}${fromSearch || ""}`;
  if (!isSafeReturnPath(path)) return;
  try {
    sessionStorage.setItem(STORAGE_PATH_KEY, path);
    sessionStorage.setItem(STORAGE_LABEL_KEY, getReturnLabelForPath(path));
  } catch (_e) {
    /* ignore */
  }
}

function readStoredReturn() {
  try {
    const path = sessionStorage.getItem(STORAGE_PATH_KEY);
    const label = sessionStorage.getItem(STORAGE_LABEL_KEY);
    if (path && isSafeReturnPath(path)) {
      return { path, label: label || getReturnLabelForPath(path) };
    }
  } catch (_e) {
    /* ignore */
  }
  return null;
}

export function getProfileDetailsReturnTarget(location) {
  const stateFrom = location && location.state && location.state.from;
  if (stateFrom && isSafeReturnPath(stateFrom)) {
    return {
      path: stateFrom,
      label: location.state.fromLabel || getReturnLabelForPath(stateFrom),
    };
  }

  const stored = readStoredReturn();
  if (stored) return stored;

  return DEFAULT_RETURN;
}

export function buildProfileDetailsLink(employeeId, fromLocation, fromLabel) {
  const pathname = `/hrms/profile/${employeeId}`;
  if (!fromLocation) return { pathname };

  const from = (fromLocation.pathname || "") + (fromLocation.search || "");
  const state = { from };
  if (fromLabel) state.fromLabel = fromLabel;
  return { pathname, state };
}
