import React from "react";
import { getOrgCategoryLabel } from "./appConfigTree.utils";

function IdentityField({
  label,
  value,
  editing,
  onEdit,
  onCancel,
  onSave,
  canSave,
  children,
}) {
  return (
    <div className={`lux-hero-identity__item${editing ? " is-editing" : ""}`}>
      <span className="lux-hero-identity__label">{label}</span>
      {editing ? (
        <div className="lux-hero-identity__editor">
          {children}
          <div className="lux-hero-identity__editor-actions">
            <button
              type="button"
              className="lux-hero-identity__action lux-hero-identity__action--save"
              disabled={!canSave}
              onClick={onSave}
              title="Save"
            >
              <i className="fe fe-check" aria-hidden="true" />
            </button>
            <button
              type="button"
              className="lux-hero-identity__action"
              onClick={onCancel}
              title="Cancel"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </div>
        </div>
      ) : (
        <button
          type="button"
          className="lux-hero-identity__value-btn"
          onClick={onEdit}
          title={`Edit ${label.toLowerCase()}`}
        >
          <span className="lux-hero-identity__value">{value}</span>
          <i className="fe fe-edit-2 lux-hero-identity__edit-hint" aria-hidden="true" />
        </button>
      )}
    </div>
  );
}

function ApplicationConfigIdentityBar({
  data,
  menuSelection,
  parentMenuOptions,
  showConfigProperty,
  onChangeShowAddtionalOption,
  handleSaveConfigProperty,
}) {
  if (!data || !menuSelection) return null;

  const isOrg = menuSelection.type === "org";
  const currentMenuNode = parentMenuOptions.find(
    (node) => node.value === menuSelection.id
  );
  const hasParent = currentMenuNode && currentMenuNode.parent;
  const parentLabel = hasParent
    ? (
        parentMenuOptions.find(
          (node) => node.value === currentMenuNode.parent
        ) || {}
      ).label
    : null;

  return (
    <div className="lux-hero-identity">
      <IdentityField
        label="Name"
        value={data.name}
        editing={showConfigProperty.name.enabled}
        onEdit={() => onChangeShowAddtionalOption("name", "enabled", true)}
        onCancel={() => onChangeShowAddtionalOption("name", "enabled", false)}
        onSave={() => handleSaveConfigProperty("name")}
        canSave={
          showConfigProperty.name.value &&
          showConfigProperty.name.value.length > 3
        }
      >
        <input
          type="text"
          className="lux-hero-identity__input"
          value={showConfigProperty.name.value || ""}
          onChange={(event) =>
            onChangeShowAddtionalOption("name", "value", event.target.value)
          }
          placeholder="Enter name..."
          autoFocus
        />
      </IdentityField>

      {hasParent && (
        <>
          <span className="lux-hero-identity__divider" aria-hidden="true" />
          <IdentityField
            label="Parent"
            value={parentLabel || "—"}
            editing={showConfigProperty.parent.enabled}
            onEdit={() => onChangeShowAddtionalOption("parent", "enabled", true)}
            onCancel={() => onChangeShowAddtionalOption("parent", "enabled", false)}
            onSave={() => handleSaveConfigProperty("parent")}
            canSave={
              showConfigProperty.parent.value &&
              showConfigProperty.parent.value.length > 0
            }
          >
            <select
              className="lux-hero-identity__select"
              value={showConfigProperty.parent.value || ""}
              onChange={(event) =>
                onChangeShowAddtionalOption("parent", "value", event.target.value)
              }
            >
              <option value="">Select parent</option>
              {parentMenuOptions.map((node) => {
                if (
                  node.category !== "Team" &&
                  node.value !== menuSelection.id &&
                  node.value !== currentMenuNode.parent
                ) {
                  return (
                    <option value={node.value} key={node.value}>
                      {node.label}
                    </option>
                  );
                }
                return null;
              })}
            </select>
          </IdentityField>
        </>
      )}

      {isOrg && (
        <>
          <span className="lux-hero-identity__divider" aria-hidden="true" />
          <IdentityField
            label="Type"
            value={getOrgCategoryLabel(data.category || "Default")}
            editing={showConfigProperty.category.enabled}
            onEdit={() => onChangeShowAddtionalOption("category", "enabled", true)}
            onCancel={() => onChangeShowAddtionalOption("category", "enabled", false)}
            onSave={() => handleSaveConfigProperty("category")}
            canSave={
              showConfigProperty.category.value &&
              showConfigProperty.category.value.length > 1
            }
          >
            <select
              className="lux-hero-identity__select"
              value={showConfigProperty.category.value || ""}
              onChange={(event) =>
                onChangeShowAddtionalOption("category", "value", event.target.value)
              }
            >
              <option value="">Select type</option>
              <option value="Department">Department</option>
              <option value="Division">Division</option>
              <option value="Section">Section</option>
              <option value="Account">Account</option>
              <option value="Team">Team</option>
            </select>
          </IdentityField>
        </>
      )}
    </div>
  );
}

export default ApplicationConfigIdentityBar;
