import React, { Component } from "react";
import ChatPageSummary from "./components/chat/ChatPageSummary";
import ChatSidebar from "./components/chat/ChatSidebar";
import ChatThread from "./components/chat/ChatThread";
import {
  CHAT_DEMO_CONTACTS,
  CHAT_DEMO_GROUPS,
  CHAT_DEMO_MESSAGES,
  buildChatSummary,
} from "./components/chat/chat.utils";

class ChatPage extends Component {
  constructor() {
    super();
    this.state = {
      activeThread: CHAT_DEMO_GROUPS[0],
      messages: CHAT_DEMO_MESSAGES,
    };
  }

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
  }

  handleSelectThread = (thread) => {
    this.setState({ activeThread: thread });
  };

  handleSendMessage = (text) => {
    this.setState((prev) => ({
      messages: [
        ...prev.messages,
        {
          id: `local-${Date.now()}`,
          author: "You",
          initials: "ME",
          isMine: true,
          time: new Date().toLocaleTimeString([], { hour: "numeric", minute: "2-digit" }),
          text,
        },
      ],
    }));
  };

  render() {
    const summary = buildChatSummary(CHAT_DEMO_CONTACTS, CHAT_DEMO_GROUPS);

    return (
      <div className="lux-chat-page lux-bid-requests">
        <ChatPageSummary stat={summary} />
        <div className="lux-chat-workspace">
          <ChatSidebar
            contacts={CHAT_DEMO_CONTACTS}
            groups={CHAT_DEMO_GROUPS}
            activeId={this.state.activeThread && this.state.activeThread.id}
            onSelect={this.handleSelectThread}
          />
          <ChatThread
            thread={this.state.activeThread}
            messages={this.state.messages}
            onSend={this.handleSendMessage}
          />
        </div>
      </div>
    );
  }
}

export default ChatPage;
