import dateUtils from "_helpers/date.utils";

export const COLLAB_VIEWS = {
  COMMENT: "COMMENT",
  ACTIVITY: "ACTIVITY",
  HISTORY: "HISTORY",
};

export const COLLAB_VIEW_TABS = [
  { id: COLLAB_VIEWS.COMMENT, label: "Comments", icon: "fe-message-square" },
  { id: COLLAB_VIEWS.ACTIVITY, label: "Activity", icon: "fe-activity" },
  { id: COLLAB_VIEWS.HISTORY, label: "History", icon: "fe-clock" },
];

export function stripHtml(html) {
  if (!html) return "";
  return String(html)
    .replace(/<br\s*\/?>/gi, " ")
    .replace(/<\/p>/gi, " ")
    .replace(/<[^>]+>/g, "")
    .replace(/&nbsp;/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function getEmployeeName(entry) {
  if (!entry) return "Unknown user";
  if (entry.employeeInfo && entry.employeeInfo.name) return entry.employeeInfo.name;
  if (entry.createdByDetails && entry.createdByDetails.name) return entry.createdByDetails.name;
  return "System";
}

export function getEmployeeMeta(entry) {
  const employee = entry && entry.employeeInfo;
  if (!employee) return null;
  return employee.designation || employee.email || employee.empCode || null;
}

export function formatCollabTimestamp(value) {
  if (!value) return "—";
  return dateUtils.convertDateTimeFormat(value);
}

export function formatCollabRelativeTime(value) {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";

  const diffMs = Date.now() - date.getTime();
  const minutes = Math.floor(diffMs / 60000);
  if (minutes < 1) return "Just now";
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  if (days < 7) return `${days}d ago`;
  return dateUtils.convertDateFormat(value);
}

export function getEntryHeadline(entry, viewType) {
  if (!entry) return "Update";
  if (entry.name) return entry.name;
  if (entry.title) return entry.title;

  const plain = stripHtml(entry.description);
  if (!plain) {
    return viewType === COLLAB_VIEWS.HISTORY
      ? "Audit event"
      : viewType === COLLAB_VIEWS.ACTIVITY
      ? "Activity logged"
      : "Comment";
  }

  if (viewType === COLLAB_VIEWS.HISTORY) {
    if (/status/i.test(plain)) return "Status changed";
    if (/assign/i.test(plain)) return "Assignment updated";
    if (/creat/i.test(plain)) return "Record created";
    if (/updat/i.test(plain)) return "Fields updated";
    if (/delet|archiv/i.test(plain)) return "Record modified";
    return plain.length > 72 ? `${plain.slice(0, 72)}…` : plain;
  }

  if (viewType === COLLAB_VIEWS.ACTIVITY) {
    if (/comment/i.test(plain)) return "Comment activity";
    if (/status/i.test(plain)) return "Status activity";
    if (/upload|attach|file/i.test(plain)) return "File activity";
    return plain.length > 88 ? `${plain.slice(0, 88)}…` : plain;
  }

  return plain.length > 96 ? `${plain.slice(0, 96)}…` : plain;
}

export function getEntryTone(entry, viewType) {
  const plain = stripHtml(entry && entry.description).toLowerCase();
  if (viewType === COLLAB_VIEWS.HISTORY) {
    if (/reject|delet|remov|fail|cancel/i.test(plain)) return "danger";
    if (/approv|complet|won|success/i.test(plain)) return "success";
    if (/assign|creat|new/i.test(plain)) return "sky";
    if (/status|updat|chang|edit/i.test(plain)) return "amber";
    return "slate";
  }
  if (/comment|note|mention/i.test(plain)) return "indigo";
  if (/status|progress/i.test(plain)) return "amber";
  if (/file|upload|attach/i.test(plain)) return "sky";
  return "violet";
}

export function getEntryIcon(viewType, tone) {
  if (viewType === COLLAB_VIEWS.COMMENT) return "fe-message-square";
  if (viewType === COLLAB_VIEWS.HISTORY) {
    if (tone === "success") return "fe-check-circle";
    if (tone === "danger") return "fe-alert-circle";
    if (tone === "amber") return "fe-edit-3";
    return "fe-shield";
  }
  if (tone === "sky") return "fe-upload";
  if (tone === "amber") return "fe-flag";
  return "fe-activity";
}

export function groupEntriesByDay(entries) {
  const map = new Map();
  (entries || []).forEach((entry) => {
    const label = entry.createdDate
      ? dateUtils.convertDateFormat(entry.createdDate)
      : "Undated";
    if (!map.has(label)) map.set(label, []);
    map.get(label).push(entry);
  });
  return Array.from(map.entries());
}

export function hasRichHtmlContent(html) {
  return stripHtml(html).length > 0;
}

export function getCollabItemsForView(props, view) {
  if (view === COLLAB_VIEWS.COMMENT) return props.comments;
  if (view === COLLAB_VIEWS.ACTIVITY) return props.activities;
  return props.histories;
}
