import React from "react";
import { UTIL_TONES } from "../plannerAnalytics.utils";

export default function PlannerUtilLegend({ compact }) {
  const items = ["leave", "available", "light", "balanced", "high", "critical"];
  return (
    <div className={`lux-planner-legend${compact ? " lux-planner-legend--compact" : ""}`} aria-label="Utilization legend">
      {items.map((key) => (
        <span key={key} className="lux-planner-legend__item">
          <span className={`lux-planner-legend__swatch is-${key}`} style={{ "--legend-color": UTIL_TONES[key].color }} />
          {UTIL_TONES[key].label}
        </span>
      ))}
    </div>
  );
}
