import React, { Component } from "react";
import { getQuestionLayoutSpan } from "../../feedbackForm.utils";
import LuxFeedbackQuestionLabel from "./LuxFeedbackQuestionLabel";

class LongTextInput extends Component {
  onChange = (value) => {
    this.props.onChange({ ...this.props.questionConfig, answer: value });
  };

  render() {
    const { questionConfig, readonly } = this.props;
    if (!questionConfig) return null;
    const span = getQuestionLayoutSpan(questionConfig.type);

    return (
      <div className={`lux-fb-q lux-fb-q--${span}`}>
        <div className="lux-fb-q__card">
          <LuxFeedbackQuestionLabel questionConfig={questionConfig} />
          <textarea
            name="message"
            id={`lux-fb-q-${questionConfig.id}`}
            placeholder="Share any additional context that would help us understand your experience…"
            disabled={readonly}
            value={questionConfig.answer || ""}
            onChange={(event) => this.onChange(event.target.value)}
          />
        </div>
      </div>
    );
  }
}
export default LongTextInput;
