export function buildChatSummary(contacts, groups) {
  const online = [...contacts, ...groups].filter((c) => c.status === "online").length;
  const unread = [...contacts, ...groups].reduce((sum, c) => sum + (c.unread || 0), 0);
  return {
    contacts: contacts.length,
    groups: groups.length,
    online,
    unread,
    kpis: [
      { key: "threads", label: "Conversations", value: contacts.length + groups.length, icon: "fe fe-message-square", hint: `${groups.length} groups` },
      { key: "online", label: "Online now", value: online, icon: "fe fe-wifi", hint: "Available teammates", tone: "green" },
      { key: "unread", label: "Unread", value: unread, icon: "fe fe-bell", hint: "Across all threads", tone: unread > 0 ? "amber" : "slate" },
    ],
  };
}

export function filterChatList(items, query) {
  if (!query) return items;
  const q = query.toLowerCase();
  return items.filter(
    (item) =>
      item.name.toLowerCase().includes(q) || (item.preview && item.preview.toLowerCase().includes(q))
  );
}
