import React from "react";
import ReactApexChart from "react-apexcharts";

function DashboardApexChart({ type, series, options, height = 300 }) {
  return (
    <ReactApexChart
      options={options}
      series={series}
      type={type}
      height={height}
      width="100%"
    />
  );
}

export default DashboardApexChart;
