import React, { PureComponent } from "react";
import { connect } from "react-redux";
import { Link } from "react-router-dom";
import LuxBackNavLink from "views/common/fragments/LuxBackNavLink";
import { accessUtils, store, commonUtils } from "_helpers";
import { invoiceActions } from "_actions/invoice.actions";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import InvoiceDocumentView from "./components/invoice/InvoiceDocumentView";
import InvoiceEmployeesModal from "./components/invoice/InvoiceEmployeesModal";
import { downloadInvoicePdf } from "./components/invoice/invoicePdf.utils";
import {
  buildInvoiceShareUrl,
  getInvoiceNumber,
  getInvoiceShareAccessToken,
  getUserCount,
  INVOICE_STATUS_META,
} from "./components/invoice/invoice.utils";

class InvoiceDetailsPage extends PureComponent {
  constructor() {
    super();
    this.state = {
      showEmployeesModal: false,
      pdfDownloading: false,
      permission: accessUtils.getInvoiceAccessControl(),
    };
    this.invoiceSheetRef = React.createRef();
  }

  componentDidMount() {
    const invoiceId = this.props.match.params.invoiceId;
    this.setState({ invoiceId });
    this.invokeGetInvoiceService(invoiceId);
    if (this.state.permission.viewEnabled && !getInvoiceShareAccessToken(this.props.header)) {
      store.dispatch(this.props.ensureInvoiceHeader());
    }
    document.body.classList.add("lux-inv-detail-page-open");
  }

  componentWillUnmount() {
    document.body.classList.remove("lux-inv-detail-page-open");
  }

  openEmployeesModal = () => {
    this.setState({ showEmployeesModal: true });
  };

  closeEmployeesModal = () => {
    this.setState({ showEmployeesModal: false });
  };

  invokeGetInvoiceService = (invoiceId) => {
    const hasAccess = this.hasAccess();
    if (this.state.permission.viewEnabled || hasAccess) {
      store.dispatch(this.props.getInvoiceInfo(invoiceId, hasAccess));
    }
  };

  hasAccess = () => {
    const ac = new URLSearchParams(this.props.location.search).get("ac");
    const urlInvoiceNumber = new URLSearchParams(this.props.location.search).get("uin");
    const invoiceId = this.props.match.params.invoiceId;
    return (
      ac &&
      urlInvoiceNumber &&
      commonUtils.decryptString(ac, urlInvoiceNumber + "_" + invoiceId) === urlInvoiceNumber
    );
  };

  isDocumentView = () => {
    return (this.props.location.pathname || "").indexOf("/document/") === 0;
  };

  handlePrint = () => {
    window.print();
  };

  handleDownloadPdf = async () => {
    const { item } = this.props;
    if (!item || this.state.pdfDownloading) return;

    this.setState({ pdfDownloading: true });
    try {
      await downloadInvoicePdf(
        this.invoiceSheetRef.current,
        `Invoice-${getInvoiceNumber(item)}.pdf`
      );
    } catch (error) {
      console.error("Invoice PDF download failed:", error);
    } finally {
      this.setState({ pdfDownloading: false });
    }
  };

  getShareUrl = () => {
    return buildInvoiceShareUrl(
      this.props.item,
      getInvoiceShareAccessToken(this.props.header)
    );
  };

  renderToolbar = () => {
    const { item } = this.props;
    const statusMeta =
      item && INVOICE_STATUS_META[item.status]
        ? INVOICE_STATUS_META[item.status]
        : INVOICE_STATUS_META.DRAFT;
    const shareUrl = this.getShareUrl();
    const employeeCount = item ? getUserCount(item) : 0;

    return (
      <div className="lux-inv-detail__toolbar no-print">
        <div className="lux-inv-detail__toolbar-inner">
          <div className="lux-inv-detail__toolbar-start">
            {!this.isDocumentView() && (
              <LuxBackNavLink
                to="/hrms/invoice"
                destinationLabel="Invoices"
                className="lux-inv-detail__back-btn"
              />
            )}
            {item && (
              <div className="lux-inv-detail__toolbar-title">
                <span>Invoice #{getInvoiceNumber(item)}</span>
                <span className={`lux-inv-detail__status is-${statusMeta.tone}`}>
                  {statusMeta.label}
                </span>
              </div>
            )}
          </div>
          <div className="lux-inv-detail__toolbar-actions">
            {item && item.usersMap && employeeCount > 0 && (
              <button
                type="button"
                className="lux-inv-detail__action-btn lux-inv-detail__action-btn--accent"
                onClick={this.openEmployeesModal}
              >
                <i className="fe fe-users" aria-hidden="true" />
                Billed employees
                <span className="lux-inv-detail__action-count">{employeeCount}</span>
              </button>
            )}
            <button type="button" className="lux-inv-detail__action-btn" onClick={this.handlePrint}>
              <i className="fe fe-printer" aria-hidden="true" />
              Print
            </button>
            <button
              type="button"
              className="lux-inv-detail__action-btn"
              onClick={this.handleDownloadPdf}
              disabled={this.state.pdfDownloading}
            >
              <i
                className={`fe ${this.state.pdfDownloading ? "fe-loader" : "fe-download"}`}
                aria-hidden="true"
              />
              {this.state.pdfDownloading ? "Generating…" : "Download PDF"}
            </button>
            {shareUrl && this.state.permission.viewEnabled && (
              <a
                href={shareUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="lux-inv-detail__action-btn"
              >
                <i className="fe fe-share-2" aria-hidden="true" />
                Share
              </a>
            )}
          </div>
        </div>
      </div>
    );
  };

  renderLoading = () => (
    <div className="lux-inv-detail__sheet lux-inv-detail__sheet--loading">
      <SkeletonTheme baseColor="#f1f5f9" highlightColor="#e2e8f0">
        <Skeleton height={120} borderRadius={0} />
        <Skeleton height={180} borderRadius={0} style={{ marginTop: 0 }} />
        <Skeleton height={240} borderRadius={0} style={{ marginTop: 0 }} />
      </SkeletonTheme>
    </div>
  );

  renderDenied = () => (
    <div className="lux-inv-detail__denied">
      <i className="fe fe-lock" aria-hidden="true" />
      <strong>Access restricted</strong>
      <p>You do not have permission to view this invoice.</p>
    </div>
  );

  render() {
    const canView = this.state.permission.viewEnabled || this.hasAccess();
    const { item, loading } = this.props;

    return (
      <div className="lux-inv-detail lux-inv-detail--fullpage">
        {canView && this.renderToolbar()}

        {canView && loading && !item && this.renderLoading()}

        {canView && item && (
          <>
            <InvoiceDocumentView item={item} sheetRef={this.invoiceSheetRef} />
            <InvoiceEmployeesModal
              open={this.state.showEmployeesModal}
              onClose={this.closeEmployeesModal}
              usersMap={item.usersMap}
              invoiceLabel={`Invoice #${getInvoiceNumber(item)}`}
            />
          </>
        )}

        {!canView && this.renderDenied()}
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  loading: state.invoice.loading,
  item: state.invoice.selectedInvoiceInfo,
  header: state.invoice.header,
});

const mapDispatchToProps = () => ({
  getInvoiceInfo: invoiceActions.getInvoiceInfo,
  ensureInvoiceHeader: invoiceActions.ensureInvoiceHeader,
  removeInvoice: invoiceActions.removeInvoice,
  updateInvoiceStatus: invoiceActions.updateInvoiceStatus,
});

export default connect(mapStateToProps, mapDispatchToProps)(InvoiceDetailsPage);
