import React, { Component } from "react";
import { createPortal } from "react-dom";
import { connect } from "react-redux";
import Skeleton from "react-loading-skeleton";
import { workItemConstants } from "_constants";
import { taskService } from "_services";
import { commonUtils, store } from "_helpers";
import { notificationActions } from "_actions";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import LuxNoteCard from "views/project/components/LuxNoteCard";
import LuxNoteEditorPanel from "views/project/components/modal/LuxNoteEditorPanel";
import {
  filterPendingNotes,
  formatNoteWhen,
  getNotesLoadRange,
} from "views/project/components/notes.utils";

const SCATTER_OFFSETS = [0, 14, -10, 18, -6, 8, -12];

class NotesPendingOverlay extends Component {
  constructor(props) {
    super(props);
    this.state = {
      items: [],
      isLoading: false,
      showEditor: false,
      editingNote: null,
      isSaving: false,
    };
  }

  componentDidMount() {
    if (this.props.show) {
      this.loadPending();
    }
  }

  componentDidUpdate(prevProps) {
    if (this.props.show && !prevProps.show) {
      this.loadPending();
    }
  }

  close = () => {
    store.dispatch({ type: workItemConstants.CLOSE_NOTES_OVERLAY_WINDOW });
    this.setState({ showEditor: false, editingNote: null });
  };

  loadPending = () => {
    const employeeId = commonUtils.getCurrentUserId();
    if (!employeeId) return;
    const range = getNotesLoadRange();
    this.setState({ isLoading: true });
    taskService
      .listNotes({
        employeeId,
        currentEmployeeId: employeeId,
        startDate: range.startDate,
        endDate: range.endDate,
      })
      .then((res) => {
        const raw = res && res.payload;
        const all = Array.isArray(raw) ? raw : raw ? [raw] : [];
        this.setState({ items: filterPendingNotes(all), isLoading: false });
      })
      .catch(() => {
        this.setState({ items: [], isLoading: false });
      });
  };

  openCreate = (e) => {
    e.stopPropagation();
    this.setState({ showEditor: true, editingNote: null });
  };

  openEdit = (note) => {
    this.setState({ showEditor: true, editingNote: note });
  };

  closeEditor = () => {
    if (!this.state.isSaving) {
      this.setState({ showEditor: false, editingNote: null });
    }
  };

  saveNote = (payload) => {
    const employeeId = commonUtils.getCurrentUserId();
    const body = { ...payload, employeeId };
    this.setState({ isSaving: true });
    const isEdit = !!(this.state.editingNote && this.state.editingNote.id);
    const req = isEdit ? taskService.updateNote(body) : taskService.createNote(body);
    req
      .then(() => {
        store.dispatch(notificationActions.success(isEdit ? "Note updated" : "Note added"));
        this.setState({ isSaving: false, showEditor: false, editingNote: null });
        this.loadPending();
      })
      .catch((err) => {
        store.dispatch(notificationActions.error(String((err && err.message) || err || "Could not save")));
        this.setState({ isSaving: false });
      });
  };

  markDone = (note) => {
    taskService
      .updateNoteStatus(note.id, "COMPLETED")
      .then(() => this.loadPending())
      .catch((err) => {
        store.dispatch(notificationActions.error(String((err && err.message) || err || "Update failed")));
      });
  };

  deleteNote = (note) => {
    taskService
      .removeNote(note.id)
      .then(() => {
        store.dispatch(notificationActions.success("Note deleted"));
        this.loadPending();
      })
      .catch((err) => {
        store.dispatch(notificationActions.error(String((err && err.message) || err || "Delete failed")));
      });
  };

  scatterStyle = (index) => ({
    marginLeft: `${SCATTER_OFFSETS[index % SCATTER_OFFSETS.length]}px`,
  });

  render() {
    const { show } = this.props;
    const { items, isLoading } = this.state;
    if (!show) return null;

    const content = (
      <>
        <button
          type="button"
          className="lux-notes-overlay__backdrop"
          aria-label="Close notes overlay"
          onClick={this.close}
        />

        <div className="lux-notes-overlay" aria-hidden="false">
          <header
            className="lux-notes-overlay__float-head"
            role="region"
            aria-label="Pending notes controls"
            onClick={(e) => e.stopPropagation()}
          >
            <div>
              <LuxSummaryEyebrow variant="notes" className="lux-notes-overlay__eyebrow">
                Personal notes
              </LuxSummaryEyebrow>
              <h2 className="lux-notes-overlay__title">Pending notes</h2>
              <p className="lux-notes-overlay__sub">
                {isLoading
                  ? <Skeleton width={140} height={14} borderRadius={4} />
                  : items.length === 0
                    ? "Nothing open — capture a quick thought anytime."
                    : `${items.length} open note${items.length === 1 ? "" : "s"}`}
              </p>
            </div>
            <div className="lux-notes-overlay__head-actions">
              <button
                type="button"
                className="lux-create-footer__btn lux-create-footer__btn--primary"
                onClick={this.openCreate}
              >
                <i className="fe fe-plus" aria-hidden="true" />
                Add note
              </button>
              <button
                type="button"
                className="lux-notes-overlay__close"
                onClick={this.close}
                aria-label="Close overlay"
              >
                <i className="fe fe-x" aria-hidden="true" />
              </button>
            </div>
          </header>

          <div className="lux-notes-overlay__deck" role="list" aria-label="Pending note cards">
            {isLoading &&
              [1, 2, 3].map((k) => (
                <div
                  key={k}
                  className="lux-notes-overlay__card-slot"
                  style={this.scatterStyle(k - 1)}
                  role="listitem"
                >
                  <Skeleton height={148} borderRadius={16} />
                </div>
              ))}
            {!isLoading && items.length === 0 && (
              <article
                className="lux-notes-overlay__empty-card lux-notes-overlay__card-slot"
                style={this.scatterStyle(0)}
                role="listitem"
              >
                <i className="fe fe-edit-3" aria-hidden="true" />
                <strong>All caught up</strong>
                <p>Yellow sticky notes float here when you have open items.</p>
                <button
                  type="button"
                  className="lux-create-footer__btn lux-create-footer__btn--primary"
                  onClick={this.openCreate}
                >
                  <i className="fe fe-plus" aria-hidden="true" />
                  New note
                </button>
              </article>
            )}
            {!isLoading &&
              items.map((note, index) => (
                <div
                  key={note.id}
                  className="lux-notes-overlay__card-slot"
                  style={this.scatterStyle(index)}
                  role="listitem"
                >
                  <LuxNoteCard
                    note={note}
                    formatWhen={formatNoteWhen}
                    stickyVisual
                    onMarkDone={this.markDone}
                    onEdit={this.openEdit}
                    onDelete={this.deleteNote}
                  />
                </div>
              ))}
          </div>
        </div>

        <LuxNoteEditorPanel
          show={this.state.showEditor}
          note={this.state.editingNote}
          onClose={this.closeEditor}
          onSave={this.saveNote}
          isSaving={this.state.isSaving}
        />
      </>
    );

    if (typeof document !== "undefined") {
      return createPortal(content, document.body);
    }
    return content;
  }
}

const mapStateToProps = (state) => ({
  show: !!(state.workItem && state.workItem.showNotesOverlay),
});

export default connect(mapStateToProps)(NotesPendingOverlay);
