import React, { Component } from "react";
import { createPortal } from "react-dom";
import MobileAppRegistrationPanel from "./components/MobileAppRegistrationPanel";
import "./DeviceRegistrationPopup.css";

class DeviceRegistrationPopup extends Component {
  handleOverlayClick = (e) => {
    if (e.target === e.currentTarget) {
      this.props.onClose(e);
    }
  };

  handleCloseClick = (e) => {
    e.preventDefault();
    e.stopPropagation();
    this.props.onClose(e);
  };

  render() {
    return createPortal(
      <div className="device-registration-popup-overlay" onClick={this.handleOverlayClick}>
        <div className="device-registration-popup" onClick={(e) => e.stopPropagation()} role="dialog" aria-modal="true" aria-labelledby="mobile-app-popup-title">
          <div className="device-registration-popup__header">
            <h3 id="mobile-app-popup-title" className="device-registration-popup__title">
              Mobile App
            </h3>
            <button
              type="button"
              className="device-registration-popup__close"
              onClick={this.handleCloseClick}
              aria-label="Close"
              data-ga-action="device_popup_close"
              data-ga-category="engagement"
              data-ga-label="Close"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </div>

          <div className="device-registration-popup__body">
            <MobileAppRegistrationPanel />
          </div>
        </div>
      </div>,
      document.body
    );
  }
}

export default DeviceRegistrationPopup;
