class MultiListValueConfigItem extends Component {
    constructor() {
        super();
        this.state = {
            configItemRequest: null,
            addNewValueEnabled: false,
            addNewValue: '',
            multiAddEnabled: false
        }
    }
    componentDidMount() {
        this.setState(prevState => ({
            configItemRequest: {
                ...this.props.configItem
            }
        }))
    }

    onChange = (fieldName, value) => {

        if ("overridden" === fieldName) {
            let oldvalues = this.props.configItem.parentValue && value === false ? this.props.configItem.parentValue : this.props.configItem.value
            this.setState(prevState => ({
                configItemRequest: {
                    ...this.props.configItem,
                    "overridden": value,
                    "value": oldvalues
                }
            }), () => {
                this.props.onChange(this.props.selectedKey, this.state.configItemRequest);
            })
        } else {
            this.setState(prevState => ({
                configItemRequest: {
                    ...prevState.configItemRequest,
                    [fieldName]: value
                }
            }), () => {
                this.props.onChange(this.props.selectedKey, this.state.configItemRequest);
            })
        }

    }

    onDelete = (valueToBeDeteleted) => {
        this.onChange("value", this.state.configItemRequest.value.filter(value => valueToBeDeteleted != value))
    }

    onAddNewValueEnabled = (valueToBeDeteleted) => {
        this.setState(prevState => ({
            addNewValueEnabled: true
        }))
    }

    onAddNewValue = () => {
        let addNewValue = this.state.addNewValue.trim();
        if (addNewValue !== '') {
            if (this.state.multiAddEnabled) {
                let addNewValueArray = addNewValue.split(/[\n,]/).map(function (item) {
                    return item.trim();
                }).filter(Boolean);
                this.onChange("value", [...addNewValueArray, ...this.state.configItemRequest.value])
            } else {
                this.onChange("value", [addNewValue.trim(), ...this.state.configItemRequest.value])
            }

            this.onClearAddNew();
        }
    }

    onClearAddNew = () => {
        this.setState(prevState => ({
            addNewValueEnabled: false,
            addNewValue: ''
        }))
    }

    onAddNewValueInputChange = (e) => {
        e.persist();
        if (validationUtils.validateAlphaNumbericWithCommaAndReturn(e.target.value)) {
            this.setState(prevState => ({
                addNewValue: e.target.value
            }));
        }
    }

    onToggleMultiAddEnabled = () => {
        this.setState(prevState => ({
            multiAddEnabled: !prevState.multiAddEnabled
        }))
    }

    render() {
        const { configItemRequest } = this.state;
        if (!configItemRequest) return null;

        return (
            <div className={getConfigBlockClasses(configItemRequest)}>
                <ConfigBlockHeader
                    label={configItemRequest.label}
                    count={configItemRequest.value.length}
                    parentLocked={this.props.configItem.parentLocked}
                    configItemRequest={configItemRequest}
                    onChange={this.onChange}
                    actions={
                        <>
                            {this.state.addNewValueEnabled && (
                                <button type="button" className="lux-appconfig-icon-btn link" title="Toggle bulk add" onClick={this.onToggleMultiAddEnabled}>
                                    <i className={classNames("fe fe-list", { "text-muted": !this.state.multiAddEnabled })} />
                                </button>
                            )}
                            {configItemRequest.overridden && (
                                <button type="button" className="lux-appconfig-icon-btn link" title="Add value" onClick={this.onAddNewValueEnabled}>
                                    <i className="fe fe-plus" />
                                </button>
                            )}
                        </>
                    }
                />
                <div className="lux-ac-config-block__body appconfig-item">
                    <ul className="lux-ac-config-block__list">
                        {this.state.addNewValueEnabled && (
                            <ConfigAddValueRow
                                addNewValue={this.state.addNewValue}
                                multiAddEnabled={this.state.multiAddEnabled}
                                onValueChange={this.onAddNewValueInputChange}
                                onSave={this.onAddNewValue}
                                onClear={this.onClearAddNew}
                                onToggleMulti={this.onToggleMultiAddEnabled}
                                showMultiToggle={false}
                            />
                        )}
                        {configItemRequest.value.map((value, index) => (
                            <li key={value} className="lux-ac-config-block__list-item">
                                <span className="lux-ac-config-block__list-index">{index + 1}</span>
                                <span className="lux-ac-config-block__list-value">{value}</span>
                                {!this.props.configItem.parentLocked && configItemRequest.overridden && (
                                    <button type="button" className="lux-appconfig-icon-btn link lux-ac-config-block__remove" title="Remove" onClick={() => this.onDelete(value)}>
                                        <i className="fe fe-x" />
                                    </button>
                                )}
                            </li>
                        ))}
                    </ul>
                </div>
            </div>
        );
    }
}


