class MultiLevelValueSection extends Component {
    constructor() {
        super();
        this.state = {
            topOverridden: false,
            topSelectedItemValue: null,
            selectedItemValue: null,
            addNewValueEnabled: false,
            addNewValue: '',
            multiAddEnabled: false
        }
    }

    onChange = (fieldName, values) => {
        if (this.props.selectedItemValue) {
            this.props.values[this.props.selectedItemValue] = values;
            this.props.onChange(fieldName, this.props.values)
        } else {
            this.props.onChange(fieldName, values)
        }
    }
    componentDidUpdate() {
        if (this.props.configItemRequest.overridden !== this.state.topOverridden) {

            this.setState(prevState => ({
                topSelectedItemValue: null,
                selectedItemValue: null,
                topOverridden: this.props.configItemRequest.overridden
            }))
        }
        if (this.props.selectedItemValue !== this.state.topSelectedItemValue) {
            this.setState(prevState => ({
                selectedItemValue: null,
                addNewValueEnabled: false,
                addNewValue: '',
                multiAddEnabled: false,
                topSelectedItemValue: this.props.selectedItemValue
            }))
        }
    }

    onDelete = (valueToBeDeteleted) => {
        let updatedValues = this.getValue();
        delete updatedValues[valueToBeDeteleted];
        this.onChange("value", updatedValues)
    }

    onAddNewValueEnabled = (valueToBeDeteleted) => {
        this.setState(prevState => ({
            addNewValueEnabled: true
        }))
    }

    onAddNewValue = () => {
        let addNewValue = this.state.addNewValue.trim();
        if (addNewValue !== '') {
            if (this.state.multiAddEnabled) {
                let addNewValueArray = addNewValue.split(/[\n,]/).map(function (item) {
                    return item.trim();
                }).filter(Boolean);
                this.onChange("value", { ...addNewValueArray.reduce((a, v) => ({ ...a, [v]: {} }), {}), ...this.getValue() })
            } else {
                this.onChange("value", { [addNewValue]: {}, ...this.getValue() })
            }

            this.onClearAddNew();
        }
    }

    onClearAddNew = () => {
        this.setState(prevState => ({
            addNewValueEnabled: false,
            addNewValue: ''
        }))
    }

    onAddNewValueInputChange = (e) => {
        e.persist();
        if (validationUtils.validateAlphaNumbericWithCommaAndReturn(e.target.value)) {
            this.setState(prevState => ({
                addNewValue: e.target.value
            }));
        }
    }

    onToggleMultiAddEnabled = () => {
        this.setState(prevState => ({
            multiAddEnabled: !prevState.multiAddEnabled
        }))
    }
    toggleSelectItem = (value) => {
        this.setState(prevState => ({
            selectedItemValue: prevState.selectedItemValue === value ? null : value
        }))
    }

    getValue = () => {
        if (this.props.selectedItemValue && !this.props.isRoot && this.props.values) {
            return this.props.values[this.props.selectedItemValue]
        }
        return this.props.isRoot && this.props.values;
    }

    render() {
        const values = this.getValue();
        const { configItemRequest } = this.props;
        if (!configItemRequest) return null;

        return (
            <>
                <div className={getConfigBlockClasses(configItemRequest, "lux-ac-config-block--nested")}>
                    <div className="lux-ac-config-block__header lux-ac-config-block__header--nested">
                        <div className="lux-ac-config-block__title">
                            <span className="lux-ac-config-block__label">{this.props.levelLabel[this.props.level]}</span>
                            <span className="lux-ac-config-block__count">{values ? Object.keys(values).length : 0}</span>
                        </div>
                        {!configItemRequest.parentLocked && (
                            <div className="lux-appconfig-setting__actions">
                                {this.state.addNewValueEnabled && (
                                    <button type="button" className="lux-appconfig-icon-btn link" title="Toggle bulk add" onClick={this.onToggleMultiAddEnabled}>
                                        <i className={classNames("fe fe-list", { "text-muted": !this.state.multiAddEnabled })} />
                                    </button>
                                )}
                                {configItemRequest.overridden && (this.props.selectedItemValue || this.props.isRoot) && (
                                    <button type="button" className="lux-appconfig-icon-btn link" title="Add value" onClick={this.onAddNewValueEnabled}>
                                        <i className="fe fe-plus" />
                                    </button>
                                )}
                            </div>
                        )}
                    </div>
                    <div className="lux-ac-config-block__body appconfig-item multivalueitem">
                        <ul className="lux-ac-config-block__list">
                            {this.state.addNewValueEnabled && (this.props.selectedItemValue || this.props.isRoot) && (
                                <ConfigAddValueRow
                                    addNewValue={this.state.addNewValue}
                                    multiAddEnabled={this.state.multiAddEnabled}
                                    onValueChange={this.onAddNewValueInputChange}
                                    onSave={this.onAddNewValue}
                                    onClear={this.onClearAddNew}
                                    onToggleMulti={this.onToggleMultiAddEnabled}
                                    showMultiToggle
                                />
                            )}
                            {values && Object.keys(values).map((value, index) => (
                                <li
                                    key={value}
                                    onClick={() => this.toggleSelectItem(value)}
                                    className={classNames("lux-ac-config-block__list-item lux-ac-config-block__list-item--selectable multivalueitemvalue", {
                                        "is-selected": this.state.selectedItemValue === value,
                                    })}
                                >
                                    <span className="lux-ac-config-block__list-index">{index + 1}</span>
                                    <span className="lux-ac-config-block__list-value">{value}</span>
                                    {!configItemRequest.parentLocked && configItemRequest.overridden && (
                                        <button
                                            type="button"
                                            className="lux-appconfig-icon-btn link lux-ac-config-block__remove"
                                            title="Remove"
                                            onClick={(event) => {
                                                event.stopPropagation();
                                                this.onDelete(value);
                                            }}
                                        >
                                            <i className="fe fe-x" />
                                        </button>
                                    )}
                                </li>
                            ))}
                        </ul>
                    </div>
                </div>
                {this.props.level > 1 && (
                    <MultiLevelValueSection
                        configItemRequest={configItemRequest}
                        selectedItemValue={this.state.selectedItemValue}
                        isRoot={false}
                        values={values}
                        levelLabel={this.props.levelLabel}
                        level={this.props.level - 1}
                        onChange={this.onChange}
                    />
                )}
            </>
        );
    }
}



