import React from "react";
import classNames from "classnames/bind";

export function LuxDelFact({ label, value, icon, wide }) {
  return (
    <div className={classNames("lux-del-fact", { "lux-del-fact--wide": wide })}>
      <span className="lux-del-fact__label">{label}</span>
      <span className="lux-del-fact__value">
        {icon && <i className={`${icon} lux-del-fact__icon`} aria-hidden="true" />}
        {value || "—"}
      </span>
    </div>
  );
}

export function LuxDelFactGroup({ tone, emoji, title, children }) {
  return (
    <section className={classNames("lux-del-fact-group", tone && `is-${tone}`)}>
      <header className="lux-del-fact-group__head">
        <span className="lux-del-fact-group__emoji" aria-hidden="true">
          {emoji}
        </span>
        <h3 className="lux-del-fact-group__title">{title}</h3>
      </header>
      <div className="lux-del-fact-grid">{children}</div>
    </section>
  );
}

export function LuxDelSection({ icon, title, subtitle, children, flush }) {
  return (
    <section className={classNames("lux-del-section", { "is-flush": flush })}>
      <header className="lux-del-section__head">
        <span className="lux-del-section__icon" aria-hidden="true">
          <i className={icon} />
        </span>
        <div className="lux-del-section__copy">
          <h3 className="lux-del-section__title">{title}</h3>
          {subtitle && <p className="lux-del-section__subtitle">{subtitle}</p>}
        </div>
      </header>
      <div className="lux-del-section__body">{children}</div>
    </section>
  );
}

export function LuxDelTimelineStep({ label, value, active }) {
  return (
    <div className={classNames("lux-del-timeline__step", { "is-active": active })}>
      <span className="lux-del-timeline__dot" aria-hidden="true" />
      <div className="lux-del-timeline__content">
        <span className="lux-del-timeline__label">{label}</span>
        <span className="lux-del-timeline__value">{value || "—"}</span>
      </div>
    </div>
  );
}
