import dateUtils from "_helpers/date.utils";
import {
  employeeIdsMatch,
  formatPlannerHours,
  getItemEndDate,
  getItemStartDate,
  getWorkItemEmployeeId,
  getWorkItemStatusColor,
  normalizeWorkItemStatus,
} from "./planner.utils";
import { isEmployeeOnLeave, isPlannerLeaveOrHolidayItem } from "./plannerLeave.utils";
import { getActualMinutesForDay } from "./plannerTimesheet.utils";

/** Working hours shown in hourly grid (inclusive start, exclusive end for slots). */
export const PLANNER_HOUR_START = 8;
export const PLANNER_HOUR_END = 18;
export const PLANNER_HOUR_SLOT_MINUTES = 60;

export function getPlannerHourSlots() {
  const slots = [];
  for (let h = PLANNER_HOUR_START; h < PLANNER_HOUR_END; h += 1) {
    slots.push({
      hour: h,
      label: `${String(h).padStart(2, "0")}:00`,
      labelShort: `${h}`,
    });
  }
  return slots;
}

export function getOverlappedMinutesInHour(startDate, endDate, dayMoment, hour) {
  if (!startDate || !endDate) return 0;
  const slotStart = dayMoment.clone().hour(hour).minute(0).second(0);
  const slotEnd = slotStart.clone().add(PLANNER_HOUR_SLOT_MINUTES, "minutes");
  const itemStart = dateUtils.convertDateToMoment(startDate);
  const itemEnd = dateUtils.convertDateToMoment(endDate);
  const overlappedStart = itemStart.isAfter(slotStart) ? itemStart : slotStart;
  const overlappedEnd = itemEnd.isBefore(slotEnd) ? itemEnd : slotEnd;
  if (overlappedEnd.diff(overlappedStart, "minutes") <= 0) return 0;
  return overlappedEnd.diff(overlappedStart, "minutes");
}

export function buildEmployeeHourlyDay({
  employee,
  workItems,
  dayMoment,
  filterOptions,
  leaveMap,
  actualsByEmployee,
  showActuals,
}) {
  const dayKey = dayMoment.format("YYYY-MM-DD");
  const onLeave = isEmployeeOnLeave(leaveMap, employee.id, dayKey);
  const slots = getPlannerHourSlots();
  const hourCells = slots.map((slot) => {
    let allocated = 0;
    const items = [];
    if (onLeave) {
      return {
        ...slot,
        allocated: 0,
        capacity: PLANNER_HOUR_SLOT_MINUTES,
        free: 0,
        utilization: 0,
        items: [],
        hasBandwidth: false,
        isOnLeave: true,
      };
    }
    (workItems || []).forEach((item) => {
      if (isPlannerLeaveOrHolidayItem(item)) return;
      if (!employeeIdsMatch(getWorkItemEmployeeId(item), employee.id)) return;
      const start = getItemStartDate(item);
      if (!start) return;
      const end = getItemEndDate(item, start);
      const itemDay = dateUtils.convertDateToMoment(start).format("YYYY-MM-DD");
      if (itemDay !== dayMoment.format("YYYY-MM-DD")) return;
      const mins = getOverlappedMinutesInHour(start, end, dayMoment, slot.hour);
      if (mins <= 0) return;
      allocated += mins;
      items.push({ item, minutes: mins });
    });
    const capacity = PLANNER_HOUR_SLOT_MINUTES;
    const utilization = Math.round((allocated / capacity) * 100);
    return {
      ...slot,
      allocated,
      capacity,
      free: Math.max(0, capacity - allocated),
      utilization,
      items,
      hasBandwidth: allocated < capacity,
    };
  });

  const totalAllocated = hourCells.reduce((s, c) => s + c.allocated, 0);
  const totalCapacity = hourCells.length * PLANNER_HOUR_SLOT_MINUTES;

  const actualMinutes =
    showActuals && actualsByEmployee
      ? getActualMinutesForDay(actualsByEmployee, employee.id, dayKey)
      : 0;

  return {
    employee,
    dayMoment,
    dayKey,
    dateLabel: dayMoment.format("dddd, DD MMM YYYY"),
    isOnLeave: onLeave,
    actualMinutes,
    hourCells,
    totalAllocated,
    totalCapacity: onLeave ? 0 : totalCapacity,
    horizonUtilization: onLeave
      ? 0
      : Math.round((totalAllocated / Math.max(totalCapacity, 1)) * 100),
    chartSeries: hourCells.map((c) => Math.round((c.allocated / 60) * 10) / 10),
    chartCategories: hourCells.map((c) => c.labelShort),
  };
}

export function buildTeamHourlyGrid({
  employees,
  workItems,
  focusDayMoment,
  filterOptions,
  leaveMap,
  actualsByEmployee,
  showActuals,
}) {
  const roster = (employees || []).filter((e) => e != null && e.deleted !== true && e.active !== false);
  return roster.map((employee) =>
    buildEmployeeHourlyDay({
      employee,
      workItems,
      dayMoment: focusDayMoment.clone(),
      filterOptions,
      leaveMap,
      actualsByEmployee,
      showActuals,
    })
  );
}

export function formatHourRange(hour) {
  const end = hour + 1;
  return `${String(hour).padStart(2, "0")}:00–${String(end).padStart(2, "0")}:00`;
}

export function getStatusMeta(status) {
  const st = normalizeWorkItemStatus(status);
  const map = {
    ASSIGNED: { label: "Assigned", tone: "info", icon: "fe-user-check" },
    INPROGRESS: { label: "In progress", tone: "warn", icon: "fe-play-circle" },
    COMPLETED: { label: "Completed", tone: "good", icon: "fe-check-circle" },
    CLOSED: { label: "Closed", tone: "muted", icon: "fe-archive" },
    NEW: { label: "New", tone: "info", icon: "fe-star" },
    ONGOING: { label: "Ongoing", tone: "purple", icon: "fe-refresh-cw" },
    PAUSED: { label: "Paused", tone: "warn", icon: "fe-pause-circle" },
  };
  return map[st] || { label: st || "Unknown", tone: "muted", icon: "fe-circle" };
}

export function enrichWorkItemDetail(item, minutes) {
  const start = getItemStartDate(item);
  const end = start ? getItemEndDate(item, start) : null;
  const st = normalizeWorkItemStatus(item.status);
  return {
    item,
    minutes: minutes || item.estDurationInMins || 60,
    statusMeta: getStatusMeta(st),
    statusColor: getWorkItemStatusColor(st),
    startLabel: start ? dateUtils.convertDateToMoment(start).format("ddd DD MMM · HH:mm") : "—",
    endLabel: end ? dateUtils.convertDateToMoment(end).format("ddd DD MMM · HH:mm") : "—",
    durationLabel: formatPlannerHours(minutes || item.estDurationInMins || 60),
    projectName: item.projectName || "—",
    taskName: item.taskName || "—",
    category: item.taskActCategory || "—",
    employeeLabel: item.employeeName || (item.employee && item.employee.name) || "—",
  };
}
