import React, { PureComponent } from "react";
import { connect } from "react-redux";
import PageInnerHeader from "views/common/PageInnerHeader";
import { projectActions } from "_actions";
import { taskActions } from "_actions";
import { taskConstants } from "_constants";
import { accessUtils } from "_helpers";
import { commonUtils, store } from "_helpers";
import CreateTaskSidebar from "./components/modal/CreateTaskSidebar";
import ViewTaskDetailsSidebar from "./components/modal/ViewTaskDetailsSidebar";
import DeliverableListTable from "./components/DeliverableListTable";
import DeliverablePageSummary from "./components/DeliverablePageSummary";
import DeliverableProjectContext from "./components/DeliverableProjectContext";
import { buildDeliverableSummaryStats } from "./components/deliverableSummary.utils";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxRegisterFetchError from "views/common/fragments/LuxRegisterFetchError";
import { shouldShowRegisterFetchError } from "_helpers/registerListError.utils";
import {
  paginateRegisterList,
  REGISTER_DEFAULT_PAGE_SIZE,
  shouldResetRegisterPage,
} from "_helpers/registerPagination.utils";

class TaskListPage extends PureComponent {
  constructor() {
    super();
    this.state = {
      filterOptions: {
        SHOW: {
          options: [
            { name: "ALL", label: "All" },
            { name: "ONGOING", label: "On Going" },
            { name: "COMPLETED", label: "Completed" },
            { name: "MYASSIGNED", label: "My Assigned" },
            { name: "CREATEDBYME", label: "Created By Me" },
          ],
          selected: "ONGOING",
        },
        SORT: {
          options: [
            { name: "ESTIMATEDENDDATE", label: "Due Date" },
            { name: "ESTIMATEDSTARTDATE", label: "Est Start Date" },
            { name: "CREATEDDATE", label: "Created Date" },
            { name: "A-Z", label: "A-Z" },
          ],
          selected: "A-Z",
          directionUp: true,
        },
        filterText: null,
      },
      permission: accessUtils.getTaskAccessControl(),
      editMode: false,
      duplicateMode: false,
      projectId: null,
      page: 1,
      pageSize: REGISTER_DEFAULT_PAGE_SIZE,
    };
  }

  componentDidUpdate(prevProps) {
    if (shouldResetRegisterPage(prevProps, this.props)) {
      this.setState({ page: 1 });
    }
  }

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(
      this.props.routeProp.name + " : " + this.props.match.params.projectId
    );
    const projectId = commonUtils.removeNameIntial(this.props.match.params.projectId);
    store.dispatch(this.props.getProjectInfo(projectId));
    this.invokeTasksListService(projectId);
    this.setState({ projectId });
  }

  invokeTasksListService = (projectId) => {
    const pid = projectId || this.state.projectId;
    if (!pid) return;
    const userTeams = commonUtils.getUserTeams(this.props.userTeams);
    store.dispatch({ type: taskConstants.INITIALIZE_TASKS_USER_TEAMS, userTeams });
    this.reloadTasksListService(userTeams, pid);
  };

  reloadTasksListService = (userTeams, projectId) => {
    const pid = projectId || this.state.projectId;
    store.dispatch(this.props.getAllTasks({ projectId: pid }, this.state.filterOptions));
  };

  handlePageChange = (page) => {
    this.setState({ page });
  };

  handlePageSizeChange = (pageSize) => {
    this.setState({ pageSize, page: 1 });
  };

  onCreateItemClick = (e) => {
    e.preventDefault();
    this.setState({ editMode: false, duplicateMode: false });
    const defaultTeam = commonUtils.getCurrentUserTeamId();
    store.dispatch(this.props.initializeCreateTask(defaultTeam));
  };

  onCloseCreateItem = () => {
    store.dispatch({ type: taskConstants.CLOSE_TASK_CREATE_WINDOW });
  };

  handleDeleteTask = (taskIdTobeDeleted, isDelete) => {
    store.dispatch(this.props.deleteTask(taskIdTobeDeleted, isDelete));
  };

  handleEditTask = (taskId, projectId, taskUserTeamId) => {
    this.setState({ duplicateMode: false, editMode: true });
    store.dispatch(this.props.getTaskInfo(taskId, projectId));
    store.dispatch(this.props.initializeCreateTask(taskUserTeamId));
  };

  handleDuplicateTask = (taskId, projectId, taskUserTeamId) => {
    this.setState({ duplicateMode: true, editMode: false });
    store.dispatch(this.props.getTaskInfo(taskId, projectId));
    store.dispatch(this.props.initializeCreateTask(taskUserTeamId));
  };

  handleRemoveTask = (taskId) => {
    store.dispatch(this.props.removeTask(taskId));
  };

  onViewTask = (taskId, projectId) => {
    store.dispatch(this.props.getTaskInfo(taskId, projectId));
    store.dispatch({ type: taskConstants.SHOW_TASK_VIEW_WINDOW });
  };

  onCloseViewTask = () => {
    store.dispatch({ type: taskConstants.CLOSE_TASK_VIEW_WINDOW });
  };

  handleActivateTask = (taskId, isActive) => {
    store.dispatch(this.props.activateTask(taskId, isActive));
  };

  handleUpdateStatus = (taskId, status) => {
    store.dispatch(this.props.updateTaskStatus(taskId, status));
  };

  handleSubmit = (taskRequest, isEdtiMode, isCreateAnotherEnabled, callbackFunction) => {
    if (isEdtiMode) {
      store.dispatch(this.props.updateTask(taskRequest));
    } else {
      store.dispatch(this.props.createTask(taskRequest, isCreateAnotherEnabled, callbackFunction));
    }
  };

  onFilterTextChange = (value) => {
    this.setState(
      (prevState) => ({
        filterOptions: {
          ...prevState.filterOptions,
          filterText: value,
        },
      }),
      () => {
        this.handleFilterChange(this.state.filterOptions);
      }
    );
  };

  handleFilterChange = (filterOptions) => {
    this.setState({ filterOptions }, () => {
      store.dispatch({ type: taskConstants.CHANGE_FILTER_TASKS, filterOptions });
    });
  };

  handleSummaryQuickFilter = (showValue) => {
    const baseOptions = this.props.filterOptions || this.state.filterOptions;
    this.handleFilterChange({
      ...baseOptions,
      SHOW: { ...baseOptions.SHOW, selected: showValue },
    });
  };

  handleUserTeamsSelection = (userTeams) => {
    store.dispatch({ type: taskConstants.INITIALIZE_TASKS_USER_TEAMS, userTeams });
    this.reloadTasksListService(userTeams);
  };

  canCreateDeliverable = () => {
    return (
      this.state.permission.createEnabled &&
      this.props.projectInfo &&
      this.props.projectInfo.status === "INPROGRESS"
    );
  };

  render() {
    const allTasks = this.props.tasks || [];
    const pagination = paginateRegisterList(allTasks, this.state.page, this.state.pageSize);
    const filterOptions = this.props.filterOptions || this.state.filterOptions;
    const summaryStat = buildDeliverableSummaryStats(this.props.tasksRaw || allTasks);

    return (
      <div className="deliverablelist lux-bid-requests lux-deliverable-requests">
        <DeliverableProjectContext projectInfo={this.props.projectInfo} isLoading={this.props.isProjectLoading} />

        <PageInnerHeader
          userTeams={commonUtils.getUserTeams(this.props.userTeams)}
          handleUserTeamsSelection={this.handleUserTeamsSelection}
          showCreateMenu={this.canCreateDeliverable()}
          showFilter
          showUserTeamMenu
          isLoading={this.props.isLoading}
          filterOptions={filterOptions}
          handleFilterChange={this.handleFilterChange}
          onFilterTextChange={this.onFilterTextChange}
          showCreateMenuText="Create deliverable"
          createItemHandler={this.onCreateItemClick}
          permission={this.state.permission}
        />

        <DeliverablePageSummary
          stat={summaryStat}
          visibleCount={allTasks.length}
          filterOptions={filterOptions}
          isLoading={this.props.isLoading}
          onQuickFilter={this.handleSummaryQuickFilter}
        />

        {((allTasks.length > 0) || this.props.isLoading) && (
          <div className="lux-register-list-section">
            <DeliverableListTable
              tasks={pagination.items}
              totalCount={pagination.total}
              isLoading={this.props.isLoading}
              handleDeleteTask={this.handleDeleteTask}
              handleEditTask={this.handleEditTask}
              handleUpdateStatus={this.handleUpdateStatus}
              handleDuplicateTask={this.handleDuplicateTask}
              projectId={this.state.projectId}
              handleActivateTask={this.handleActivateTask}
              handleRemoveTask={this.handleRemoveTask}
              onViewTask={this.onViewTask}
              permission={this.state.permission}
              reloadDeliverables={() => this.invokeTasksListService()}
              pagination={pagination}
              onPageChange={this.handlePageChange}
              onPageSizeChange={this.handlePageSizeChange}
            />
          </div>
        )}

        {shouldShowRegisterFetchError({
          error: this.props.error,
          isLoading: this.props.isLoading,
          items: allTasks,
        }) && (
          <LuxRegisterFetchError
            error={this.props.error}
            onRetry={() => this.invokeTasksListService()}
          />
        )}

        {allTasks.length === 0 && !this.props.isLoading && !this.props.error && (
          <LuxRegisterEmptyState
            variant="deliverables"
            eyebrow="Project deliverables"
            title="No deliverables found"
            description="No deliverables match the selected teams or filters. Create a deliverable to break the project into trackable work packages."
            hints={[
              "Each deliverable can hold work items, estimates, and a checklist",
              "Use status and timeline to monitor delivery progress",
            ]}
            createLabel="Create deliverable"
            onCreate={this.onCreateItemClick}
            showCreate={this.canCreateDeliverable()}
          />
        )}

        {this.props.projectInfo && (
          <CreateTaskSidebar
            projectId={this.state.projectId}
            show={this.props.showCreateModel}
            userTeams={this.props.userTeams}
            closeActionHandler={this.onCloseCreateItem}
            editMode={this.state.editMode}
            duplicateMode={this.state.duplicateMode}
            selectedTaskInfo={this.props.selectedTaskInfo}
            handleSubmit={this.handleSubmit}
            projectInfo={this.props.projectInfo}
            permission={this.state.permission}
          />
        )}
        <ViewTaskDetailsSidebar show={this.props.isShowTaskViewSidebar} onCloseViewTask={this.onCloseViewTask} />
      </div>
    );
  }
}

const mapStateToProps = (state) => {
  const tasks = commonUtils.filterTasks(state.tasks.items, state.tasks.filterOptions);
  return {
  tasksRaw: state.tasks.items,
  items: tasks,
  tasks,
  projectInfo: state.projects.selectedProjectInfo,
  isProjectLoading: state.projects.getInfoLoading,
  isLoading: state.tasks.tasksLoading,
  error: state.tasks.error,
  userTeams: state.tasks.userTeams,
  filterOptions: state.tasks.filterOptions,
  showCreateModel: state.tasks.showCreateModel,
  isShowTaskViewSidebar: state.tasks.isShowTaskViewSidebar,
  selectedTaskInfo: state.tasks.selectedTaskInfo,
  };
};

const mapDispatchToProps = (dispatch) => ({
  getAllTasks: taskActions.getAllTasks,
  getTaskInfo: taskActions.getTaskInfo,
  getProjectInfo: projectActions.getProjectInfo,
  createTask: taskActions.createTask,
  updateTask: taskActions.updateTask,
  updateTaskStatus: taskActions.updateTaskStatus,
  activateTask: taskActions.activateTask,
  removeTask: taskActions.removeTask,
  deleteTask: taskActions.deleteTask,
  initializeCreateTask: taskActions.initializeCreateTask,
});

export default connect(mapStateToProps, mapDispatchToProps)(TaskListPage);
