import React, { useCallback, useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import DashboardApexChart from "views/hrms/components/dashboard/DashboardApexChart";
import { enrichWorkItemDetail } from "../plannerHourly.utils";
import { buildHourlyLoadChart } from "../plannerSummary.charts";
import PlannerLuxActions from "./PlannerLuxActions";
import { formatPlannerHours } from "../planner.utils";
import { measurePlannerOverlayTop } from "../plannerOverlay.utils";

export default function PlannerLuxPanel({
  open,
  onClose,
  title,
  subtitle,
  statusMeta,
  metrics,
  hourlyModel,
  assignments,
  primaryItem,
  actions,
  footer,
  bandwidthHint,
}) {
  const [panelTop, setPanelTop] = useState(0);
  const primary = primaryItem ? enrichWorkItemDetail(primaryItem.item || primaryItem, primaryItem.minutes) : null;

  const hourlyChart = useMemo(() => {
    if (!hourlyModel || !hourlyModel.chartSeries) return null;
    return buildHourlyLoadChart(hourlyModel.chartCategories, hourlyModel.chartSeries);
  }, [hourlyModel]);

  const syncPanelTop = useCallback(() => {
    setPanelTop(measurePlannerOverlayTop());
  }, []);

  useEffect(() => {
    if (!open) return undefined;
    syncPanelTop();
    window.addEventListener("resize", syncPanelTop);
    window.addEventListener("scroll", syncPanelTop, true);
    return () => {
      window.removeEventListener("resize", syncPanelTop);
      window.removeEventListener("scroll", syncPanelTop, true);
    };
  }, [open, syncPanelTop]);

  if (!open || typeof document === "undefined") return null;

  const panelStyle = {
    top: panelTop,
    height: `calc(100dvh - ${panelTop}px)`,
  };

  return createPortal(
    <div className="lux-planner-detail-portal" role="presentation">
      <button
        type="button"
        className="lux-planner-detail-portal__backdrop"
        aria-label="Close details"
        onClick={onClose}
      />
      <aside
        className={classNames("lux-planner-lux-panel", "lux-planner-lux-panel--overlay", "is-open")}
        style={panelStyle}
        role="dialog"
        aria-modal="true"
        aria-label={title}
      >
        <div className="lux-planner-lux-panel__sheet">
          <header className="lux-planner-lux-panel__hero">
            <div className="lux-planner-lux-panel__hero-bg" aria-hidden />
            <button type="button" className="lux-planner-lux-panel__close" onClick={onClose} aria-label="Close">
              <i className="fe fe-x" />
            </button>
            {statusMeta && (
              <span className={classNames("lux-planner-lux-panel__status", `is-${statusMeta.tone}`)}>
                <i className={`fe ${statusMeta.icon}`} />
                {statusMeta.label}
              </span>
            )}
            <h2>{title}</h2>
            {subtitle && <p>{subtitle}</p>}
            {bandwidthHint && (
              <div className="lux-planner-lux-panel__bandwidth">
                <i className="fe fe-sun" />
                {bandwidthHint}
              </div>
            )}
          </header>

          <div className="lux-planner-lux-panel__body">
            {metrics && metrics.length > 0 && (
              <div className="lux-planner-lux-panel__metrics">
                {metrics.map((m) => (
                  <div key={m.label} className={classNames("lux-planner-lux-metric", m.tone && `is-${m.tone}`)}>
                    <span>{m.label}</span>
                    <strong>{m.value}</strong>
                    {m.hint && <small>{m.hint}</small>}
                  </div>
                ))}
              </div>
            )}

            {primary && (
              <section className="lux-planner-lux-panel__primary">
                <h3>Work item</h3>
                <div className="lux-planner-lux-card">
                  <div className="lux-planner-lux-card__accent" style={{ background: primary.statusColor }} />
                  <div className="lux-planner-lux-card__main">
                    <strong>{primary.item.name || primary.item.taskActCategory || "Work item"}</strong>
                    <span>#{primary.item.id}</span>
                    <dl className="lux-planner-lux-dl">
                      <div><dt>Project</dt><dd>{primary.projectName}</dd></div>
                      <div><dt>Task</dt><dd>{primary.taskName}</dd></div>
                      <div><dt>Category</dt><dd>{primary.category}</dd></div>
                      <div><dt>Schedule</dt><dd>{primary.startLabel}</dd></div>
                      <div><dt>Due / end</dt><dd>{primary.endLabel}</dd></div>
                      <div><dt>Planned</dt><dd>{primary.durationLabel}</dd></div>
                    </dl>
                  </div>
                </div>
              </section>
            )}

            {hourlyChart && (
              <section className="lux-planner-lux-panel__chart">
                <h3>Hourly load (this day)</h3>
                <p className="lux-planner-lux-panel__chart-sub">Allocated hours per slot vs 1h capacity each.</p>
                <DashboardApexChart {...hourlyChart} />
              </section>
            )}

            {assignments && assignments.length > 0 && (
              <section className="lux-planner-lux-panel__list">
                <h3>Assignments ({assignments.length})</h3>
                <ul>
                  {assignments.map((entry) => {
                    const d = enrichWorkItemDetail(entry.item, entry.minutes);
                    return (
                      <li key={d.item.id} className="lux-planner-lux-list-item">
                        <span className="lux-planner-lux-list-item__dot" style={{ background: d.statusColor }} />
                        <div>
                          <strong>{d.item.name || d.item.taskActCategory}</strong>
                          <span>{[d.projectName, d.taskName, d.statusMeta.label].join(" · ")}</span>
                          <em>{d.durationLabel}</em>
                        </div>
                      </li>
                    );
                  })}
                </ul>
              </section>
            )}

            {actions && actions.length > 0 && (
              <section className="lux-planner-lux-panel__actions-wrap">
                <h3>Actions</h3>
                <PlannerLuxActions actions={actions} />
              </section>
            )}
          </div>

          {footer && <footer className="lux-planner-lux-panel__foot">{footer}</footer>}
        </div>
      </aside>
    </div>,
    document.body
  );
}

export function buildPanelMetricsFromCell(cell) {
  if (!cell) return [];
  const metrics = [];
  if (cell.isOnLeave) {
    metrics.push({ label: "Status", value: cell.leaveLabel || "Leave / PTO", tone: "purple" });
    return metrics;
  }
  metrics.push(
    { label: "Utilization", value: `${cell.utilization}%`, tone: cell.utilization > 100 ? "critical" : undefined },
    { label: "Planned", value: formatPlannerHours(cell.allocated) },
    { label: "Free", value: formatPlannerHours(cell.free), tone: "good" },
    { label: "Items", value: String((cell.items && cell.items.length) || 0) }
  );
  if (cell.actualMinutes != null && cell.actualMinutes > 0) {
    const delta = cell.varianceMins || 0;
    metrics.push({
      label: "Timesheet",
      value: formatPlannerHours(cell.actualMinutes),
      hint: delta === 0 ? "On plan" : `${delta > 0 ? "+" : ""}${formatPlannerHours(Math.abs(delta))} vs plan`,
      tone: delta > 60 ? "warn" : delta < -60 ? "good" : undefined,
    });
  }
  return metrics;
}

export function buildPanelMetricsFromRow(row) {
  if (!row) return [];
  return [
    { label: "Horizon load", value: `${row.horizonUtilization}%` },
    { label: "Free capacity", value: formatPlannerHours(row.freeMinutes), tone: "good" },
    { label: "Projects", value: String(row.activeProjects || 0) },
    { label: "Overbooked days", value: String(row.overbookedDays || 0), tone: row.overbookedDays ? "critical" : undefined },
  ];
}
