import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import { CALENDAR_EVENT_STATUS } from "./userCalendar.utils";

export default class UserCalendarSummary extends PureComponent {
  renderLegend = () => (
    <div className="lux-user-calendar-summary__legend" aria-label="Event status legend">
      {Object.keys(CALENDAR_EVENT_STATUS).map((key) => {
        const meta = CALENDAR_EVENT_STATUS[key];
        return (
          <span key={key} className={classNames("lux-user-calendar-summary__legend-item", `is-${meta.tone}`)}>
            <span className="lux-user-calendar-summary__legend-dot" aria-hidden="true" />
            {meta.label}
          </span>
        );
      })}
    </div>
  );

  render() {
    const { stat, viewModeLabel, periodLabel } = this.props;
    if (!stat) return null;

    return (
      <section className="lux-bid-summary lux-user-calendar-summary" aria-label="Calendar insights">
        <header className="lux-bid-summary__head">
          <LuxSummaryEyebrow variant="user-calendar" className="lux-bid-summary__eyebrow">
            Planning horizon
          </LuxSummaryEyebrow>
          <div className="lux-bid-summary__head-main">
            <h2 className="lux-bid-summary__title">Team calendar</h2>
            <p className="lux-bid-summary__context">
              {stat.total} in view · {stat.todayCount} today · {viewModeLabel || "work items"}
              {periodLabel ? ` · ${periodLabel}` : ""}
            </p>
          </div>
        </header>
        <div className="lux-bid-summary__kpi-strip" role="list">
          {stat.kpis.map((kpi) => (
            <article
              key={kpi.key}
              className={classNames("lux-bid-summary__kpi", kpi.tone && `is-${kpi.tone}`)}
              role="listitem"
            >
              <div className="lux-bid-summary__kpi-top">
                <span className="lux-bid-summary__kpi-label">{kpi.label}</span>
                <span className="lux-bid-summary__kpi-icon" aria-hidden="true">
                  <i className={kpi.icon} />
                </span>
              </div>
              <strong className="lux-bid-summary__kpi-value">
                <CountUp end={Number(kpi.value) || 0} duration={0.65} />
              </strong>
              {kpi.hint && <span className="lux-bid-summary__kpi-hint">{kpi.hint}</span>}
            </article>
          ))}
        </div>
        {this.renderLegend()}
      </section>
    );
  }
}
