import React from "react";
import classNames from "classnames/bind";
import dateUtils from "_helpers/date.utils";
import { formatEntryTotalLabel, getDayTotalHighlightLevel } from "./timesheetBoard.utils";
import { getTimesheetDayColumnClass } from "./TimesheetWeekRail";

function TimesheetBoardFooter({ weekDates, totalByDateMap, weekTotalMins, maxHoursAllowed, onDayClick }) {
  if (!weekDates || !weekDates.length) return null;

  return (
    <div className="lux-ts-board__footer-totals lux-ts-board__grid-row" role="row" aria-label="Daily totals">
      <div className="lux-ts-board__footer-meta lux-ts-board__col-meta">
        <span className="lux-ts-board__footer-meta-label">Daily total</span>
      </div>

      {weekDates.map((dateString, index) => {
        const dayTotal =
          (totalByDateMap && totalByDateMap[dateString] && totalByDateMap[dateString].totalMins) || 0;
        const highlightLevel = getDayTotalHighlightLevel(dayTotal);
        const overMax = dayTotal > parseInt(maxHoursAllowed || 0, 10) * 60;

        return (
          <div
            key={dateString}
            className={classNames(
              "lux-ts-board__footer-day",
              getTimesheetDayColumnClass(index),
              {
                "has-value": dayTotal > 0,
                "is-under-8h": highlightLevel === "under",
                "is-over-8h": highlightLevel === "over" || overMax,
                "is-on-target": highlightLevel === "target",
                "is-empty-day": highlightLevel === "empty",
                "is-clickable": !!onDayClick,
              }
            )}
            onClick={onDayClick ? () => onDayClick(dateString) : undefined}
            onKeyDown={
              onDayClick
                ? (event) => {
                    if (event.key === "Enter" || event.key === " ") onDayClick(dateString);
                  }
                : undefined
            }
            role={onDayClick ? "button" : undefined}
            tabIndex={onDayClick ? 0 : undefined}
            title={onDayClick ? `View ${dateString} summary` : undefined}
          >
            <span
              className={classNames("lux-ts-board__footer-day-value", {
                "is-under-8h": highlightLevel === "under",
                "is-over-8h": highlightLevel === "over" || overMax,
                "is-on-target": highlightLevel === "target",
              })}
            >
              {dateUtils.minuteToHourString(dayTotal)}
            </span>
          </div>
        );
      })}

      <div className="lux-ts-board__footer-grand lux-ts-board__col-tools">
        <span className="lux-ts-board__footer-grand-label">Total</span>
        <strong className="lux-ts-board__footer-grand-value">
          {formatEntryTotalLabel(weekTotalMins)}
        </strong>
      </div>
    </div>
  );
}

export default TimesheetBoardFooter;
