export const FILE_MIME_META = {
  folder: { icon: "fe-folder", tone: "indigo", label: "Folder" },
  pdf: { icon: "fe-file-text", tone: "rose", label: "PDF" },
  word: { icon: "fe-file", tone: "sky", label: "Document" },
  excel: { icon: "fe-grid", tone: "green", label: "Spreadsheet" },
  image: { icon: "fe-image", tone: "amber", label: "Image" },
  generic: { icon: "fe-file", tone: "slate", label: "File" },
};

export function getFileMimeMeta(mimeKind) {
  return FILE_MIME_META[mimeKind] || FILE_MIME_META.generic;
}

export function formatFileSize(bytes) {
  if (bytes == null || bytes === 0) return "—";
  const units = ["B", "KB", "MB", "GB", "TB"];
  let size = bytes;
  let unit = 0;
  while (size >= 1024 && unit < units.length - 1) {
    size /= 1024;
    unit += 1;
  }
  const decimals = unit === 0 ? 0 : size < 10 ? 1 : 0;
  return `${size.toFixed(decimals)}${units[unit]}`;
}

export function formatFileDate(isoDate) {
  if (!isoDate) return "—";
  const d = new Date(isoDate);
  if (Number.isNaN(d.getTime())) return isoDate;
  return d.toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" });
}

export function getOwnerInitials(owner) {
  if (!owner) return "?";
  const parts = String(owner).trim().split(/\s+/);
  if (parts.length >= 2) {
    return `${parts[0][0]}${parts[1][0]}`.toUpperCase();
  }
  return owner.slice(0, 2).toUpperCase();
}

export function getAllFileManagerItems() {
  return DEMO_ITEMS.map((item) => ({
    ...item,
    sizeLabel: item.type === "folder" && item.sizeBytes == null ? "—" : formatFileSize(item.sizeBytes),
    lastUpdatedLabel: formatFileDate(item.lastUpdated),
    isShared: !!(item.sharedWith && item.sharedWith.length > 0),
    isMine: item.owner === "Me",
  }));
}

export function getRecentFileManagerItems(items) {
  const starred = items.filter((i) => i.starred);
  const pool = starred.length >= 3 ? starred : items;
  return pool
    .slice()
    .sort((a, b) => new Date(b.lastUpdated) - new Date(a.lastUpdated))
    .slice(0, 4);
}

export function getFolderBreadcrumb(folderId, items) {
  const trail = [{ id: FILE_MANAGER_ROOT_ID, name: "All files" }];
  if (!folderId || folderId === FILE_MANAGER_ROOT_ID) return trail;

  const byId = {};
  items.forEach((i) => {
    if (i.type === "folder") byId[i.id] = i;
  });

  const chain = [];
  let current = byId[folderId];
  while (current) {
    chain.unshift({ id: current.id, name: current.name });
    current = current.parentId && current.parentId !== FILE_MANAGER_ROOT_ID ? byId[current.parentId] : null;
  }
  return trail.concat(chain);
}

function matchesFilterText(item, text) {
  if (!text) return true;
  const q = text.toLowerCase();
  return (
    item.name.toLowerCase().includes(q) ||
    item.owner.toLowerCase().includes(q) ||
    (item.sharedWith &&
      item.sharedWith.some((s) => s.name && s.name.toLowerCase().includes(q)))
  );
}

function matchesShowFilter(item, show) {
  switch (show) {
    case "FOLDERS":
      return item.type === "folder";
    case "FILES":
      return item.type === "file";
    case "SHARED":
      return item.isShared;
    case "MINE":
      return item.isMine;
    default:
      return true;
  }
}

export function filterFileManagerItems(items, { parentId, filterOptions }) {
  const show = (filterOptions && filterOptions.SHOW && filterOptions.SHOW.selected) || "ALL";
  const text = filterOptions && filterOptions.filterText;
  const sortKey = (filterOptions && filterOptions.SORT && filterOptions.SORT.selected) || "NAME";
  const sortUp = filterOptions && filterOptions.SORT && filterOptions.SORT.directionUp !== false;

  let list = items.filter(
    (item) =>
      item.parentId === (parentId || FILE_MANAGER_ROOT_ID) &&
      matchesShowFilter(item, show) &&
      matchesFilterText(item, text)
  );

  list.sort((a, b) => {
    let cmp = 0;
    if (sortKey === "DATE") {
      cmp = new Date(a.lastUpdated) - new Date(b.lastUpdated);
    } else if (sortKey === "SIZE") {
      cmp = (a.sizeBytes || 0) - (b.sizeBytes || 0);
    } else {
      cmp = a.name.localeCompare(b.name, undefined, { sensitivity: "base" });
    }
    if (a.type === "folder" && b.type !== "folder") return -1;
    if (a.type !== "folder" && b.type === "folder") return 1;
    return sortUp ? cmp : -cmp;
  });

  return list;
}

export function buildFileManagerSummary(items) {
  const files = items.filter((i) => i.type === "file");
  const folders = items.filter((i) => i.type === "folder");
  const shared = items.filter((i) => i.isShared);
  const totalBytes = items.reduce((sum, i) => sum + (i.sizeBytes || 0), 0);
  const mine = items.filter((i) => i.isMine);
  const storageLabel = formatFileSize(totalBytes);

  const kpis = [
    {
      key: "total",
      label: "Items",
      value: items.length,
      icon: "fe fe-layers",
      hint: `${folders.length} folders · ${files.length} files`,
    },
    {
      key: "storage",
      label: "Storage used",
      displayValue: storageLabel,
      icon: "fe fe-hard-drive",
      hint: "Across visible workspace",
      tone: "indigo",
    },
    {
      key: "shared",
      label: "Shared",
      value: shared.length,
      icon: "fe fe-users",
      hint: "With teammates",
      tone: shared.length > 0 ? "sky" : "slate",
    },
    {
      key: "mine",
      label: "Owned by you",
      value: mine.length,
      icon: "fe fe-user",
      hint: `${files.length} downloadable files`,
      tone: "green",
    },
  ];

  const highlights = [
    {
      key: "starred",
      label: "Starred",
      value: items.filter((i) => i.starred).length,
      tone: "amber",
      icon: "fe fe-star",
    },
    {
      key: "folders",
      label: "Folders",
      value: folders.length,
      tone: "indigo",
      icon: "fe fe-folder",
    },
    {
      key: "pdfs",
      label: "PDFs",
      value: files.filter((f) => f.mimeKind === "pdf").length,
      tone: "rose",
      icon: "fe fe-file-text",
    },
    {
      key: "docs",
      label: "Office docs",
      value: files.filter((f) => f.mimeKind === "word" || f.mimeKind === "excel").length,
      tone: "sky",
      icon: "fe fe-file",
    },
  ];

  return {
    total: items.length,
    files: files.length,
    folders: folders.length,
    shared: shared.length,
    storageLabel,
    kpis,
    highlights,
  };
}
