import React, { PureComponent } from "react";
import { connect } from "react-redux";
import { accessUtils, store, commonUtils } from "_helpers";
import { invoiceActions } from "_actions";
import { invoiceConstants } from "_constants";
import PageInnerHeader from "views/common/PageInnerHeader";
import CreateInvoiceSidebar from "views/project/components/modal/CreateInvoiceSidebar";
import InvoicePageSummary from "./components/invoice/InvoicePageSummary";
import InvoiceListTable from "./components/invoice/InvoiceListTable";
import {
  buildInvoiceSummaryStats,
  buildFyOutstandingInvoices,
  filterInvoices,
  getAvailableFinancialYears,
  getCurrentFinancialYearStartYear,
  INVOICE_DASHBOARD_SCOPE,
  INVOICE_LIST_LOAD_STEP,
  INVOICE_LIST_PAGE_SIZE,
  resolveDashboardFinancialYear,
} from "./components/invoice/invoice.utils";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxRegisterFetchError from "views/common/fragments/LuxRegisterFetchError";
import { shouldShowRegisterFetchError } from "_helpers/registerListError.utils";
import Skeleton from "react-loading-skeleton";

const DEFAULT_FILTER_OPTIONS = {
  SHOW: {
    options: [
      { name: "ALL", label: "All" },
      { name: "DRAFT", label: "Draft" },
      { name: "PENDING", label: "Pending" },
      { name: "APPROVED", label: "Approved" },
      { name: "PAID", label: "Paid" },
      { name: "CLOSED", label: "Closed" },
    ],
    selected: "ALL",
  },
  filterText: null,
  fyStartYear: null,
};

class InvoiceListPage extends PureComponent {
  constructor() {
    super();
    this.state = {
      permission: accessUtils.getInvoiceAccessControl(),
      filterOptions: DEFAULT_FILTER_OPTIONS,
      dashboardScope: INVOICE_DASHBOARD_SCOPE.CURRENT_FY,
      selectedFyStartYear: getCurrentFinancialYearStartYear(),
      listFyFilterEnabled: false,
    };
  }

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    if (!this.props.allItems) {
      this.invokeInvoiceListService();
    }
  }

  invokeInvoiceListService = () => {
    const limit = this.props.listLimit || INVOICE_LIST_PAGE_SIZE;
    store.dispatch(this.props.getAllInvoices(limit));
  };

  handleLoadMore = () => {
    store.dispatch(
      this.props.loadMoreInvoices(
        this.props.listLimit || INVOICE_LIST_PAGE_SIZE,
        INVOICE_LIST_LOAD_STEP
      )
    );
  };

  onOpenGenerateInvoice = (e) => {
    e.preventDefault();
    store.dispatch({ type: invoiceConstants.SHOW_INVOICE_CREATE_WINDOW });
  };

  onCloseGenerateInvoice = (e) => {
    e.preventDefault();
    store.dispatch({ type: invoiceConstants.CLOSE_INVOICE_CREATE_WINDOW });
  };

  handleInvoiceCreateSubmit = (invoiceRequest) => {
    store.dispatch(
      this.props.createInvoice(invoiceRequest, false, () => {
        store.dispatch({ type: invoiceConstants.CLOSE_INVOICE_CREATE_WINDOW });
        this.invokeInvoiceListService();
      })
    );
  };

  removeInvoice = (id) => {
    store.dispatch(this.props.removeInvoice(id));
  };

  handleUpdateStatus = (invoiceId, status) => {
    store.dispatch(this.props.updateInvoiceStatus(invoiceId, status));
  };

  onFilterChange = (filterOptions) => {
    this.setState({ filterOptions });
  };

  onFilterTextChange = (value) => {
    this.setState((prev) => ({
      filterOptions: {
        ...prev.filterOptions,
        filterText: value,
      },
    }));
  };

  handleSummaryQuickFilter = (statusValue) => {
    this.setState((prev) => ({
      filterOptions: {
        ...prev.filterOptions,
        SHOW: {
          ...prev.filterOptions.SHOW,
          selected: statusValue,
        },
      },
    }));
  };

  handleDashboardScopeChange = (scope, fyStartYear) => {
    const resolvedFy = resolveDashboardFinancialYear(
      scope,
      scope === INVOICE_DASHBOARD_SCOPE.FY ? fyStartYear : this.state.selectedFyStartYear
    );

    this.setState((prev) => {
      const listFyFilterEnabled =
        scope === INVOICE_DASHBOARD_SCOPE.ALL ? false : prev.listFyFilterEnabled;

      return {
        dashboardScope: scope,
        selectedFyStartYear:
          scope === INVOICE_DASHBOARD_SCOPE.FY
            ? fyStartYear
            : scope === INVOICE_DASHBOARD_SCOPE.CURRENT_FY
              ? getCurrentFinancialYearStartYear()
              : prev.selectedFyStartYear,
        listFyFilterEnabled,
        filterOptions: {
          ...prev.filterOptions,
          fyStartYear: listFyFilterEnabled ? resolvedFy : null,
        },
      };
    });
  };

  handleToggleListFyFilter = (enabled) => {
    const fyStartYear = resolveDashboardFinancialYear(
      this.state.dashboardScope,
      this.state.selectedFyStartYear
    );

    this.setState((prev) => ({
      listFyFilterEnabled: enabled,
      filterOptions: {
        ...prev.filterOptions,
        fyStartYear: enabled ? fyStartYear : null,
      },
    }));
  };

  handleFocusPending = () => {
    this.setState((prev) => {
      const fyStartYear = resolveDashboardFinancialYear(
        prev.dashboardScope,
        prev.selectedFyStartYear
      );

      return {
        listFyFilterEnabled: fyStartYear != null,
        filterOptions: {
          ...prev.filterOptions,
          SHOW: {
            ...prev.filterOptions.SHOW,
            selected: "PENDING",
          },
          fyStartYear,
        },
      };
    });
  };

  getListFilterOptions = () => {
    const { filterOptions, dashboardScope, selectedFyStartYear, listFyFilterEnabled } =
      this.state;

    if (!listFyFilterEnabled || dashboardScope === INVOICE_DASHBOARD_SCOPE.ALL) {
      return filterOptions;
    }

    return {
      ...filterOptions,
      fyStartYear: resolveDashboardFinancialYear(dashboardScope, selectedFyStartYear),
    };
  };

  renderLoadMore = (loadedCount, visibleCount, hasMore) => {
    const { isLoading, loadingMore } = this.props;

    if (isLoading && !loadingMore) return null;

    return (
      <div className="lux-invoice-load-more">
        <div className="lux-invoice-load-more__meta">
          <span>
            Showing <strong>{visibleCount}</strong>
            {visibleCount !== loadedCount && (
              <> of <strong>{loadedCount}</strong> loaded</>
            )}
            {" "}invoice{visibleCount === 1 ? "" : "s"}
          </span>
          {hasMore && (
            <span className="lux-invoice-load-more__hint">
              More invoices may be available — load additional history below.
            </span>
          )}
        </div>

        {hasMore && (
          <button
            type="button"
            className="lux-invoice-load-more__btn"
            onClick={this.handleLoadMore}
            disabled={loadingMore}
          >
            {loadingMore ? (
              <Skeleton width={100} height={14} borderRadius={4} />
            ) : (
              <>
                <i className="fe fe-plus-circle" aria-hidden="true" />
                Load {INVOICE_LIST_LOAD_STEP} more invoices
              </>
            )}
          </button>
        )}

        {!hasMore && loadedCount > 0 && (
          <span className="lux-invoice-load-more__done">
            <i className="fe fe-check-circle" aria-hidden="true" />
            All available invoices loaded
          </span>
        )}
      </div>
    );
  };

  render() {
    const { permission, dashboardScope, selectedFyStartYear, listFyFilterEnabled } =
      this.state;
    const listFilterOptions = this.getListFilterOptions();
    const visibleItems = filterInvoices(this.props.allItems, listFilterOptions);
    const loadedCount = this.props.allItems ? this.props.allItems.length : 0;
    const hasItems = visibleItems.length > 0;
    const showList = hasItems || this.props.isLoading;
    const dashboardFy = resolveDashboardFinancialYear(dashboardScope, selectedFyStartYear);
    const summaryStat = buildInvoiceSummaryStats(this.props.allItems, {
      fyStartYear: dashboardFy,
    });
    const outstanding =
      dashboardFy != null
        ? buildFyOutstandingInvoices(this.props.allItems, dashboardFy)
        : null;
    const availableFinancialYears = getAvailableFinancialYears(this.props.allItems);
    const isListFiltered =
      Boolean(listFilterOptions.filterText) ||
      listFilterOptions.SHOW.selected !== "ALL" ||
      listFilterOptions.fyStartYear != null;

    return (
      <div className="lux-invoice">
        <PageInnerHeader
          showUserTeamMenu={false}
          showFilter={true}
          showCreateMenu={permission.createEnabled === true}
          createItemHandler={this.onOpenGenerateInvoice}
          showCreateMenuText="Generate invoice"
          createMenuIcon="fe-file-plus"
          isLoading={this.props.isLoading && !this.props.loadingMore}
          permission={permission}
          filterOptions={listFilterOptions}
          handleFilterChange={this.onFilterChange}
          onFilterTextChange={this.onFilterTextChange}
        />

        <InvoicePageSummary
          stat={summaryStat}
          visibleCount={visibleItems.length}
          filterOptions={listFilterOptions}
          isLoading={this.props.isLoading && !this.props.loadingMore}
          canViewAmounts={permission.viewEnabled === true}
          onQuickFilter={this.handleSummaryQuickFilter}
          dashboardScope={dashboardScope}
          selectedFyStartYear={selectedFyStartYear}
          availableFinancialYears={availableFinancialYears}
          onDashboardScopeChange={this.handleDashboardScopeChange}
          listFyFilterEnabled={listFyFilterEnabled}
          onToggleListFyFilter={this.handleToggleListFyFilter}
          outstanding={outstanding}
          onFocusPending={this.handleFocusPending}
        />

        {showList && (
          <div className="lux-register-list-section">
            <InvoiceListTable
              items={visibleItems}
              header={this.props.header}
              isLoading={this.props.isLoading && !this.props.loadingMore}
              removeInvoice={this.removeInvoice}
              handleUpdateStatus={this.handleUpdateStatus}
              permission={permission}
            />
            {this.renderLoadMore(loadedCount, visibleItems.length, this.props.hasMore)}
          </div>
        )}

        {shouldShowRegisterFetchError({
          error: this.props.error,
          isLoading: this.props.isLoading,
          items: this.props.allItems,
        }) && (
          <LuxRegisterFetchError
            error={this.props.error}
            onRetry={this.invokeInvoiceListService}
          />
        )}

        {!hasItems && !this.props.isLoading && !this.props.error && (
          <LuxRegisterEmptyState
            variant="invoices"
            eyebrow="Billing register"
            title="No invoices found"
            description={
              isListFiltered
                ? "Nothing matches your search, status, or financial year filter. Broaden the filters or load additional records from the server."
                : "Your invoice register is empty for the current view. Generate a bill to track amounts, approvals, and payment status."
            }
            hints={
              isListFiltered
                ? [
                    "Clear the search box or set status to All",
                    "Toggle financial year scope in the summary panel",
                  ]
                : [
                    "Draft → Pending → Approved → Paid workflow",
                    "Link line items to contracts and delivery work",
                  ]
            }
            createLabel="Generate invoice"
            createIcon="fe fe-file-plus"
            onCreate={this.onOpenGenerateInvoice}
            showCreate={permission.createEnabled === true}
            secondaryLabel="Load more invoices"
            secondaryIcon="fe fe-plus-circle"
            onSecondary={this.handleLoadMore}
            showSecondary={this.props.hasMore === true}
            secondaryDisabled={this.props.loadingMore === true}
          />
        )}

        <CreateInvoiceSidebar
          show={this.props.showCreateModel === true}
          closeActionHandler={this.onCloseGenerateInvoice}
          handleSubmit={this.handleInvoiceCreateSubmit}
          isProcessing={this.props.creating === true}
        />
      </div>
    );
  }
}

const mapStateToProps = (state) => {
  const allItems =
    state.invoice.items &&
    commonUtils.sortArrayOfObjectsByDateField(
      state.invoice.items,
      "invoiceDateTime",
      false
    );

  return {
    authentication: state.authentication,
    isLoading: state.invoice.invoicesLoading,
    error: state.invoice.error,
    loadingMore: state.invoice.loadingMore,
    header: state.invoice.header,
    allItems,
    listLimit: state.invoice.listLimit || INVOICE_LIST_PAGE_SIZE,
    hasMore: state.invoice.hasMore === true,
    showCreateModel: state.invoice.showCreateModel,
    creating: state.invoice.creating,
  };
};

const mapDispatchToProps = () => ({
  getAllInvoices: invoiceActions.getAllInvoices,
  loadMoreInvoices: invoiceActions.loadMoreInvoices,
  getInvoiceInfo: invoiceActions.getInvoiceInfo,
  createInvoice: invoiceActions.createInvoice,
  updateInvoice: invoiceActions.updateInvoice,
  updateInvoiceStatus: invoiceActions.updateInvoiceStatus,
  removeInvoice: invoiceActions.removeInvoice,
});

export default connect(mapStateToProps, mapDispatchToProps)(InvoiceListPage);
