import React, { Component } from "react";
import { NavLink } from "react-router-dom";
import classNames from "classnames/bind";

class Menu extends Component {

  activeRoute(routeName) {
    let layoutAndPage = this.props.location.pathname.split("/");
    if (layoutAndPage.length > 2 && routeName === "/" + layoutAndPage[1]) {
      return true;
    }
    return false;
  }

  activeRoutePage(routeName) {
    return this.props.location.pathname.indexOf(routeName) > -1 ? "active" : "";
  }

  getChildRouteCount = () => {
    return this.props.routes.filter((prop) =>
      prop.layout === this.props.layoutName &&
      prop.showInMenu &&
      this.props.menuAccessControl &&
      this.props.menuAccessControl[prop.layout.substring(1) + "Modules"][prop.path.substring(1) + "Enabled"] === true
    ).length;
  }

  render() {
    const isExpanded = this.activeRoute(this.props.layoutName);
    const childCount = this.getChildRouteCount();

    return (
      <li className={classNames("lux-nav__group", { active: isExpanded })}>
        <a
          href="#"
          className="has-arrow arrow-c lux-nav__parent"
          aria-expanded={isExpanded}
        >
          <span className="lux-nav__icon"><i className={this.props.icon} /></span>
          <span className="lux-nav__label">{this.props.menuName}</span>
          <span className="lux-nav__count">{childCount}</span>
        </a>
        <ul
          className={isExpanded ? "collapse in lux-nav__children" : "collapse lux-nav__children"}
          aria-expanded={isExpanded}
          style={{ height: isExpanded ? "unset" : "0px" }}
        >
          {this.props.routes.map((prop, key) => {
            if (prop.layout === this.props.layoutName && prop.showInMenu && this.props.menuAccessControl && this.props.menuAccessControl[prop.layout.substring(1) + "Modules"][prop.path.substring(1) + "Enabled"] === true)
              return (
                <li
                  className={this.activeRoutePage(prop.layout + prop.path)}
                  key={key}
                >
                  <NavLink
                    to={prop.layout + prop.path}
                    className="nav-link list-b lux-nav__child"
                    activeClassName="active"
                  >
                    <span>{prop.name}</span>
                  </NavLink>
                </li>
              );
            return null;
          })}
        </ul>
      </li>
    );
  }
}

export default Menu;
