import dateUtils from "_helpers/date.utils";

export function getDayHeaderMeta(dateString) {
  const momentDate = dateUtils.convertDateStringToMoment(dateString);
  const today = dateUtils.getCurrentTime().format(dateUtils.CLIENT_DATE_FORMAT);
  const isoWeekday = momentDate && momentDate.isoWeekday();
  return {
    isToday: dateString === today,
    isSaturday: isoWeekday === 6,
    isSunday: isoWeekday === 7,
    dayShort: momentDate && momentDate.isValid() ? momentDate.format("ddd") : dateString.slice(5),
    dayNum: momentDate && momentDate.isValid() ? momentDate.format("D") : "",
  };
}

export function computeEntryWeekTotalMins(timeSheetTaskItem, weekDates) {
  const timeEntry = (timeSheetTaskItem && timeSheetTaskItem.timeEntry) || {};
  let total = 0;
  weekDates.forEach((dateString) => {
    total += parseInt((timeEntry[dateString] && timeEntry[dateString].timesheetTimeMins) || 0, 10);
  });
  return total;
}

export function formatEntryTotalLabel(totalMins) {
  if (!totalMins) return "0h";
  const h = Math.floor(totalMins / 60);
  const m = totalMins % 60;
  return m > 0 ? `${h}h ${m}m` : `${h}h`;
}

export function getHourLevelFromMins(mins) {
  const h = mins / 60;
  if (h <= 0) return 0;
  if (h <= 2) return 1;
  if (h <= 4) return 2;
  if (h <= 6) return 3;
  return 4;
}

export function countEntriesWithHours(timeSheetRequest, weekDates) {
  let count = 0;
  if (!timeSheetRequest) return 0;
  Object.keys(timeSheetRequest).forEach((timesheetType) => {
    const groups = timeSheetRequest[timesheetType];
    if (!groups) return;
    Object.keys(groups).forEach((groupId) => {
      const tasks = groups[groupId] && groups[groupId].tasks;
      if (!tasks) return;
      tasks.forEach((task) => {
        const total = computeEntryWeekTotalMins(task, weekDates);
        if (total > 0) count += 1;
      });
    });
  });
  return count;
}

export function isLeaveOrHolidayGroup(groupId) {
  const key = (groupId || "").toLowerCase();
  return key === "leave" || key === "holiday";
}

export function getLeaveHolidayKind(groupId, taskActCategory) {
  const groupKey = (groupId || "").toLowerCase();
  const category = (taskActCategory || "").toUpperCase();
  if (groupKey === "leave" || category === "LEAVE") return "leave";
  if (groupKey === "holiday" || category === "HOLIDAY") return "holiday";
  return null;
}

export function buildGroupScrollId(timesheetType, groupId) {
  return `lux-ts-group-${timesheetType}-${groupId}`;
}

/** Standard workday target for highlighting (8 hours). */
export const DAILY_TARGET_MINS = 8 * 60;

/** Classify daily total vs 8h target: empty | under | target | over */
export function getDayTotalHighlightLevel(totalMins) {
  const mins = parseInt(totalMins || 0, 10);
  if (mins <= 0) return "empty";
  if (mins > DAILY_TARGET_MINS) return "over";
  if (mins < DAILY_TARGET_MINS) return "under";
  return "target";
}

export function buildDailyTotalsMap(timeSheetRequest, weekDates) {
  const totalByDateMap = {};
  weekDates.forEach((dateString) => {
    totalByDateMap[dateString] = {
      totalMins: 0,
      billableMins: 0,
      nonProjectMins: 0,
      leaveOrHolidayMins: 0,
    };
  });

  if (!timeSheetRequest) return totalByDateMap;

  Object.keys(timeSheetRequest).forEach((timesheetType) => {
    const taskGroupItems = timeSheetRequest[timesheetType];
    if (!taskGroupItems) return;

    Object.keys(taskGroupItems).forEach((taskGroupId) => {
      const timeEntryTaskSection = taskGroupItems[taskGroupId];
      const timeSheetTaskList = timeEntryTaskSection && timeEntryTaskSection.tasks;
      if (!timeSheetTaskList) return;

      timeSheetTaskList.forEach((timeSheetTaskItem) => {
        const timeEntry = timeSheetTaskItem && timeSheetTaskItem.timeEntry;
        if (!timeEntry) return;

        Object.keys(timeEntry).forEach((dateString) => {
          if (!weekDates.includes(dateString)) return;
          const time = parseInt((timeEntry[dateString] && timeEntry[dateString].timesheetTimeMins) || 0, 10);
          totalByDateMap[dateString].totalMins += time;
          if (timesheetType === "project") {
            totalByDateMap[dateString].billableMins += time;
          } else if (timesheetType === "nonProject") {
            if (
              timeSheetTaskItem.taskActCategory &&
              (timeSheetTaskItem.taskActCategory.toLowerCase() === "leave" ||
                timeSheetTaskItem.taskActCategory.toLowerCase() === "holiday")
            ) {
              totalByDateMap[dateString].leaveOrHolidayMins += time;
            } else {
              totalByDateMap[dateString].nonProjectMins += time;
            }
          }
        });
      });
    });
  });

  return totalByDateMap;
}
