import React, { Component } from "react";
import classNames from "classnames/bind";

const ATTACH_ICONS = {
  excel: { icon: "fe-grid", tone: "green" },
  word: { icon: "fe-file", tone: "sky" },
  pdf: { icon: "fe-file-text", tone: "rose" },
};

export default class ChatThread extends Component {
  constructor(props) {
    super(props);
    this.state = { draft: "" };
    this.scrollRef = React.createRef();
  }

  componentDidUpdate() {
    const el = this.scrollRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }

  onDraftChange = (e) => this.setState({ draft: e.target.value });

  onSend = () => {
    if (!this.state.draft.trim()) return;
    if (this.props.onSend) this.props.onSend(this.state.draft.trim());
    this.setState({ draft: "" });
  };

  onKeyDown = (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      this.onSend();
    }
  };

  renderMessage = (msg) => (
    <li
      key={msg.id}
      className={classNames("lux-chat-msg", { "is-mine": msg.isMine, "is-other": !msg.isMine })}
    >
      {!msg.isMine && (
        <span className="lux-chat-msg__avatar" aria-hidden="true">
          {msg.initials}
        </span>
      )}
      <div className="lux-chat-msg__bubble">
        {!msg.isMine && <span className="lux-chat-msg__author">{msg.author}</span>}
        {msg.text && <p className="lux-chat-msg__text">{msg.text}</p>}
        {msg.attachments &&
          msg.attachments.map((file) => {
            const meta = ATTACH_ICONS[file.kind] || { icon: "fe-file", tone: "slate" };
            return (
              <button key={file.name} type="button" className={classNames("lux-chat-msg__file", `is-${meta.tone}`)}>
                <i className={meta.icon} aria-hidden="true" />
                <span>
                  <strong>{file.name}</strong>
                  <em>{file.size}</em>
                </span>
              </button>
            );
          })}
        <time className="lux-chat-msg__time">{msg.time}</time>
      </div>
    </li>
  );

  render() {
    const { thread, messages } = this.props;
    if (!thread) {
      return (
        <section className="lux-chat-thread lux-chat-thread--empty">
          <div className="lux-chat-thread__empty">
            <i className="fe fe-message-circle" aria-hidden="true" />
            <h3>Select a conversation</h3>
            <p>Choose a person or group from the sidebar to view messages.</p>
          </div>
        </section>
      );
    }

    return (
      <section className="lux-chat-thread" aria-label={`Chat with ${thread.name}`}>
        <header className="lux-chat-thread__head">
          <div className="lux-chat-thread__identity">
            <span className={classNames("lux-chat-thread__avatar", `is-${thread.status}`)}>
              {thread.initials}
            </span>
            <div>
              <h3 className="lux-chat-thread__title">{thread.name}</h3>
              <p className="lux-chat-thread__meta">
                {thread.status === "online" ? "Online" : "Last seen 2 hours ago"}
                {thread.members && (
                  <>
                    <span className="lux-chat-thread__dot">·</span>
                    {thread.members} members
                  </>
                )}
              </p>
            </div>
          </div>
          <div className="lux-chat-thread__actions">
            <button type="button" className="lux-chat-thread__action" title="Search in thread">
              <i className="fe fe-search" aria-hidden="true" />
            </button>
            <button type="button" className="lux-chat-thread__action" title="Thread settings">
              <i className="fe fe-settings" aria-hidden="true" />
            </button>
          </div>
        </header>
        <ul className="lux-chat-thread__messages" ref={this.scrollRef}>
          {messages.map((msg) => this.renderMessage(msg))}
        </ul>
        <footer className="lux-chat-thread__composer">
          <div className="lux-chat-thread__composer-tools">
            <button type="button" title="Attach file"><i className="fe fe-paperclip" aria-hidden="true" /></button>
            <button type="button" title="Add image"><i className="fe fe-image" aria-hidden="true" /></button>
          </div>
          <textarea
            rows={1}
            placeholder="Write a message…"
            value={this.state.draft}
            onChange={this.onDraftChange}
            onKeyDown={this.onKeyDown}
            aria-label="Message"
          />
          <button
            type="button"
            className="lux-chat-thread__send"
            onClick={this.onSend}
            disabled={!this.state.draft.trim()}
            aria-label="Send message"
          >
            <i className="fe fe-send" aria-hidden="true" />
          </button>
        </footer>
      </section>
    );
  }
}
