import React, { Component } from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import { store } from "_helpers";

const TILES = [
  { key: "completedCount", label: "Completed", tone: "green", icon: "fe fe-check-circle" },
  { key: "inProgressCount", label: "In progress", tone: "amber", icon: "fe fe-loader" },
  { key: "assignedCount", label: "Assigned", tone: "slate", icon: "fe fe-user-check" },
  { key: "newCount", label: "New", tone: "rose", icon: "fe fe-star" },
];

/** Work item KPI strip inside deliverable overview tab */
export default class DeliverableDetailsSummaryStats extends Component {
  componentDidMount() {
    if (this.props.itemId && this.props.loadData) {
      store.dispatch(this.props.loadData(this.props.itemId));
    }
  }

  sum = (key) => {
    if (!this.props.items) return 0;
    return this.props.items.reduce((total, item) => total + (item[key] || 0), 0);
  };

  render() {
    return (
      <div className="lux-del-kpi-strip" aria-label="Work item summary">
        {TILES.map((tile) => (
          <article
            key={tile.key}
            className={classNames("lux-del-kpi", `is-${tile.tone}`)}
          >
            <span className="lux-del-kpi__icon" aria-hidden="true">
              <i className={tile.icon} />
            </span>
            <div className="lux-del-kpi__body">
              <strong className="lux-del-kpi__value">
                <CountUp end={this.sum(tile.key)} duration={0.8} />
              </strong>
              <span className="lux-del-kpi__label">{tile.label}</span>
            </div>
          </article>
        ))}
      </div>
    );
  }
}
