import React, { Component } from "react";
import FileDropZone from "views/common/plugins/FileDropZone";

class BidRequestQuestions extends Component {
  constructor() {
    super();
    this.state = {
      expand: true,
      isFileUploadEnabled: false,
      isTextEditorEnabled: false,
      isQuestionaireEnabled: true,
    };
  }

  componentDidMount() {
    const list =
      this.props.questionData && this.props.questionData.questionnaireList;
    this.setState({
      isFileUploadEnabled: list && list.find((qd) => qd.type === "file"),
      isTextEditorEnabled: list && list.find((qd) => qd.type === "html"),
      isQuestionaireEnabled: list && list.some((qd) => qd.type === "questions"),
    });
  }

  toggleExpand = (expand) => this.setState({ expand });

  toggleFileupload = (isFileUpload) => {
    this.setState({
      isFileUploadEnabled: isFileUpload,
      isTextEditorEnabled: false,
      isQuestionaireEnabled: false,
    });
  };

  toggleTextEditor = (isTextEditor) => {
    this.setState({
      isTextEditorEnabled: isTextEditor,
      isFileUploadEnabled: false,
      isQuestionaireEnabled: false,
    });
  };

  toggleQuestioner = (isQuestionaireEnabled) => {
    this.setState({
      isQuestionaireEnabled,
      isFileUploadEnabled: false,
      isTextEditorEnabled: false,
    });
  };

  onTextEditorChange = (value) => {
    this.onChange({ type: "html", html: value });
  };

  onChange = (value) => {
    this.props.onChange(this.props.name, { questionnaireList: [value] });
  };

  getQuestions = () => {
    const questionsType =
      this.props.questionData &&
      this.props.questionData.questionnaireList &&
      this.props.questionData.questionnaireList.find((qd) => qd.type === "questions");
    return (questionsType && questionsType.questions) || this.props.questionsConfig;
  };

  onQuestionChange = (questionId, e) => {
    e.persist();
    const { value, type, checked } = e.target;
    const newAnswer =
      type === "checkbox"
        ? checked
        : type === "radio"
        ? value === "true"
        : value;
    const updatedQuestions = this.getQuestions().map((question) => {
      if (question.id === questionId) {
        const { answer, ...questionCopy } = question;
        return { ...questionCopy, answer: newAnswer };
      }
      return question;
    });
    this.onChange({ type: "questions", questions: updatedQuestions });
  };

  render() {
    const htmlValueType =
      this.props.questionData &&
      this.props.questionData.questionnaireList &&
      this.props.questionData.questionnaireList.find((qd) => qd.type === "html");
    const questions = this.getQuestions();
    const htmlValue = (htmlValueType && htmlValueType.html) || "";

    return (
      <div className="lux-bid-questions">
        <div className="lux-bid-questions__header">
          <span className="lux-bid-questions__title">
            <i className="fe fe-help-circle" aria-hidden="true" />
            {this.props.header}
          </span>
          <div className="lux-bid-questions__tools">
            {this.state.expand && !this.props.readOnly && (
              <>
                <button
                  type="button"
                  className={`lux-bid-questions__tool ${
                    this.state.isFileUploadEnabled ? "is-active" : ""
                  }`}
                  title="File upload"
                  onClick={() => this.toggleFileupload(!this.state.isFileUploadEnabled)}
                >
                  <i className="fe fe-upload" aria-hidden="true" />
                </button>
                <button
                  type="button"
                  className={`lux-bid-questions__tool ${
                    this.state.isTextEditorEnabled ? "is-active" : ""
                  }`}
                  title="Rich text"
                  onClick={() => this.toggleTextEditor(!this.state.isTextEditorEnabled)}
                >
                  <i className="fe fe-edit-2" aria-hidden="true" />
                </button>
                <button
                  type="button"
                  className={`lux-bid-questions__tool ${
                    this.state.isQuestionaireEnabled ? "is-active" : ""
                  }`}
                  title="Questionnaire"
                  onClick={() => this.toggleQuestioner(!this.state.isQuestionaireEnabled)}
                >
                  <i className="fe fe-list" aria-hidden="true" />
                </button>
              </>
            )}
            <button
              type="button"
              className="lux-bid-questions__tool"
              title={this.state.expand ? "Collapse" : "Insights"}
              onClick={() => this.toggleExpand(!this.state.expand)}
            >
              <i
                className={`fe fe-chevron-${this.state.expand ? "up" : "down"}`}
                aria-hidden="true"
              />
            </button>
          </div>
        </div>
        {this.state.expand && (
          <div className="lux-bid-questions__body">
            {this.state.isTextEditorEnabled && (
              <div className="lux-bid-questions__editor">
                {this.props.readOnly ? (
                  htmlValue || ""
                ) : (
                  <textarea
                    rows={5}
                    value={htmlValue}
                    onChange={(e) => this.onTextEditorChange(e.target.value)}
                  />
                )}
              </div>
            )}
            {this.state.isFileUploadEnabled && <FileDropZone selectedFiles={null} />}
            {this.state.isQuestionaireEnabled && (
              <div>
                {questions &&
                  questions.map((question) => (
                    <div key={question.id} className="lux-bid-questions__row">
                      <div className="lux-bid-questions__label">{question.name}</div>
                      <div>
                        {this.props.readOnly && (
                          <>
                            {question.type === "boolean"
                              ? question.answer === "false"
                                ? "No"
                                : "Yes"
                              : question.answer || "NA"}
                          </>
                        )}
                        {!this.props.readOnly && (
                          <>
                            {question.type === "string" && (
                              <input
                                type="text"
                                className="form-control input-sm filter"
                                value={question.answer || ""}
                                onChange={(event) =>
                                  this.onQuestionChange(question.id, event)
                                }
                              />
                            )}
                            {question.type === "number" && (
                              <input
                                type="number"
                                className="form-control input-sm filter"
                                value={question.answer || ""}
                                onChange={(event) =>
                                  this.onQuestionChange(question.id, event)
                                }
                              />
                            )}
                            {question.type === "boolean" && (
                              <div className="custom-controls-stacked mt-2">
                                <label className="custom-control custom-radio custom-control-inline">
                                  <input
                                    type="radio"
                                    className="custom-control-input"
                                    name={this.props.name}
                                    value={true}
                                    checked={
                                      question.answer !== undefined &&
                                      question.answer === true
                                    }
                                    onChange={(event) =>
                                      this.onQuestionChange(question.id, event)
                                    }
                                  />
                                  <div className="custom-control-label">Yes</div>
                                </label>
                                <label className="custom-control custom-radio custom-control-inline">
                                  <input
                                    type="radio"
                                    className="custom-control-input"
                                    name={this.props.name}
                                    value={false}
                                    checked={
                                      question.answer !== undefined &&
                                      question.answer === false
                                    }
                                    onChange={(event) =>
                                      this.onQuestionChange(question.id, event)
                                    }
                                  />
                                  <div className="custom-control-label">No</div>
                                </label>
                              </div>
                            )}
                          </>
                        )}
                      </div>
                    </div>
                  ))}
              </div>
            )}
          </div>
        )}
      </div>
    );
  }
}

export default BidRequestQuestions;
