import React from "react";
import classNames from "classnames";

export const LuxHeaderDropdownEmpty = ({ icon = "fe fe-inbox", title, hint }) => (
  <div className="lux-header-dropdown__empty">
    <span className="lux-header-dropdown__empty-icon" aria-hidden="true">
      <i className={icon} />
    </span>
    <strong>{title}</strong>
    {hint && <span>{hint}</span>}
  </div>
);

export const LuxHeaderDropdownItem = ({
  as: Component = "button",
  className,
  icon,
  iconTone,
  title,
  hint,
  children,
  ...props
}) => (
  <Component
    type={Component === "button" ? "button" : undefined}
    className={classNames("lux-header-dropdown__item", className, {
      [`is-${iconTone}`]: iconTone,
    })}
    {...props}
  >
    {icon && (
      <span className={classNames("lux-header-dropdown__item-icon", iconTone && `is-${iconTone}`)} aria-hidden="true">
        <i className={icon} />
      </span>
    )}
    <span className="lux-header-dropdown__item-copy">
      <strong>{title || children}</strong>
      {hint && <span>{hint}</span>}
    </span>
  </Component>
);

const LuxHeaderDropdownPanel = ({
  icon,
  eyebrow,
  title,
  subtitle,
  children,
  footer,
  className,
  widthClass,
  tone = "default",
  headAvatar,
}) => (
  <div
    className={classNames(
      "dropdown-menu dropdown-menu-right lux-header-dropdown",
      widthClass,
      tone && `lux-header-dropdown--tone-${tone}`,
      className
    )}
  >
    <header className="lux-header-dropdown__head">
      {headAvatar ? (
        <span className="lux-header-dropdown__head-avatar">{headAvatar}</span>
      ) : (
        <span className="lux-header-dropdown__head-icon" aria-hidden="true">
          <i className={icon} />
        </span>
      )}
      <div className="lux-header-dropdown__head-copy">
        <span className="lux-header-dropdown__eyebrow">{eyebrow}</span>
        <strong>{title}</strong>
        {subtitle && <span className="lux-header-dropdown__subtitle">{subtitle}</span>}
      </div>
    </header>
    <div className="lux-header-dropdown__body">{children}</div>
    {footer && <footer className="lux-header-dropdown__foot">{footer}</footer>}
  </div>
);

export default LuxHeaderDropdownPanel;
