const FONT_IDS = FONT_OPTIONS.map((font) => font.id);

const LEGACY_FONT_MAP = {
  'font-roboto': 'roboto',
  'font-opensans': 'open-sans',
  'font-montserrat': 'montserrat',
};

const FONT_FALLBACK = '-apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';

export const LAYOUT_TOGGLES = [
  {
    id: 'stickyHeader',
    label: 'Sticky header',
    description: 'Keep the top bar visible while scrolling',
    icon: 'fe-anchor',
  },
  {
    id: 'elevatedSurfaces',
    label: 'Elevated surfaces',
    description: 'Add soft depth to cards, buttons, and progress bars',
    icon: 'fe-layers',
  },
];

const DEFAULT_SETTINGS = {
  font: 'inter',
  stickyHeader: true,
  elevatedSurfaces: false,
};

export function getFontOption(fontId) {
  const normalized = LEGACY_FONT_MAP[fontId] || fontId;
  return FONT_OPTIONS.find((font) => font.id === normalized) || FONT_OPTIONS[0];
}

function buildFontStack(family) {
  return `${family}, ${FONT_FALLBACK}`;
}

function normalizeSettings(settings) {
  const next = { ...DEFAULT_SETTINGS, ...settings };
  next.font = getFontOption(next.font).id;
  return next;
}

export function getUiSettings() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { ...DEFAULT_SETTINGS };
    return normalizeSettings(JSON.parse(raw));
  } catch (e) {
    return { ...DEFAULT_SETTINGS };
  }
}

function persistUiSettings(settings) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
  } catch (e) {
    /* ignore storage errors */
  }
}

function ensureFontLoaded(fontOption) {
  if (!fontOption || !fontOption.googleFamily) return;

  const linkId = `lux-font-${fontOption.id}`;
  if (document.getElementById(linkId)) return;

  const link = document.createElement('link');
  link.id = linkId;
  link.rel = 'stylesheet';
  link.href = `https://fonts.googleapis.com/css2?family=${fontOption.googleFamily}&display=swap`;
  document.head.appendChild(link);
}

function applyFont(fontId) {
  const fontOption = getFontOption(fontId);
  const stack = buildFontStack(fontOption.family);

  ensureFontLoaded(fontOption);

  document.documentElement.setAttribute('data-lux-font', fontOption.id);
  document.documentElement.style.setProperty('--app-font-sans', stack);

  if (document.body) {
    document.body.style.setProperty('--app-font-sans', stack);
  }

  const root = document.getElementById('root');
  if (root) {
    root.style.setProperty('--app-font-sans', stack);
  }

  const mainContent = document.getElementById('main_content');
  if (mainContent) {
    mainContent.style.setProperty('--app-font-sans', stack);
  }

  return fontOption;
}

function applyElevatedSurfaces(enabled) {
  document.body.classList.toggle('lux-elevated-surfaces', enabled);
  document.querySelectorAll('.card, .btn, .progress').forEach((el) => {
    el.classList.toggle('box_shadow', enabled);
  });
}

export function applyUiSettings(settings) {
  const next = normalizeSettings(settings);

  applyFont(next.font);

  const pageTop = document.getElementById('page_top');
  if (pageTop) {
    pageTop.classList.toggle('sticky-top', next.stickyHeader);
  }

  if (document.body) {
    applyElevatedSurfaces(next.elevatedSurfaces);
  }

  return next;
}

export function updateUiSettings(partial) {
  const next = applyUiSettings({ ...getUiSettings(), ...partial });
  persistUiSettings(next);
  return next;
}

export function initUiSettings() {
  const settings = getUiSettings();
  applyUiSettings(settings);
  return settings;
}

export function getFontIds() {
  return FONT_IDS;
}
