import React, { Component } from "react";
import { connect } from "react-redux";
import { commonUtils, store } from "_helpers";
import dateUtils from "_helpers/date.utils";
import { employeeActions } from "_actions";
import { employeeConstants } from "_constants";
import { dashbaordService } from "_services/dashboard.service";
import { employeeService } from "_services/employee.service";
import EmployeeDashboardTabs from "./components/dashboard/EmployeeDashboardTabs";
import EmployeePersonalDashboard from "./components/dashboard/EmployeePersonalDashboard";
import EmployeeManagerDashboard from "./components/dashboard/EmployeeManagerDashboard";
import {
  buildDashboardAnalytics,
  buildEmployeeSummaryStats,
  getSelectedTeamLabels,
  MANAGER_DEFAULT_FILTER,
  MANAGER_SCOPE,
  resolveDashboardAccess,
} from "./components/dashboard/employeeDashboard.utils";

class EmployeeDashboardPage extends Component {
  constructor(props) {
    super(props);
    const access = resolveDashboardAccess();
    this.state = {
      activeTab: "personal",
      managerScope: MANAGER_SCOPE.TEAMS,
      managerFilterOptions: { ...MANAGER_DEFAULT_FILTER },
      personalUtilization: null,
      personalMonthUtilization: null,
      personalAttendanceItems: [],
      personalHolidays: [],
      personalWeeklyTrend: [],
      personalInsightsLoading: true,
      access,
    };
  }

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    const userTeams = commonUtils.getUserTeams(this.props.userTeamsProp);
    store.dispatch({ type: employeeConstants.INITIALIZE_EMPLOYEE_USER_TEAMS, userTeams });
    this.fetchPersonalInsights();
    if (this.state.access.showManagerTab) {
      this.loadManagerEmployees(userTeams, this.state.managerScope);
    }
  }

  fetchPersonalInsights = () => {
    const employeeId = commonUtils.getCurrentUserId();
    const teamIds = commonUtils.getCurrentUserTeamIds();
    const userTeamIds =
      teamIds && teamIds.length > 0 ? teamIds : [commonUtils.getCurrentUserTeamId()];
    const now = dateUtils.getCurrentTime();
    const weekStart = now.clone().startOf("week").startOf("day").format(dateUtils.SERVER_DATE_FORMAT);
    const weekEnd = now.clone().endOf("week").endOf("day").format(dateUtils.SERVER_DATE_FORMAT);
    const monthRange = dateUtils.getFirstAndLastDayofMonth(now);
    const monthStart = monthRange[0].format(dateUtils.SERVER_DATE_FORMAT);
    const monthEnd = monthRange[1].format(dateUtils.SERVER_DATE_FORMAT);
    const holidayStart = now.clone().startOf("day").format(dateUtils.SERVER_DATE_FORMAT);
    const holidayEnd = now.clone().add(120, "days").endOf("day").format(dateUtils.SERVER_DATE_FORMAT);

    const weeklyRequests = [];
    for (let i = 5; i >= 0; i -= 1) {
      const start = now.clone().subtract(i, "weeks").startOf("week").startOf("day");
      const end = start.clone().endOf("week").endOf("day");
      weeklyRequests.push({
        label: start.format("MMM D"),
        startDate: start.format(dateUtils.SERVER_DATE_FORMAT),
        endDate: end.format(dateUtils.SERVER_DATE_FORMAT),
      });
    }

    this.setState({ personalInsightsLoading: true });

    const utilizationRequest = (startDate, endDate) =>
      dashbaordService
        .employeeWeeklyUtilization({ employeeId, startDate, endDate })
        .then((res) => (res && res.payload) || null)
        .catch(() => null);

    Promise.all([
      utilizationRequest(weekStart, weekEnd),
      utilizationRequest(monthStart, monthEnd),
      employeeService
        .getTeamsAttendance({
          userTeamIds,
          startDate: monthStart,
          endDate: monthEnd,
        })
        .then((res) => (res && res.payload) || [])
        .catch(() => []),
      employeeService
        .getHolidays({ startDate: holidayStart, endDate: holidayEnd })
        .then((res) => (res && res.payload) || [])
        .catch(() => []),
      Promise.all(
        weeklyRequests.map((week) =>
          utilizationRequest(week.startDate, week.endDate).then((utilization) => ({
            label: week.label,
            utilization,
          }))
        )
      ),
    ])
      .then(
        ([
          personalUtilization,
          personalMonthUtilization,
          personalAttendanceItems,
          personalHolidays,
          personalWeeklyTrend,
        ]) => {
          this.setState({
            personalUtilization,
            personalMonthUtilization,
            personalAttendanceItems,
            personalHolidays,
            personalWeeklyTrend,
            personalInsightsLoading: false,
          });
        }
      )
      .catch(() => {
        this.setState({ personalInsightsLoading: false });
      });
  };

  loadManagerEmployees = (userTeams, managerScope) => {
    if (managerScope === MANAGER_SCOPE.ALL) {
      this.props.getAllEmployees();
      return;
    }
    const selectedUserTeamsIds = commonUtils.getSelectedUserTeamIds(userTeams);
    if (selectedUserTeamsIds.length > 0) {
      this.props.getTeamsEmployees(selectedUserTeamsIds, this.state.managerFilterOptions);
    }
  };

  handleTabChange = (activeTab) => {
    this.setState({ activeTab }, () => {
      if (activeTab === "team") {
        const userTeams = commonUtils.getUserTeams(this.props.userTeamsProp);
        this.loadManagerEmployees(userTeams, this.state.managerScope);
      }
    });
  };

  handleManagerScopeChange = (managerScope) => {
    const userTeams = commonUtils.getUserTeams(this.props.userTeamsProp);
    this.setState({ managerScope }, () => {
      this.loadManagerEmployees(userTeams, managerScope);
    });
  };

  handleUserTeamsSelection = (userTeams) => {
    store.dispatch({ type: employeeConstants.INITIALIZE_EMPLOYEE_USER_TEAMS, userTeams });
    if (this.state.managerScope === MANAGER_SCOPE.TEAMS) {
      this.loadManagerEmployees(userTeams, MANAGER_SCOPE.TEAMS);
    }
  };

  handleManagerFilterChange = (showValue) => {
    const managerFilterOptions = {
      ...this.state.managerFilterOptions,
      SHOW: {
        ...this.state.managerFilterOptions.SHOW,
        selected: showValue,
      },
    };
    this.setState({ managerFilterOptions });
  };

  resolveManagerEmployees = () => {
    const { managerScope } = this.state;
    if (managerScope === MANAGER_SCOPE.ALL) {
      return this.props.allEmployees || [];
    }
    return this.props.teamPageEmployees || [];
  };

  render() {
    const { access, activeTab, managerScope, managerFilterOptions, personalInsightsLoading } =
      this.state;
    const userTeams = commonUtils.getUserTeams(this.props.userTeamsProp);
    const teamScopeLabel =
      managerScope === MANAGER_SCOPE.ALL
        ? "All employees"
        : getSelectedTeamLabels(userTeams);

    const managerEmployeesRaw = this.resolveManagerEmployees();
    const managerEmployees = commonUtils.filterEmployees(
      managerEmployeesRaw,
      managerFilterOptions
    );
    const managerActiveEmployees = managerEmployees.filter((employee) => employee.active);
    const showFilter = managerFilterOptions.SHOW.selected;
    const chartEmployees =
      showFilter === "INACTIVE"
        ? managerEmployees
        : managerActiveEmployees.length
          ? managerActiveEmployees
          : managerEmployees;

    const managerLoading =
      managerScope === MANAGER_SCOPE.ALL ? this.props.allEmployeesLoading : this.props.loading;

    const stats = buildEmployeeSummaryStats(managerEmployeesRaw, userTeams);
    const analytics = buildDashboardAnalytics(
      managerEmployeesRaw,
      chartEmployees,
      this.props.allTeams
    );
    const user = commonUtils.getCurrentUser();

    return (
      <div className="lux-hrms-dash">
        <EmployeeDashboardTabs
          activeTab={activeTab}
          onChange={this.handleTabChange}
          showManagerTab={access.showManagerTab}
        />

        {activeTab === "personal" && (
          <EmployeePersonalDashboard
            personalUtilization={this.state.personalUtilization}
            personalMonthUtilization={this.state.personalMonthUtilization}
            personalAttendanceItems={this.state.personalAttendanceItems}
            personalHolidays={this.state.personalHolidays}
            personalWeeklyTrend={this.state.personalWeeklyTrend}
            loading={personalInsightsLoading}
            onRefresh={this.fetchPersonalInsights}
          />
        )}

        {activeTab === "team" && access.showManagerTab && (
          <EmployeeManagerDashboard
            user={user}
            stats={stats}
            loading={managerLoading}
            hasData={chartEmployees.length > 0}
            analytics={analytics}
            userTeams={userTeams}
            teamScopeLabel={teamScopeLabel}
            managerScope={managerScope}
            showFilter={showFilter}
            canViewAllEmployees={access.canViewAllEmployees}
            canSwitchTeams={access.canSwitchTeams}
            onScopeChange={this.handleManagerScopeChange}
            onFilterChange={this.handleManagerFilterChange}
            onUserTeamsSelection={this.handleUserTeamsSelection}
          />
        )}
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  allEmployees: state.employees.allEmployees,
  teamPageEmployees: state.employees.items,
  loading: state.employees.loading,
  allEmployeesLoading: state.employees.allEmployeesLoading,
  userTeamsProp: state.employees.userTeams,
  allTeams: state.appconfig.allTeams,
});

const mapDispatchToProps = {
  getAllEmployees: employeeActions.getAllEmployees,
  getTeamsEmployees: employeeActions.getTeamsEmployeesPage,
};

export default connect(mapStateToProps, mapDispatchToProps)(EmployeeDashboardPage);
