function ReadOnlyField({ label, value, required, hint }) {
  return (
    <div className="lux-hrms-settings__field">
      <label className="lux-hrms-settings__label">
        {label}
        {required && <span className="lux-hrms-settings__required">*</span>}
      </label>
      <input className="lux-hrms-settings__input" type="text" value={value} readOnly disabled />
      {hint && <span className="lux-hrms-settings__field-hint">{hint}</span>}
    </div>
  );
}

function ReadOnlySelect({ label, value, options, hint }) {
  return (
    <div className="lux-hrms-settings__field">
      <label className="lux-hrms-settings__label">{label}</label>
      <select className="lux-hrms-settings__input" value={value} disabled>
        {options.map((opt) => (
          <option key={opt.value} value={opt.value}>
            {opt.label}
          </option>
        ))}
      </select>
      {hint && <span className="lux-hrms-settings__field-hint">{hint}</span>}
    </div>
  );
}

