export function NotificationSettingsSection() {
  const channels = [
    {
      icon: "fe fe-mail",
      label: "Email",
      description: "Digests, mentions, and assignment alerts to your inbox",
      enabled: true,
      disabled: true,
    },
    {
      icon: "fe fe-smartphone",
      label: "Mobile push",
      description: "Real-time alerts on registered devices",
      enabled: false,
      disabled: true,
      comingSoon: true,
    },
    {
      icon: "fe fe-bell",
      label: "In-app",
      description: "Notification center inside the web workspace",
      enabled: true,
      disabled: true,
    },
  ];

  const events = [
    { label: "Direct messages and @mentions", checked: false, group: "Collaboration" },
    { label: "Profile views", checked: true, group: "Collaboration" },
    { label: "Comments on your posts", checked: true, group: "Collaboration" },
    { label: "Deliverable status changes", checked: true, group: "Delivery" },
    { label: "Work item assignments", checked: true, group: "Delivery" },
    { label: "Weekly digest summary", checked: false, group: "Digests" },
  ];

  const groups = [...new Set(events.map((e) => e.group))];

  return (
    <SettingsTabShell
      icon="fe fe-bell"
      eyebrow="Alerts"
      title="Notifications"
      subtitle="Control how and when you are notified about workspace activity."
      stats={[
        { key: "channels", label: "Channels", value: "3", hint: "Email, push, in-app" },
        { key: "active", label: "Enabled events", value: events.filter((e) => e.checked).length, tone: "green" },
        { key: "sync", label: "Sync", value: "Preview", tone: "amber", hint: "Server sync soon" },
      ]}
    >
      <LuxCreateSectionCard
        icon="fe fe-radio"
        title="Delivery channels"
        hint="Where notifications can reach you"
        className="lux-hrms-settings__card"
      >
        <div className="lux-hrms-settings__channels">
          {channels.map((ch) => (
            <ProfileChannelCard key={ch.label} {...ch} />
          ))}
        </div>
      </LuxCreateSectionCard>

      {groups.map((group) => (
        <LuxCreateSectionCard
          key={group}
          icon="fe fe-sliders"
          title={group}
          hint={`${group} notification preferences`}
          className="lux-hrms-settings__card"
        >
          <ul className="lux-hrms-settings__toggles">
            {events
              .filter((e) => e.group === group)
              .map((row) => (
                <li key={row.label} className="lux-hrms-settings__toggle-row">
                  <span className="lux-hrms-settings__toggle-copy">
                    <strong>{row.label}</strong>
                    <em>Preview — toggles will sync when server preferences launch</em>
                  </span>
                  <label className="lux-hrms-settings__switch">
                    <input type="checkbox" defaultChecked={row.checked} disabled />
                    <span className="lux-hrms-settings__switch-track" aria-hidden="true" />
                  </label>
                </li>
              ))}
          </ul>
        </LuxCreateSectionCard>
      ))}
    </SettingsTabShell>
  );
}
