import React, { useCallback, useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import { getEmployeeDailyCapacityMinutes } from "../plannerCapacity.utils";
import { measurePlannerOverlayTop } from "../plannerOverlay.utils";
import { formatPlannerHours, getPlannerRosterEmployees } from "../planner.utils";

export default function PlannerCapacitySettings({
  open,
  onClose,
  employees,
  capacityOverrides,
  onSaveOverride,
}) {
  const roster = useMemo(() => getPlannerRosterEmployees(employees), [employees]);
  const [query, setQuery] = useState("");
  const [panelTop, setPanelTop] = useState(0);

  const syncPanelTop = useCallback(() => {
    setPanelTop(measurePlannerOverlayTop());
  }, []);

  useEffect(() => {
    if (!open) return undefined;
    syncPanelTop();
    window.addEventListener("resize", syncPanelTop);
    window.addEventListener("scroll", syncPanelTop, true);
    return () => {
      window.removeEventListener("resize", syncPanelTop);
      window.removeEventListener("scroll", syncPanelTop, true);
    };
  }, [open, syncPanelTop]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (q.length < 2) return roster;
    return roster.filter((e) => (e.name || "").toLowerCase().includes(q));
  }, [roster, query]);

  if (!open || typeof document === "undefined") return null;

  const panelStyle = {
    top: panelTop,
    height: `calc(100dvh - ${panelTop}px)`,
  };

  return createPortal(
    <div className="lux-planner-capacity-portal" role="presentation">
      <button
        type="button"
        className="lux-planner-capacity-portal__backdrop"
        aria-label="Close capacity settings"
        onClick={onClose}
      />
      <aside
        className={classNames("lux-planner-capacity-panel", { "is-open": open })}
        style={panelStyle}
        role="dialog"
        aria-modal="true"
        aria-label="Per-person capacity"
      >
        <header className="lux-planner-capacity-panel__hero">
          <div className="lux-planner-capacity-panel__hero-bg" aria-hidden />
          <button
            type="button"
            className="lux-planner-capacity-panel__close"
            onClick={onClose}
            aria-label="Close"
          >
            <i className="fe fe-x" />
          </button>
          <span className="lux-planner-capacity-panel__eyebrow">Team capacity</span>
          <h2>Per-person capacity</h2>
          <p>Overrides apply in this browser only. Profile FTE / hours fill in when no override is set.</p>
          <label className="lux-planner-capacity-panel__search">
            <i className="fe fe-search" aria-hidden />
            <input
              type="search"
              placeholder="Search team member…"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
            />
          </label>
        </header>

        <div className="lux-planner-capacity-panel__body">
          <p className="lux-planner-capacity-intro">
            <i className="fe fe-info" aria-hidden />
            Drives utilization on roster and planning views. Does not change payroll settings.
          </p>
          <ul className="lux-planner-capacity-list">
            {filtered.length === 0 ? (
              <li className="lux-planner-capacity-list__empty">No team members match your search.</li>
            ) : (
              filtered.map((emp) => (
                <CapacityRow
                  key={emp.id}
                  employee={emp}
                  capacityOverrides={capacityOverrides}
                  onSaveOverride={onSaveOverride}
                />
              ))
            )}
          </ul>
        </div>
      </aside>
    </div>,
    document.body
  );
}

function CapacityRow({ employee, capacityOverrides, onSaveOverride }) {
  const defaultMins = getEmployeeDailyCapacityMinutes(employee, {});
  const storedOverride =
    capacityOverrides && capacityOverrides[String(employee.id)] != null
      ? capacityOverrides[String(employee.id)]
      : null;
  const [hours, setHours] = useState(
    storedOverride != null ? String(Math.round((storedOverride / 60) * 10) / 10) : ""
  );

  const commit = () => {
    const trimmed = (hours || "").trim();
    if (trimmed === "") {
      onSaveOverride(employee.id, null);
      return;
    }
    const h = Number(trimmed);
    if (!Number.isNaN(h) && h >= 0 && h <= 24) {
      onSaveOverride(employee.id, Math.round(h * 60));
    }
  };

  const hasOverride = storedOverride != null;

  return (
    <li className={classNames("lux-planner-capacity-card", { "has-override": hasOverride })}>
      <div className="lux-planner-capacity-card__person">
        <span className="lux-planner-capacity-card__avatar" aria-hidden>
          {(employee.name || "?").charAt(0).toUpperCase()}
        </span>
        <div>
          <strong>{employee.name}</strong>
          <span>Default {formatPlannerHours(defaultMins)}/day from profile</span>
        </div>
      </div>
      <div className="lux-planner-capacity-card__control">
        <label>
          <span>Hours / day</span>
          <input
            type="number"
            min="0"
            max="24"
            step="0.5"
            placeholder={String(Math.round((defaultMins / 60) * 10) / 10)}
            value={hours}
            onChange={(e) => setHours(e.target.value)}
            onBlur={commit}
            onKeyDown={(e) => e.key === "Enter" && commit()}
          />
        </label>
        {hasOverride && (
          <button
            type="button"
            className="lux-planner-capacity-card__reset"
            onClick={() => {
              setHours("");
              onSaveOverride(employee.id, null);
            }}
          >
            Reset
          </button>
        )}
      </div>
    </li>
  );
}
