import React, { Component } from "react";
import PageInnerHeader from "views/common/PageInnerHeader";
import CreateWorkItemModel from "./components/modal/CreateWorkItemModel";
import LuxWorkItemCreatePanel from "./components/LuxWorkItemCreatePanel";
import { store } from "_helpers";
import { connect } from "react-redux";
import { workItemConstants } from "_constants";
import { commonUtils } from "_helpers";
import { workItemActions } from "_actions";
import { taskActions } from "_actions";
import { accessUtils } from "_helpers";
import WorkItemDeliverableContext from "./components/WorkItemDeliverableContext";
import WorkItemPageSummary from "./components/WorkItemPageSummary";
import WorkItemListTable from "./components/WorkItemListTable";
import LuxWorkItemDateToolbar, { rangeForPreset } from "./components/LuxWorkItemDateToolbar";
import { buildWorkItemActivitySummary } from "./components/workItemActivity.utils";
import dateUtils from "_helpers/date.utils";
import workItemUtils from "_helpers/workitem.utils";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxRegisterFetchError from "views/common/fragments/LuxRegisterFetchError";
import { shouldShowRegisterFetchError } from "_helpers/registerListError.utils";
import {
  paginateRegisterList,
  REGISTER_DEFAULT_PAGE_SIZE,
  shouldResetRegisterPage,
} from "_helpers/registerPagination.utils";

class WorkItemsListPage extends Component {
  constructor() {
    super();
    this.state = {
      dateRange: rangeForPreset("week", null),
      datePreset: "week",
      filterOptions: {
        SHOW: {
          options: [
            { name: "ALL", label: "All" },
            { name: "ONGOING", label: "On Going" },
            { name: "DELETED", label: "Deleted" },
            { name: "COMPLETED", label: "Completed" },
            { name: "MYASSIGNED", label: "My Assigned" },
            { name: "CREATEDBYME", label: "Created By Me" },
          ],
          selected: "ONGOING",
        },
        SORT: {
          options: [
            { name: "ACTUALSTARTDATE", label: "Start Date" },
            { name: "ESTIMATEDENDDATE", label: "Due Date" },
            { name: "CREATEDDATE", label: "Created Date" },
            { name: "A-Z", label: "A-Z" },
          ],
          selected: "A-Z",
          directionUp: true,
        },
        filterText: null,
      },
      permission: accessUtils.getWorkItemAccessControl(),
      taskId: null,
      editMode: false,
      page: 1,
      pageSize: REGISTER_DEFAULT_PAGE_SIZE,
    };
  }

  componentDidUpdate(prevProps) {
    if (shouldResetRegisterPage(prevProps, this.props)) {
      this.setState({ page: 1 });
    }
    if (this.props.taskInfo && !prevProps.taskInfo && this.state.datePreset === "week") {
      this.applyDatePreset("deliverable");
    }
  }

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(
      this.props.routeProp.name + " : " + this.props.match.params.taskId
    );
    const taskId = commonUtils.removeNameIntial(this.props.match.params.taskId);
    if (!this.props.taskInfo || this.props.taskInfo.id !== taskId) {
      store.dispatch(this.props.getTaskInfo(taskId));
    }
    this.setState({ taskId });
    this.reloadWorkItemsListService(taskId, this.state.dateRange);
  }

  reloadWorkItemsListService = (taskId, dateRange) => {
    const id = taskId || this.state.taskId;
    if (!id) return;
    const range = dateRange || this.state.dateRange;
    store.dispatch(this.props.getAllWorkItems({ taskId: id, dateRange: range }, this.state.filterOptions));
  };

  applyDatePreset = (presetKey) => {
    const range = rangeForPreset(presetKey, this.props.taskInfo);
    this.setState(
      { dateRange: range, datePreset: presetKey, page: 1 },
      () => this.reloadWorkItemsListService(this.state.taskId, range)
    );
  };

  handleDateRangeChange = (range, presetKey) => {
    this.setState(
      { dateRange: range, datePreset: presetKey || "custom", page: 1 },
      () => this.reloadWorkItemsListService(this.state.taskId, range)
    );
  };

  handlePageChange = (page) => {
    this.setState({ page });
  };

  handlePageSizeChange = (pageSize) => {
    this.setState({ pageSize, page: 1 });
  };

  onCreateItemClick = () => {
    this.setState({ editMode: false });
    store.dispatch(this.props.initializeCreateWorkItem(commonUtils.getCurrentUserTeamId()));
  };

  onCloseCreateItem = () => {
    store.dispatch({ type: workItemConstants.CLOSE_WORK_ITEM_CREATE_WINDOW });
  };

  handleDeleteWorkItem = (workItemIdTobeDeleted, isDelete) => {
    store.dispatch(this.props.deleteWorkItem(workItemIdTobeDeleted, isDelete));
  };

  handleEditWorkItem = (workItemId) => {
    this.setState({ editMode: true });
    store.dispatch(this.props.getWorkItemInfo(workItemId));
    store.dispatch(this.props.initializeCreateWorkItem(commonUtils.getCurrentUserTeamId()));
  };

  handleRemoveWorkItem = (workItemId) => {
    store.dispatch(this.props.removeWorkItem(workItemId));
  };

  handleSubmit = (workItemRequest, isEdtiMode, isCreateAnotherEnabled, callbackFunction) => {
    if (isEdtiMode) {
      store.dispatch(this.props.updateWorkItem(workItemRequest));
    } else {
      store.dispatch(
        this.props.createWorkItem(workItemRequest, isCreateAnotherEnabled, callbackFunction)
      );
    }
  };

  onFilterTextChange = (value) => {
    this.setState(
      (prevState) => ({
        filterOptions: {
          ...prevState.filterOptions,
          filterText: value,
        },
        page: 1,
      }),
      () => {
        this.handleFilterChange(this.state.filterOptions);
      }
    );
  };

  handleFilterChange = (filterOptions) => {
    this.setState({ filterOptions, page: 1 }, () => {
      store.dispatch({ type: workItemConstants.CHANGE_FILTER_WORK_ITEMS, filterOptions });
    });
  };

  handleSummaryQuickFilter = (showValue) => {
    const base = this.props.filterOptions || this.state.filterOptions;
    const next = {
      ...base,
      SHOW: { ...base.SHOW, selected: showValue },
    };
    this.handleFilterChange(next);
  };

  canCreateWorkItem = () => {
    return (
      this.state.permission.createEnabled &&
      this.props.taskInfo &&
      this.props.taskInfo.status === "INPROGRESS"
    );
  };

  render() {
    const allItems = this.props.items || [];
    const filterOptions = this.props.filterOptions || this.state.filterOptions;
    const summaryStat = buildWorkItemActivitySummary(this.props.itemsRaw || allItems, []);
    const pagination = paginateRegisterList(allItems, this.state.page, this.state.pageSize);
    const pageItems = pagination.items;

    return (
      <div className="workitemslist lux-bid-requests lux-workitem-requests">
        <WorkItemDeliverableContext
          taskInfo={this.props.taskInfo}
          isLoading={this.props.taskInfoLoading}
        />

        {this.props.taskInfo &&
          this.props.showCreateModel &&
          ((this.state.editMode && this.props.selectedWorkItemInfo) || !this.state.editMode) && (
            <LuxWorkItemCreatePanel
              show={this.props.showCreateModel}
              editMode={this.state.editMode}
              onClose={this.onCloseCreateItem}
              taskInfo={this.props.taskInfo}
            >
              <CreateWorkItemModel
                onCloseCreateItem={this.onCloseCreateItem}
                show={this.props.showCreateModel}
                editMode={this.state.editMode}
                selectedWorkItemInfo={this.props.selectedWorkItemInfo}
                handleSubmit={this.handleSubmit}
                taskInfo={this.props.taskInfo}
                permission={this.state.permission}
                minDate={workItemUtils.getWorkItemCreateStartMinDate(
                  dateUtils.convertDateStringToMoment(
                    this.props.taskInfo.estStartTime ||
                      dateUtils.getCurrentTime().clone().subtract(30, "days")
                  ),
                  this.state.permission
                )}
                maxDate={workItemUtils.getWorkItemCreateEndMaxDate(
                  dateUtils.convertDateStringToMoment(
                    this.props.taskInfo.estCompletionTime ||
                      dateUtils.getCurrentTime().clone().add(30, "days")
                  ),
                  this.state.permission
                )}
              />
            </LuxWorkItemCreatePanel>
          )}

        <PageInnerHeader
          showFilter
          stickytop={false}
          isLoading={this.props.loading}
          showUserTeamMenu={false}
          filterOptions={filterOptions}
          handleFilterChange={this.handleFilterChange}
          onFilterTextChange={this.onFilterTextChange}
          showCreateMenu={this.canCreateWorkItem()}
          showCreateMenuText="Create work item"
          createItemHandler={this.onCreateItemClick}
        />

        <LuxWorkItemDateToolbar
          taskInfo={this.props.taskInfo}
          dateRange={this.state.dateRange}
          activePreset={this.state.datePreset}
          onRangeChange={this.handleDateRangeChange}
        />

        <WorkItemPageSummary
          stat={summaryStat}
          visibleCount={allItems.length}
          filterOptions={filterOptions}
          isLoading={this.props.isLoading}
          onQuickFilter={this.handleSummaryQuickFilter}
        />

        {(allItems.length > 0 || this.props.isLoading) && (
          <div className="lux-register-list-section">
            <WorkItemListTable
              items={pageItems}
              totalCount={pagination.total}
              isLoading={this.props.isLoading}
              permission={this.state.permission}
              handleEditWorkItem={this.handleEditWorkItem}
              handleDeleteWorkItem={this.handleDeleteWorkItem}
              handleRemoveWorkItem={this.handleRemoveWorkItem}
              onRefresh={() =>
                this.reloadWorkItemsListService(this.state.taskId, this.state.dateRange)
              }
              pagination={pagination}
              onPageChange={this.handlePageChange}
              onPageSizeChange={this.handlePageSizeChange}
            />
          </div>
        )}

        {shouldShowRegisterFetchError({
          error: this.props.error,
          isLoading: this.props.isLoading,
          items: allItems,
        }) && (
          <LuxRegisterFetchError
            error={this.props.error}
            onRetry={() =>
              this.reloadWorkItemsListService(this.state.taskId, this.state.dateRange)
            }
          />
        )}

        {allItems.length === 0 && !this.props.isLoading && !this.props.error && (
          <LuxRegisterEmptyState
            variant="task-activities"
            eyebrow="Deliverable work"
            title="No work items found"
            description="No work items match the current filters or date range. Try a wider range, adjust filters, or create a work item to log effort on this deliverable."
            hints={[
              "Use Deliverable range to see the full delivery window",
              "Click a row or use the menu to view rich activity details",
              "Summary insights above reflect the current filter",
            ]}
            createLabel="Create work item"
            onCreate={this.onCreateItemClick}
            showCreate={this.canCreateWorkItem()}
          />
        )}
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  items:
    state.workItem.items &&
    commonUtils.filterWorkItems(state.workItem.items, state.workItem.filterOptionsWI),
  itemsRaw: state.workItem.items,
  taskInfo: state.tasks.selectedTaskInfo,
  taskInfoLoading: !state.tasks.selectedTaskInfo,
  isLoading: state.workItem.workItemLoading,
  loading: state.workItem.workItemLoading,
  error: state.workItem.error,
  filterOptions: state.workItem.filterOptionsWI,
  selectedWorkItemInfo: state.workItem.selectedWorkItemInfo,
  showCreateModel: state.workItem.showCreateModel,
});

const mapDispatchToProps = () => ({
  getTaskInfo: taskActions.getTaskInfo,
  getAllWorkItems: workItemActions.getAllWorkItems,
  getWorkItemInfo: workItemActions.getWorkItemInfo,
  createWorkItem: workItemActions.createWorkItem,
  updateWorkItem: workItemActions.updateWorkItem,
  deleteWorkItem: workItemActions.deleteWorkItem,
  removeWorkItem: workItemActions.removeWorkItem,
  initializeCreateWorkItem: workItemActions.initializeCreateWorkItem,
});

export default connect(mapStateToProps, mapDispatchToProps)(WorkItemsListPage);
