import { userUtils } from "_helpers";
import { accessUtils } from "_helpers";
import React, { Component } from "react";
import DeviceRegistrationSection from "./components/fragments/DeviceRegistrationSection";
import ScheduleListSection from "./components/fragments/ScheduleListSection";
import ServiceHealthSection from "./components/fragments/ServiceHealthSection";
import SettingsPageNav from "./components/settings/SettingsPageNav";
import {
  CompanySettingsSection,
  LocalizationSettingsSection,
  NotificationSettingsSection,
} from "./components/settings/SettingsLuxSections";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";

const TAB_META = {
  mobile: { label: "Mobile app", desc: "Pair devices for secure mobile access" },
  schedulers: { label: "Schedulers", desc: "Manage background cron jobs" },
  health: { label: "Service health", desc: "Monitor platform and integrations" },
  company: { label: "Company", desc: "Organization profile and contacts" },
  localization: { label: "Localization", desc: "Regional formats and currency" },
  notifications: { label: "Notifications", desc: "Alert channels and event preferences" },
};

class ProfileSettingsPage extends Component {
  constructor() {
    super();
    this.state = {
      permission: accessUtils.getProfileSettingsControl(),
      activeTab: null,
    };
  }

  isDeviceRegistrationEnabled = () => {
    const user = userUtils.getCurrentUser();
    return user && user.deviceAppEnabled === true;
  };

  getAvailableTabs = () => {
    const { permission } = this.state;
    const tabs = [];

    if (permission.deviceRegistrationEnabled === true && this.isDeviceRegistrationEnabled()) {
      tabs.push({ id: "mobile", label: "Mobile app", icon: "fe fe-smartphone" });
    }
    if (permission.schedulerViewEnabled === true) {
      tabs.push({ id: "schedulers", label: "Schedulers", icon: "fe fe-clock" });
    }
    if (permission.serviceHealthEnabled === true) {
      tabs.push({ id: "health", label: "Service health", icon: "fe fe-activity" });
    }
    if (permission.companySettingsEnabled === true) {
      tabs.push({ id: "company", label: "Company", icon: "fe fe-briefcase" });
    }
    if (permission.localizationSettingsEnabled === true) {
      tabs.push({ id: "localization", label: "Localization", icon: "fe fe-globe" });
    }
    if (permission.notificationSettingsEnabled === true) {
      tabs.push({ id: "notifications", label: "Notifications", icon: "fe fe-bell" });
    }

    return tabs;
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    const tabs = this.getAvailableTabs();
    if (tabs.length > 0) {
      this.setState({ activeTab: tabs[0].id });
    }
  }

  handleTabChange = (tabId) => {
    this.setState({ activeTab: tabId });
  };

  renderActiveSection = () => {
    const { activeTab, permission } = this.state;

    if (activeTab === "mobile" && permission.deviceRegistrationEnabled) {
      return <DeviceRegistrationSection />;
    }
    if (activeTab === "schedulers" && permission.schedulerViewEnabled) {
      return <ScheduleListSection />;
    }
    if (activeTab === "health" && permission.serviceHealthEnabled) {
      return <ServiceHealthSection />;
    }
    if (activeTab === "company" && permission.companySettingsEnabled) {
      return <CompanySettingsSection />;
    }
    if (activeTab === "localization" && permission.localizationSettingsEnabled) {
      return <LocalizationSettingsSection />;
    }
    if (activeTab === "notifications" && permission.notificationSettingsEnabled) {
      return <NotificationSettingsSection />;
    }
    return null;
  };

  render() {
    const tabs = this.getAvailableTabs();
    const activeMeta = TAB_META[this.state.activeTab];

    return (
      <div className="lux-hrms-settings lux-bid-requests">
        <section className="lux-hrms-settings__hero" aria-label="Settings overview">
          <LuxSummaryEyebrow variant="settings" className="lux-hrms-settings__eyebrow">
            Administration
          </LuxSummaryEyebrow>
          <h2 className="lux-hrms-settings__title">Workspace settings</h2>
          <p className="lux-hrms-settings__subtitle">
            Manage mobile registration, schedulers, service health, and organization preferences.
          </p>
          <div className="lux-hrms-settings__stats">
            <span>
              <strong>{tabs.length}</strong> sections available
            </span>
            {activeMeta && (
              <>
                <span className="lux-hrms-settings__dot">·</span>
                <span>
                  Viewing <strong>{activeMeta.label}</strong> — {activeMeta.desc}
                </span>
              </>
            )}
          </div>
        </section>

        <SettingsPageNav tabs={tabs} activeTab={this.state.activeTab} onChange={this.handleTabChange} />

        <div className="lux-hrms-settings__content">{this.renderActiveSection()}</div>
      </div>
    );
  }
}

export default ProfileSettingsPage;
