import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import { getDayMeta } from "./attendance.utils";

class AttendanceDayCell extends PureComponent {
  handleClick = (event) => {
    event.preventDefault();
    event.stopPropagation();

    const { item, employeeId, employeeName, dayMonth, isLoading, onRequestMark, onRequestViewDetails } =
      this.props;
    const meta = getDayMeta(dayMonth);

    if (isLoading || meta.isFuture) return;

    if (item && item.id != null) {
      onRequestViewDetails(employeeId, employeeName, dayMonth, item);
    } else {
      onRequestMark(employeeId, employeeName, dayMonth);
    }
  };

  render() {
    const { item, dayMonth, isLoading } = this.props;
    const meta = getDayMeta(dayMonth);
    const isPresent = !!item;
    const canToggle = !meta.isFuture && !isLoading;

    return (
      <td
        className={classNames("lux-att-day", {
          "is-weekend-sat": meta.isSaturday,
          "is-weekend-sun": meta.isSunday,
          "is-today": meta.isToday,
          "is-future": meta.isFuture,
          "is-present": isPresent,
          "is-absent": !isPresent && !meta.isFuture,
          "is-clickable": canToggle,
        })}
      >
        {meta.isFuture ? (
          <span className="lux-att-day__future" aria-hidden="true" />
        ) : (
          <button
            type="button"
            className={classNames("lux-att-day__btn", {
              "is-present": isPresent,
              "is-absent": !isPresent,
            })}
            onClick={this.handleClick}
            disabled={!canToggle}
            title={
              meta.isWeekend
                ? isPresent
                  ? "Present (optional day) — click to view details"
                  : "Not marked (optional day) — click to mark present"
                : isPresent
                ? "Present — click to view details"
                : "Absent — click to mark with time details"
            }
            aria-label={
              isPresent
                ? `Present on ${dayMonth.format("MMM D")}`
                : `Absent on ${dayMonth.format("MMM D")}`
            }
          >
            {isPresent ? (
              <i className="fe fe-check" aria-hidden="true" />
            ) : (
              <i className="fe fe-minus" aria-hidden="true" />
            )}
          </button>
        )}
      </td>
    );
  }
}

export default AttendanceDayCell;
