import classNames from "classnames/bind";
import React, { Component } from "react";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import { LUX_SKELETON_THEME } from "views/common/fragments/luxSkeleton.constants";
import { getRegisterSkeletonRowKeys } from "views/common/fragments/luxRegisterListSkeleton.utils";
import { connect } from "react-redux";
import { workItemActions } from "_actions";
import { store } from "_helpers";
import dateUtils from "_helpers/date.utils";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import workItemUtils from "_helpers/workitem.utils";
import WorkItemActivityDetailPopover from "./WorkItemActivityDetailPopover";
import {
  getWorkItemPriorityMeta,
  getWorkItemStatusMeta,
  groupWorkItemsDurationMins,
} from "./workItemActivity.utils";

class WorkItemActiveItems extends Component {
  constructor(props) {
    super(props);
    this.state = {
      detailOpen: false,
      detailItem: null,
    };
  }

  handleDeleteWorkItem = (workItemIdTobeDeleted, isDelete) => {
    store.dispatch(this.props.deleteWorkItem(workItemIdTobeDeleted, isDelete));
  };

  handleRemoveWorkItem = (workItemId) => {
    store.dispatch(this.props.removeWorkItem(workItemId));
  };

  handleEditWorkItem = (workItemId) => {
    this.props.handleEditWorkItem(workItemId);
  };

  handleUpdateWorkItem = (workItemRequest) => {
    store.dispatch(this.props.updateWorkItem(workItemRequest));
  };

  handleOpenDetail = (item) => {
    this.setState({ detailOpen: true, detailItem: item });
  };

  handleCloseDetail = () => {
    this.setState({ detailOpen: false, detailItem: null });
  };

  render() {
    const listByTasks =
      this.props.items &&
      this.props.items.reduce(function (r, a) {
        const taskId = a.taskId || a.taskActCategory;
        r[taskId] = r[taskId] || [];
        r[taskId].push(a);
        return r;
      }, Object.create(null));

    const listByProjects =
      this.props.items &&
      this.props.items.reduce(function (r, a) {
        const taskId = a.projectId || "nonProject";
        r[taskId] = r[taskId] || [];
        r[taskId].push(a);
        return r;
      }, Object.create(null));

    const itemProps = {
      permission: this.props.permission,
      view: this.props.view,
      handleDeleteWorkItem: this.handleDeleteWorkItem,
      handleRemoveWorkItem: this.handleRemoveWorkItem,
      handleEditWorkItem: this.handleEditWorkItem,
      onCheklistItemClick: this.props.onCheklistItemClick,
      onOpenDetail: this.handleOpenDetail,
    };

    return (
      <div className="lux-activity-list">
        {this.props.isLoading && (
          <div className="lux-activity-list__skeleton is-loading" aria-busy="true">
            <SkeletonTheme
              baseColor={LUX_SKELETON_THEME.baseColor}
              highlightColor={LUX_SKELETON_THEME.highlightColor}
            >
              {getRegisterSkeletonRowKeys(10).map((key) => (
                <Skeleton
                  key={key}
                  height={52}
                  borderRadius={14}
                  containerClassName="lux-activity-list__skeleton-line"
                />
              ))}
            </SkeletonTheme>
          </div>
        )}
        {!this.props.isLoading && (
          <>
            {this.props.sortBy === "DELIVERABLE" ? (
              <>
                {listByTasks &&
                  Object.keys(listByTasks).map((key) => (
                    <WorkItemActiveItemByItem
                      key={key}
                      items={listByTasks[key]}
                      name={this.props.items[0].taskName}
                      id={listByTasks[key][0].taskId}
                      estStartTime={listByTasks[key][0].taskEstStartTime}
                      estCompletionTime={listByTasks[key][0].taskEstCompletionTime}
                      type={listByTasks[key][0].taskType}
                      category={listByTasks[key][0].taskActCategory}
                      {...itemProps}
                    />
                  ))}
              </>
            ) : this.props.sortBy === "PROJECT" ? (
              <>
                {listByProjects &&
                  Object.keys(listByProjects).map((key) => (
                    <WorkItemActiveItemByItem
                      key={key}
                      items={listByProjects[key]}
                      name={listByProjects[key][0].projectName}
                      id={listByProjects[key][0].projectId}
                      estStartTime={listByProjects[key][0].projectEstStartTime}
                      estCompletionTime={listByProjects[key][0].projectEstCompletionTime}
                      code={listByProjects[key][0].projectcode}
                      type={listByProjects[key][0].taskType}
                      projectCategory={listByProjects[key][0].projectCategory}
                      {...itemProps}
                    />
                  ))}
              </>
            ) : (
              <>
                {this.props.items &&
                  this.props.items.length > 0 &&
                  this.props.items.map((activityItem) => (
                    <WorkItemActiveItem key={activityItem.id} item={activityItem} {...itemProps} />
                  ))}
              </>
            )}
          </>
        )}

        {(!this.props.items || this.props.items.length === 0) && !this.props.isLoading && (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-activity-register__empty"
            variant="task-activities"
            eyebrow="Activity register"
            title="No work items in this view"
            description="Adjust filters, pick another date on the calendar, or create a new activity to get started."
            hints={[
              "Use the date range and status filters above",
              "Select days on the calendar sidebar",
              "Open checklists from the row actions",
            ]}
          />
        )}

        <WorkItemActivityDetailPopover
          show={this.state.detailOpen}
          item={this.state.detailItem}
          permission={this.props.permission}
          onClose={this.handleCloseDetail}
          onCheklistItemClick={this.props.onCheklistItemClick}
          handleUpdateWorkItem={this.handleUpdateWorkItem}
        />
      </div>
    );
  }
}

class WorkItemActiveItemByItem extends Component {
  constructor() {
    super();
    this.state = {
      showChilds: true,
    };
  }

  toggleChildItems = (show) => {
    this.setState({ showChilds: show });
  };

  render() {
    const estStartTime = (this.props.estStartTime && dateUtils.convertDateFormat(this.props.estStartTime)) || "";
    const estCompletionTime =
      (this.props.estCompletionTime && dateUtils.convertDateFormat(this.props.estCompletionTime)) || "";
    const totalDuration = groupWorkItemsDurationMins(this.props.items);
    const codeLabel = this.props.type === "NON_PROJECT" ? "NON BILLABLE" : this.props.id;

    return (
      <section className="lux-activity-group">
        <header className="lux-activity-group__head">
          <div className="lux-activity-group__main">
            <button
              type="button"
              className="lux-activity-group__toggle"
              onClick={() => this.toggleChildItems(!this.state.showChilds)}
              aria-expanded={this.state.showChilds}
            >
              <i className={`fe ${this.state.showChilds ? "fe-chevron-down" : "fe-chevron-right"}`} aria-hidden="true" />
            </button>
            <span className="lux-activity-group__code">[{codeLabel}]</span>
            <span className="lux-activity-group__name" title={this.props.name || this.props.category}>
              {this.props.name || this.props.category}
            </span>
            {this.props.projectCategory && (
              <span className="lux-activity-item__category">{this.props.projectCategory}</span>
            )}
          </div>
          <div className="lux-activity-group__meta">
            <span>
              {estStartTime} – {estCompletionTime}
            </span>
            <span className="lux-activity-group__duration">{dateUtils.minuteToHourString(totalDuration)}</span>
          </div>
        </header>
        {this.state.showChilds && (
          <div className="lux-activity-group__body">
            {this.props.items &&
              this.props.items.length > 0 &&
              this.props.items.map((activityItem) => (
                <WorkItemActiveItem key={activityItem.id} item={activityItem} {...this.props} />
              ))}
          </div>
        )}
      </section>
    );
  }
}

class WorkItemActiveItem extends Component {
  constructor() {
    super();
    this.state = {
      confrimDelete: false,
    };
  }

  handleRemoveWorkItem = (isConfrimDelete) => {
    if (isConfrimDelete) {
      this.props.handleRemoveWorkItem(this.props.item.id, isConfrimDelete);
    } else {
      this.setState({ confrimDelete: true });
    }
  };

  handleOpenDetail = () => {
    if (this.props.onOpenDetail) {
      this.props.onOpenDetail(this.props.item);
    }
  };

  handleRowKeyDown = (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      this.handleOpenDetail();
    }
  };

  render() {
    const item = this.props.item;
    const statusMeta = getWorkItemStatusMeta(item.status);
    const priorityMeta = getWorkItemPriorityMeta(item.taskPriority);
    const durationTone =
      item.status === "COMPLETED" || item.status === "CLOSED" ? "green" : item.status === "INPROGRESS" ? "amber" : "indigo";
    const durationValue =
      dateUtils.minuteToHourString(
        item.status === "COMPLETED" || item.status === "CLOSED" ? item.durationInMins : item.estDurationInMins
      ) || "0h 0m";
    const ownerInitial = item.ownerDetails && item.ownerDetails.name ? item.ownerDetails.name.substring(0, 1) : "U";
    const checklistClass =
      item.checklistStatus === "COMPLETED" ? "is-done" : item.checklistStatus === "INPROGRESS" ? "is-progress" : "";

    return (
      <article className="lux-activity-item">
        <div
          className="lux-activity-item__row is-clickable"
          role="button"
          tabIndex={0}
          aria-label={`View details for ${item.name}`}
          onClick={this.handleOpenDetail}
          onKeyDown={this.handleRowKeyDown}
        >
          <div className="lux-activity-item__main">
            <span className="lux-activity-item__lead">
              <span className={classNames("lux-activity-item__status", `is-${statusMeta.tone}`)}>
                <i className={classNames(statusMeta.icon, { spin: statusMeta.spin })} aria-hidden="true" />
              </span>
              <span className={classNames("lux-activity-item__prio", `is-${priorityMeta.tone}`)}>{priorityMeta.level}</span>
            </span>
            <span className="lux-activity-item__ref">{item.itemIdUserTeamPrefix}</span>
            <span className="lux-activity-item__name" title={item.name}>
              {item.name}
            </span>
          </div>
          <div className="lux-activity-item__aside">
            <span className="lux-activity-item__datetime">
              {dateUtils.convertDateTimeFormat(item.actualStartTime || item.estStartTime)}
            </span>
            <span className="lux-activity-item__category" title={item.taskActCategory || "Other"}>
              {item.taskActCategory || "Other"}
            </span>
            <span
              className="lux-activity-item__avatar"
              title={item.ownerDetails && item.ownerDetails.name ? item.ownerDetails.name : "Unknown"}
            >
              {ownerInitial}
            </span>
            <span className={classNames("lux-activity-item__duration", `is-${durationTone}`)}>{durationValue}</span>
            <div className="lux-project-row__actions">
              {this.props.permission.checklistEnabled === true &&
                this.props.view !== "PAGE" &&
                (item.taskType === "PROJECT" || item.taskType === "NON_PROJECT") && (
                  <button
                    type="button"
                    className={classNames("lux-project-row__action is-checklist", checklistClass)}
                    title="Checklist"
                    aria-label="Open checklist"
                    onClick={(e) => {
                      e.stopPropagation();
                      this.props.onCheklistItemClick(item);
                    }}
                  >
                    <i className="fa fa-wpforms" aria-hidden="true" />
                  </button>
                )}
              {this.props.permission.editEnabled === true && this.props.view === "PAGE" && (
                <button
                  type="button"
                  className="lux-project-row__action"
                  title="Edit"
                  aria-label="Edit work item"
                  onClick={(e) => {
                    e.stopPropagation();
                    this.props.handleEditWorkItem(item.id);
                  }}
                >
                  <i className="fe fe-edit-2" aria-hidden="true" />
                </button>
              )}
              {(this.props.permission.deleteEnabled === true || this.isWorkItemDeleteByHoursEnabled()) && (
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    this.props.handleDeleteWorkItem(item.id, !item.deleted);
                  }}
                  className="lux-project-row__action is-danger"
                  title={item.deleted ? "Undo Delete" : "Delete"}
                  aria-label={item.deleted ? "Undo delete" : "Delete work item"}
                  data-type="confirm"
                >
                  {item.deleted ? (
                    <i className="fe fe-rotate-ccw blink_text" aria-hidden="true" />
                  ) : (
                    <i className="fe fe-trash-2" aria-hidden="true" />
                  )}
                </button>
              )}
              {this.props.permission.removeEnabled === true && (
                <button
                  type="button"
                  className="lux-project-row__action is-danger"
                  title="Remove"
                  aria-label={this.state.confrimDelete ? "Confirm remove" : "Remove work item"}
                  onClick={(e) => {
                    e.stopPropagation();
                    this.handleRemoveWorkItem(this.state.confrimDelete);
                  }}
                >
                  {this.state.confrimDelete === true ? (
                    <i className="fe fe-check blink_text" aria-hidden="true" />
                  ) : (
                    <i className="fe fe-x" aria-hidden="true" />
                  )}
                </button>
              )}
            </div>
          </div>
        </div>
      </article>
    );
  }

  isWorkItemDeleteByHoursEnabled = () => {
    if (this.props.item) {
      const hoursToBeAdded = parseInt(this.props.permission.enableWorkItemDeleteTillNextDayXHour || 0, 10);
      return workItemUtils.isWorkItemEditActive(this.props.item.actualStartTime, hoursToBeAdded);
    }
    return false;
  };
}

const mapStateToProps = () => ({});

const mapDispatchToProps = (dispatch) => ({
  removeWorkItem: workItemActions.removeWorkItem,
  deleteWorkItem: workItemActions.deleteWorkItem,
  updateWorkItem: workItemActions.updateWorkItem,
});

export default connect(mapStateToProps, mapDispatchToProps)(WorkItemActiveItems);
