import React, { Component } from "react";
import ItemCommentsSection from "./fragments/ItemCommentsSection";
import { COLLAB_VIEWS } from "./fragments/itemComments.utils";
import ProjectDetailsTabShell from "./ProjectDetailsTabShell";

class ProjectDetailsActivity extends Component {
  render() {
    const { projectInfo, readOnly, isLoading } = this.props;
    if (!projectInfo) return null;

    return (
      <ProjectDetailsTabShell
        icon="fe fe-activity"
        eyebrow="Collaboration"
        title="Activity & history"
        subtitle="Comments, team updates, and audit events for this project — loaded from your workspace API."
        stats={[
          { key: "record", label: "Record", value: projectInfo.itemIdUserTeamPrefix || "—", hint: "Project ref" },
          { key: "status", label: "Status", value: projectInfo.status || "—", hint: "Current stage" },
        ]}
      >
        <div className={isLoading ? "lux-pd-tab__panel is-loading" : "lux-pd-tab__panel"}>
          <ItemCommentsSection
            itemId={projectInfo.id}
            subType="PROJECT"
            isReadOnly={readOnly}
            initialView={COLLAB_VIEWS.ACTIVITY}
          />
        </div>
      </ProjectDetailsTabShell>
    );
  }
}

export default ProjectDetailsActivity;
