import React, { Component } from "react";
import { createPortal } from "react-dom";
import { connect } from "react-redux";
import classNames from "classnames/bind";
import LuxCreatePanelShell from "views/common/create/LuxCreatePanelShell";
import { validationUtils } from "_helpers";
import LuxFeedbackTemplateQuestions from "../LuxFeedbackTemplateQuestions";
import LuxFeedbackTemplateEditorHero from "../LuxFeedbackTemplateEditorHero";
import LuxFeedbackTemplateDetailsSection from "../LuxFeedbackTemplateDetailsSection";
import { normalizeFeedbackTemplateForEditor } from "../feedbackTemplateQuestions.utils";
import { store } from "_helpers";
import { feedbackTemplateConstants } from "_constants";
import { commonUtils } from "_helpers";
import { feedbackTemplateActions } from "_actions";
import { accessUtils } from "_helpers";
import { appConfigActions } from "_actions";

class ConfigureFeedbackTemplateSidebar extends Component {
  constructor() {
    super();
    this.state = {
      formErrors: {},
      hasFormError: false,
      permission: accessUtils.getFeedbackTemplateAccessControl(),
    };
  }

  onCloseItemClick = () => {
    store.dispatch({
      type: feedbackTemplateConstants.CLOSE_FEEDBACK_TEMPLATE_CONFIGURE_WINDOW,
    });
  };

  onFormError = (fieldName, hasError) => {
    this.setState((prevState) => ({
      formErrors: {
        ...prevState.formErrors,
        [fieldName]: hasError,
      },
    }));
  };

  onResetFormError = () => {
    this.setState({ hasFormError: false });
  };

  handleSubmit = (feedbackTemplateRequest, submitCallBackFunction) => {
    let isValidForm = validationUtils.isValidRequest(
      this.props.fieldConfig,
      feedbackTemplateRequest,
      this.state.formErrors
    );
    isValidForm =
      feedbackTemplateRequest.questionDataList !== undefined &&
      feedbackTemplateRequest.questionDataList.length > 0;
    if (isValidForm === true) {
      feedbackTemplateRequest.questionDataList.forEach((question) => {
        if (question.question === "") {
          isValidForm = false;
        }
      });
    }
    if (isValidForm) {
      if (!feedbackTemplateRequest.id) {
        store.dispatch(
          this.props.createFeedbackTemplate(feedbackTemplateRequest, submitCallBackFunction)
        );
      } else {
        store.dispatch(
          this.props.updateFeedbackTemplate(feedbackTemplateRequest, submitCallBackFunction)
        );
      }
    } else {
      this.setState({ hasFormError: true });
    }
  };

  handleRemoveFeedbackTemplate = (feedbackTemplateId) => {
    store.dispatch(this.props.removeFeedbackTemplate(feedbackTemplateId));
  };

  render() {
    const panel = (
      <LuxCreatePanelShell
        show={this.props.show === true}
        onClose={this.onCloseItemClick}
        panelId="configfeedbackTemplatesidebar"
        className="lux-create-panel--feedback-template config_feedbackTemplate_right_sidebar"
        kicker="Feedback workspace"
        title="Configure feedback templates"
        subtitle="Design reusable question sets for campaigns — map types, teams, and preview before sending."
      >
        {this.props.show === true && (
          <div className="lux-feedback-template-panel__body">
            <ConfigureFeedbackTemplateSidebarSection
              permission={this.state.permission}
              fieldConfig={this.props.fieldConfig}
              onFormError={this.onFormError}
              onResetFormError={this.onResetFormError}
              hasFormError={this.state.hasFormError}
              getAllFeedbackTemplates={this.props.getAllFeedbackTemplates}
              handleRemoveFeedbackTemplate={this.handleRemoveFeedbackTemplate}
              feedbackTemplateDataList={this.props.feedbackTemplateDataList}
              type={this.props.type}
              submitFeedbackTemplate={this.handleSubmit}
              allUserTeams={this.props.allUserTeams}
              typeOptions={this.props.typeOptions}
              feedbackTypeOptions={this.props.feedbackTypeOptions}
              feedbackSubTypeOptions={this.props.feedbackSubTypeOptions}
            />
          </div>
        )}
      </LuxCreatePanelShell>
    );

    if (typeof document !== "undefined") {
      return createPortal(panel, document.body);
    }
    return panel;
  }
}

class ConfigureFeedbackTemplateSidebarSection extends Component {
  constructor(props) {
    super(props);
    this.state = {
      feedbackTemplateRequest: {},
      questionConfigureMode: true,
      editMode: true,
      filterText: "",
    };
  }

  componentDidMount() {
    store.dispatch(this.props.getAllFeedbackTemplates({ itemType: this.props.type }));
    store.dispatch(appConfigActions.getAllTeams(false));
    this.resetToNewTemplate();
  }

  resetToNewTemplate = () => {
    this.setState({
      feedbackTemplateRequest: {
        userTeamId: commonUtils.getCurrentUserTeamId(),
        type: this.props.type,
        questionDataList: [],
      },
      editMode: true,
      questionConfigureMode: true,
    });
  };

  onNewTemplate = () => {
    this.props.onResetFormError();
    this.resetToNewTemplate();
  };

  addNewQuesiton = () => {
    const questionDataList = [...(this.state.feedbackTemplateRequest.questionDataList || [])];
    questionDataList.push({
      index: questionDataList.length,
      id: Date.now(),
      question: "",
      type: "boolean",
      mandatory: false,
    });
    this.setState({
      feedbackTemplateRequest: {
        ...this.state.feedbackTemplateRequest,
        questionDataList,
      },
    });
  };

  onFormError = (fieldName, hasError) => {
    this.props.onFormError(fieldName, hasError);
  };

  onResetFormError = () => {
    this.props.onResetFormError();
  };

  onChange = (fieldName, value) => {
    this.onResetFormError();
    this.setState({
      feedbackTemplateRequest: {
        ...this.state.feedbackTemplateRequest,
        [fieldName]: value,
      },
    });
  };

  togglequestionConfigureMode = (questionConfigureMode) => {
    this.setState({ questionConfigureMode });
  };

  onRestFeedbackTemplate = () => {
    this.props.onResetFormError();
    this.resetToNewTemplate();
  };

  submitCallBackFunction = () => {
    this.resetToNewTemplate();
  };

  onSaveFeedbackTemplate = () => {
    this.props.submitFeedbackTemplate(
      this.state.feedbackTemplateRequest,
      this.submitCallBackFunction
    );
  };

  applyTemplateToEditor = (feedbackTemplateData, { editMode, questionConfigureMode }) => {
    this.props.onResetFormError();
    this.setState({
      feedbackTemplateRequest: normalizeFeedbackTemplateForEditor(feedbackTemplateData),
      editMode,
      questionConfigureMode,
    });
  };

  onEditFeedbackTemplate = (feedbackTemplateData) => {
    this.applyTemplateToEditor(feedbackTemplateData, {
      editMode: true,
      questionConfigureMode: true,
    });
  };

  onDuplicateFeedbackTemplate = (feedbackTemplateData) => {
    const { id, ...feedbackTemplateDataCopy } = feedbackTemplateData;
    this.applyTemplateToEditor(feedbackTemplateDataCopy, {
      editMode: true,
      questionConfigureMode: true,
    });
  };

  onSelectFeedbackTemplate = (feedbackTemplateData) => {
    this.applyTemplateToEditor(feedbackTemplateData, {
      editMode: false,
      questionConfigureMode: false,
    });
  };

  onFilterTextChange = (filterText) => {
    this.setState({ filterText });
  };

  getFeedbackTypeOptions = () => {
    if (this.props.type && this.props.feedbackTypeOptions) {
      return this.props.feedbackTypeOptions.filter((type) => type.value === this.props.type);
    }
    return this.props.feedbackTypeOptions;
  };

  getFilteredTemplates = () => {
    const list = this.props.feedbackTemplateDataList || [];
    const sorted = commonUtils.sortArrayOfObjects([...list], true);
    const q = (this.state.filterText || "").trim();
    if (!q) return sorted;
    return sorted.filter(
      (item) => item && commonUtils.stringContainsString(item.name, q)
    );
  };

  getQuestionCount = () => {
    const list = this.state.feedbackTemplateRequest.questionDataList;
    return list && list.length ? list.length : 0;
  };

  canSave = () => {
    const { permission } = this.props;
    const req = this.state.feedbackTemplateRequest;
    if (!this.state.editMode) return false;
    if (!req.id) return permission.createEnabled;
    return permission.editEnabled;
  };

  render() {
    const filtered = this.getFilteredTemplates();
    const totalTemplates = (this.props.feedbackTemplateDataList || []).length;
    const questionCount = this.getQuestionCount();
    const req = this.state.feedbackTemplateRequest;

    return (
      <div className="lux-feedback-template-editor">
        <div className="lux-feedback-template-editor__layout">
          <aside className="lux-feedback-template-editor__list-pane">
            <div className="lux-feedback-template-editor__list-head">
              <div className="lux-feedback-template-editor__list-title-row">
                <span className="lux-feedback-template-editor__list-label">
                  <i className="fe fe-layers" aria-hidden="true" />
                  Templates
                </span>
                <span className="lux-feedback-template-editor__count">{totalTemplates}</span>
              </div>
              <div className="lux-feedback-template-editor__filter">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  placeholder="Search templates…"
                  value={this.state.filterText}
                  onChange={(e) => this.onFilterTextChange(e.target.value)}
                  aria-label="Filter templates"
                />
              </div>
              <button
                type="button"
                className="lux-feedback-template-editor__new"
                onClick={this.onNewTemplate}
              >
                <i className="fe fe-plus" aria-hidden="true" />
                New template
              </button>
            </div>
            <div className="lux-feedback-template-editor__list-body">
              {filtered.length > 0 ? (
                <ul className="lux-feedback-template-editor__list" role="list">
                  {filtered.map(
                    (feedbackTemplateData) =>
                      feedbackTemplateData && (
                        <FeedbackTemplateItem
                          key={feedbackTemplateData.id}
                          selectedFeedbackTemplateId={req.id}
                          handleRemoveFeedbackTemplate={this.props.handleRemoveFeedbackTemplate}
                          onEditFeedbackTemplate={this.onEditFeedbackTemplate}
                          onDuplicateFeedbackTemplate={this.onDuplicateFeedbackTemplate}
                          onSelectFeedbackTemplate={this.onSelectFeedbackTemplate}
                          permission={this.props.permission}
                          feedbackTemplateData={feedbackTemplateData}
                        />
                      )
                  )}
                </ul>
              ) : (
                <div className="lux-feedback-template-editor__list-empty">
                  <i className="fe fe-inbox" aria-hidden="true" />
                  <strong>No templates found</strong>
                  <span>
                    {this.state.filterText
                      ? "Try a different search or create a new template."
                      : "Create your first feedback template to get started."}
                  </span>
                  <button type="button" className="lux-feedback-template-editor__new is-inline" onClick={this.onNewTemplate}>
                    <i className="fe fe-plus" aria-hidden="true" />
                    New template
                  </button>
                </div>
              )}
            </div>
          </aside>

          <div className="lux-feedback-template-editor__form-pane">
            <LuxFeedbackTemplateEditorHero
              feedbackTemplateRequest={req}
              editMode={this.state.editMode}
              questionCount={questionCount}
              feedbackTypeOptions={this.getFeedbackTypeOptions()}
              feedbackSubTypeOptions={this.props.feedbackSubTypeOptions}
              onNewTemplate={this.onNewTemplate}
            />

            <LuxFeedbackTemplateDetailsSection
              feedbackTemplateRequest={req}
              editMode={this.state.editMode}
              fieldConfig={this.props.fieldConfig}
              onChange={this.onChange}
              onFormError={this.onFormError}
              feedbackTypeOptions={this.getFeedbackTypeOptions()}
              feedbackSubTypeOptions={this.props.feedbackSubTypeOptions}
              allUserTeams={this.props.allUserTeams}
            />

            <section className="lux-feedback-template-editor__card lux-feedback-template-editor__card--questions">
              <header className="lux-feedback-template-editor__card-head lux-feedback-template-editor__card-head--tools">
                <div>
                  <i className="fe fe-help-circle" aria-hidden="true" />
                  <h3>Questions</h3>
                  <span className="lux-feedback-template-editor__card-hint">
                    Build the survey recipients will answer
                  </span>
                </div>
                {this.state.editMode && (
                  <div className="lux-feedback-template-editor__card-tools">
                    <button
                      type="button"
                      className="lux-feedback-template-editor__tool-btn is-accent"
                      title="Add question"
                      onClick={this.addNewQuesiton}
                    >
                      <i className="fe fe-plus" aria-hidden="true" />
                      Add question
                    </button>
                    <button
                      type="button"
                      className={classNames("lux-feedback-template-editor__tool-btn", {
                        "is-active": this.state.questionConfigureMode,
                      })}
                      title="Edit question fields and types"
                      onClick={() => this.togglequestionConfigureMode(true)}
                    >
                      <i className="fe fe-sliders" aria-hidden="true" />
                      Configure
                    </button>
                    <button
                      type="button"
                      className={classNames("lux-feedback-template-editor__tool-btn", {
                        "is-active": !this.state.questionConfigureMode,
                      })}
                      title="Compact list preview"
                      onClick={() => this.togglequestionConfigureMode(false)}
                    >
                      <i className="fe fe-eye" aria-hidden="true" />
                      Preview
                    </button>
                  </div>
                )}
              </header>
              <div className="lux-feedback-template-editor__card-body lux-feedback-template-questions">
                <LuxFeedbackTemplateQuestions
                  onChange={this.onChange}
                  editMode={this.state.editMode}
                  questionConfigureMode={this.state.questionConfigureMode}
                  questionDataList={req.questionDataList}
                  typeOptions={this.props.typeOptions}
                />
                {questionCount === 0 && this.state.editMode && (
                  <p className="lux-feedback-template-editor__questions-empty">
                    Add at least one question before saving.
                  </p>
                )}
              </div>
            </section>

            {this.props.hasFormError && (
              <div className="lux-feedback-template-editor__error" role="alert">
                <i className="fe fe-alert-triangle" aria-hidden="true" />
                <span>Complete all mandatory fields and add valid questions before saving.</span>
                <button type="button" onClick={() => this.props.onResetFormError()}>
                  Dismiss
                </button>
              </div>
            )}
          </div>
        </div>

        <footer className="lux-feedback-template-editor__foot">
          <p className="lux-feedback-template-editor__foot-hint">
            Templates are shared across feedback campaigns for this item type.
          </p>
          <div className="lux-feedback-template-editor__foot-actions">
            <button
              type="button"
              className="lux-feedback-template-editor__btn is-ghost"
              onClick={this.onRestFeedbackTemplate}
            >
              Reset
            </button>
            {this.canSave() && (
              <button
                type="button"
                className="lux-feedback-template-editor__btn is-primary"
                onClick={this.onSaveFeedbackTemplate}
              >
                <i className="fe fe-save" aria-hidden="true" />
                {req.id ? "Save template" : "Create template"}
              </button>
            )}
            {req.id && !this.state.editMode && this.props.permission.editEnabled && (
              <button
                type="button"
                className="lux-feedback-template-editor__btn is-secondary"
                onClick={() => this.onEditFeedbackTemplate(req)}
              >
                <i className="fe fe-edit-2" aria-hidden="true" />
                Edit template
              </button>
            )}
          </div>
        </footer>
      </div>
    );
  }
}

class FeedbackTemplateItem extends Component {
  constructor() {
    super();
    this.state = { confirmRemove: false };
  }

  handleRemoveFeedbackTemplate = () => {
    if (this.state.confirmRemove) {
      this.props.handleRemoveFeedbackTemplate(this.props.feedbackTemplateData.id);
      this.setState({ confirmRemove: false });
    } else {
      this.setState({ confirmRemove: true });
    }
  };

  render() {
    const { feedbackTemplateData } = this.props;
    const isSelected =
      this.props.selectedFeedbackTemplateId &&
      this.props.selectedFeedbackTemplateId === feedbackTemplateData.id;
    const questionCount =
      feedbackTemplateData.questionDataList && feedbackTemplateData.questionDataList.length
        ? feedbackTemplateData.questionDataList.length
        : 0;

    return (
      <li
        className={classNames("lux-feedback-template-editor__item", { "is-selected": isSelected })}
        key={feedbackTemplateData.id}
      >
        <div className="lux-feedback-template-editor__item-main">
          <button
            type="button"
            className="lux-feedback-template-editor__item-select"
            onClick={() => this.props.onSelectFeedbackTemplate(feedbackTemplateData)}
          >
            <span className="lux-feedback-template-editor__item-name">{feedbackTemplateData.name}</span>
            <span className="lux-feedback-template-editor__item-meta">
              {questionCount} q{feedbackTemplateData.subType ? ` · ${feedbackTemplateData.subType}` : ""}
            </span>
          </button>
          <div className="lux-feedback-template-editor__item-actions">
            <a
              className="lux-feedback-template-editor__item-action"
              href={`/document/feedback/template/${feedbackTemplateData.id}`}
              target="_blank"
              rel="noopener noreferrer"
              title="Preview template"
              onClick={(e) => e.stopPropagation()}
            >
              <i className="fe fe-eye" aria-hidden="true" />
            </a>
            {this.props.permission.editEnabled && (
              <button
                type="button"
                className="lux-feedback-template-editor__item-action"
                title="Edit"
                onClick={(e) => {
                  e.stopPropagation();
                  this.props.onEditFeedbackTemplate(feedbackTemplateData);
                }}
              >
                <i className="fe fe-edit-2" aria-hidden="true" />
              </button>
            )}
            {this.props.permission.duplicateEnabled && (
              <button
                type="button"
                className="lux-feedback-template-editor__item-action"
                title="Duplicate"
                onClick={() => this.props.onDuplicateFeedbackTemplate(feedbackTemplateData)}
              >
                <i className="fe fe-copy" aria-hidden="true" />
              </button>
            )}
            {this.props.permission.removeEnabled && !isSelected && (
              <button
                type="button"
                className="lux-feedback-template-editor__item-action is-danger"
                title={this.state.confirmRemove ? "Confirm remove" : "Remove"}
                onClick={this.handleRemoveFeedbackTemplate}
              >
                <i
                  className={classNames("fe", this.state.confirmRemove ? "fe-check" : "fe-x")}
                  aria-hidden="true"
                />
              </button>
            )}
          </div>
        </div>
      </li>
    );
  }
}

const mapStateToProps = (state) => ({
  currentUser: state.authentication.user,
  allUserTeams: state.appconfig.allTeams,
  feedbackTemplateDataList: state.feedbackTemplate.templateItems,
  fieldConfig: state.feedbackTemplate.feedbackTemplateFieldConfig,
  typeOptions: state.feedbackTemplate.typeOptions,
  feedbackTypeOptions: state.feedbackTemplate.feedbackTypeOptions,
  feedbackSubTypeOptions: state.feedbackTemplate.feedbackSubTypeOptions,
});

const mapDispatchToProps = (dispatch) => ({
  getAllFeedbackTemplates: feedbackTemplateActions.getAllFeedbackTemplates,
  createFeedbackTemplate: feedbackTemplateActions.createFeedbackTemplate,
  updateFeedbackTemplate: feedbackTemplateActions.updateFeedbackTemplate,
  removeFeedbackTemplate: feedbackTemplateActions.removeFeedbackTemplate,
  activateFeedbackTemplate: feedbackTemplateActions.activateFeedbackTemplate,
});

export default connect(mapStateToProps, mapDispatchToProps)(ConfigureFeedbackTemplateSidebar);
