import moment from "moment";
import dateUtils from "_helpers/date.utils";
import { getChecklistProgress } from "./fragments/checklist.utils";
import {
  getChecklistStatusMeta,
  getPendingDueMeta,
  getWorkItemPriorityMeta,
  getWorkItemStatusMeta,
} from "./workItemActivity.utils";

const STATUS_STAGES = ["NEW", "ASSIGNED", "INPROGRESS", "COMPLETED"];

function hoursFromMins(mins) {
  return Math.round(((Number(mins) || 0) / 60) * 10) / 10;
}

export function buildWorkItemDetailSummary(item) {
  if (!item) return null;

  const statusMeta = getWorkItemStatusMeta(item.status);
  const priorityMeta = getWorkItemPriorityMeta(item.taskPriority);
  const checklistMeta = getChecklistStatusMeta(item);
  const checklistProgress = getChecklistProgress(item.checklistData);
  const dueMeta = getPendingDueMeta(item.taskEstCompletionTime || item.estStartTime);
  const isCompleted = ["COMPLETED", "CLOSED"].includes((item.status || "").toUpperCase());
  const estHours = hoursFromMins(item.estDurationInMins);
  const actualHours = hoursFromMins(item.durationInMins);
  const utilizationRate =
    estHours > 0 ? Math.min(100, Math.round((actualHours / estHours) * 100)) : 0;
  const hoursVariance = Math.round((actualHours - estHours) * 10) / 10;

  let hoursVarianceLabel = "On plan";
  let hoursVarianceTone = "even";
  if (hoursVariance > 0.05) {
    hoursVarianceLabel = `${hoursVariance}h over plan`;
    hoursVarianceTone = "over";
  } else if (hoursVariance < -0.05) {
    hoursVarianceLabel = `${Math.abs(hoursVariance)}h under plan`;
    hoursVarianceTone = "under";
  }

  const currentStageIndex = STATUS_STAGES.indexOf((item.status || "NEW").toUpperCase());
  const stages = STATUS_STAGES.map((key, index) => ({
    key,
    label: getWorkItemStatusMeta(key).label,
    tone: getWorkItemStatusMeta(key).tone,
    active: index === currentStageIndex,
    complete: currentStageIndex >= 0 && index < currentStageIndex,
  }));

  const timeline = [
    {
      key: "estStart",
      label: "Planned start",
      value: dateUtils.convertDateTimeFormat(item.estStartTime),
      display: dateUtils.convertDateFormat(item.estStartTime) || "—",
      tone: "sky",
      highlight: false,
      hint: "Estimated kickoff",
    },
    {
      key: "actualStart",
      label: "Actual start",
      value: dateUtils.convertDateTimeFormat(item.actualStartTime),
      display: dateUtils.convertDateFormat(item.actualStartTime) || "Not started",
      tone: "indigo",
      highlight: true,
      hint: "When work began",
    },
    {
      key: "actualEnd",
      label: "Actual end",
      value: dateUtils.convertDateTimeFormat(item.actualEndTime),
      display: dateUtils.convertDateFormat(item.actualEndTime) || (isCompleted ? "—" : "In progress"),
      tone: "green",
      highlight: true,
      hint: isCompleted ? "Work finished" : "Still open",
    },
    {
      key: "due",
      label: "Due",
      value: dueMeta.dueLabel,
      display: dueMeta.dueLabel || "—",
      subDisplay: dueMeta.label,
      tone: dueMeta.tone,
      highlight: true,
      hint: dueMeta.overdue ? "Overdue" : dueMeta.dueSoon ? "Due soon" : dueMeta.label,
    },
  ];

  const kpis = [
    {
      key: "status",
      label: "Status",
      value: statusMeta.label,
      hint: isCompleted ? "Work finished" : "Current lifecycle stage",
      tone: statusMeta.tone,
      icon: statusMeta.icon,
    },
    {
      key: "hours",
      label: isCompleted ? "Logged hours" : "Est. hours",
      value: isCompleted ? dateUtils.minuteToHourString(item.durationInMins) : dateUtils.minuteToHourString(item.estDurationInMins),
      hint: isCompleted ? `Plan ${dateUtils.minuteToHourString(item.estDurationInMins)}` : hoursVarianceLabel,
      tone: hoursVarianceTone === "over" ? "rose" : hoursVarianceTone === "under" ? "sky" : "teal",
      icon: "fe fe-watch",
    },
    {
      key: "checklist",
      label: "Checklist",
      value: checklistProgress.hasChecklist ? `${checklistProgress.percent}%` : checklistMeta.label,
      hint: checklistProgress.hasChecklist
        ? `${checklistProgress.answered}/${checklistProgress.total} answered`
        : "No checklist attached",
      tone: checklistMeta.tone,
      icon: "fe fe-check-square",
    },
    {
      key: "priority",
      label: "Priority",
      value: priorityMeta.label,
      hint: `Level P${priorityMeta.level}`,
      tone: priorityMeta.tone,
      icon: "fe fe-flag",
    },
  ];

  const sections = [
    {
      key: "timing",
      title: "Timing",
      icon: "fe fe-clock",
      fields: [
        { label: "Actual start", value: dateUtils.convertDateTimeFormat(item.actualStartTime) },
        { label: "Recorded start", value: dateUtils.convertDateTimeFormat(item.recordedStartTime) },
        { label: "Estimated start", value: dateUtils.convertDateTimeFormat(item.estStartTime) },
        { label: "Actual end", value: dateUtils.convertDateTimeFormat(item.actualEndTime) },
        { label: "Recorded end", value: dateUtils.convertDateTimeFormat(item.recordedEndTime) },
        { label: "Last updated", value: dateUtils.convertDateTimeFormat(item.lastModifiedDate) },
        { label: "Created", value: dateUtils.convertDateTimeFormat(item.createdDate) },
      ],
    },
    {
      key: "people",
      title: "People",
      icon: "fe fe-users",
      fields: [
        { label: "Assigned to", value: (item.ownerDetails && item.ownerDetails.name) || "—" },
        { label: "User team", value: (item.ownerUserTeamDetails && item.ownerUserTeamDetails.name) || "—" },
        { label: "Created by", value: (item.createdByDetails && item.createdByDetails.name) || "—" },
        { label: "Completed by", value: (item.completedByDetails && item.completedByDetails.name) || "—" },
      ],
    },
    {
      key: "scope",
      title: "Scope",
      icon: "fe fe-layers",
      fields: [
        { label: "Deliverable", value: item.taskName || "—" },
        { label: "Project", value: item.projectName || "—" },
        { label: "Category", value: item.taskActCategory || "—" },
        { label: "Type", value: item.taskType === "NON_PROJECT" ? "Non-project" : item.taskType === "PROJECT" ? "Project billable" : item.taskType || "—" },
        { label: "Reference", value: item.itemIdUserTeamPrefix || "—" },
      ],
    },
  ];

  if (item.taskType === "PROJECT") {
    sections.push({
      key: "billing",
      title: "Project details",
      icon: "fe fe-briefcase",
      fields: [
        { label: "Quantity", value: item.quantity || "—" },
        { label: "Skill", value: item.skill || "—" },
        { label: "Project code", value: item.projectcode || "—" },
      ],
    });
  }

  if (item.taskType === "NON_PROJECT") {
    sections.push({
      key: "nonproject",
      title: "Non-project details",
      icon: "fe fe-grid",
      fields: [
        { label: "Account", value: item.account || "—" },
        { label: "Division", value: item.division || "—" },
        { label: "Client partner", value: item.clientPartner || "—" },
        { label: "Team name", value: item.teamName || "—" },
      ],
    });
  }

  const detailGroups = [
    {
      key: "when",
      title: "When it ran",
      subtitle: "Execution window",
      icon: "fe fe-clock",
      tiles: [
        { icon: "fe fe-play-circle", label: "Started", value: dateUtils.convertDateTimeFormat(item.actualStartTime) || "Not started", highlight: "date" },
        { icon: "fe fe-check-circle", label: "Finished", value: dateUtils.convertDateTimeFormat(item.actualEndTime) || "In progress", highlight: "date" },
        { icon: "fe fe-calendar", label: "Planned start", value: dateUtils.convertDateTimeFormat(item.estStartTime) || "—", highlight: "date" },
        { icon: "fe fe-flag", label: "Due", value: dueMeta.dueLabel || dueMeta.label, subValue: dueMeta.label, highlight: "date" },
        { icon: "fe fe-refresh-cw", label: "Last touch", value: dateUtils.convertDateTimeFormat(item.lastModifiedDate) || "—" },
      ],
    },
    {
      key: "team",
      title: "Team",
      subtitle: "Ownership & handoff",
      icon: "fe fe-users",
      tiles: [
        { icon: "fe fe-user", label: "Assigned to", value: (item.ownerDetails && item.ownerDetails.name) || "Unassigned", highlight: "person" },
        { icon: "fe fe-user-plus", label: "Created by", value: (item.createdByDetails && item.createdByDetails.name) || "—" },
        { icon: "fe fe-award", label: "Completed by", value: (item.completedByDetails && item.completedByDetails.name) || "—" },
        { icon: "fe fe-briefcase", label: "User team", value: (item.ownerUserTeamDetails && item.ownerUserTeamDetails.name) || "—" },
      ],
    },
    {
      key: "work",
      title: "Connected work",
      subtitle: "Where this activity lives",
      icon: "fe fe-layers",
      tiles: [
        { icon: "fe fe-package", label: "Deliverable", value: item.taskName || "—" },
        { icon: "fe fe-folder", label: "Project", value: item.projectName || "—" },
        { icon: "fe fe-tag", label: "Category", value: item.taskActCategory || "—" },
        {
          icon: "fe fe-layers",
          label: "Work type",
          value: item.taskType === "NON_PROJECT" ? "Non-project" : item.taskType === "PROJECT" ? "Billable project" : item.taskType || "—",
        },
        ...(item.taskType === "PROJECT"
          ? [
              { icon: "fe fe-hash", label: "Project code", value: item.projectcode || "—" },
              { icon: "fe fe-tool", label: "Skill", value: item.skill || "—" },
            ]
          : []),
        ...(item.taskType === "NON_PROJECT"
          ? [
              { icon: "fe fe-home", label: "Account", value: item.account || "—" },
              { icon: "fe fe-map", label: "Division", value: item.division || "—" },
            ]
          : []),
      ],
    },
  ];

  const flatDetailTiles = detailGroups.flatMap((group) =>
    group.tiles.map((tile) => ({
      ...tile,
      groupKey: group.key,
      groupTitle: group.title,
    }))
  );

  const insightStrip = [
    {
      key: "status",
      label: "Status",
      value: statusMeta.label,
      hint: isCompleted ? "Work finished" : "Current stage",
      tone: statusMeta.tone,
      icon: statusMeta.icon,
      highlight: true,
    },
    {
      key: "hours",
      label: isCompleted ? "Logged" : "Planned",
      value: isCompleted ? dateUtils.minuteToHourString(item.durationInMins) : dateUtils.minuteToHourString(item.estDurationInMins),
      hint: isCompleted ? summaryHoursHint(item, hoursVarianceLabel) : hoursVarianceLabel,
      tone: hoursVarianceTone === "over" ? "rose" : hoursVarianceTone === "under" ? "sky" : "teal",
      icon: "fe fe-watch",
      highlight: true,
    },
    {
      key: "due",
      label: "Due",
      value: dueMeta.label,
      hint: dueMeta.dueLabel,
      tone: dueMeta.tone,
      icon: "fe fe-flag",
      highlight: true,
    },
    {
      key: "util",
      label: "Utilization",
      value: isCompleted ? `${utilizationRate}%` : "—",
      hint: isCompleted ? "Actual vs estimate" : "After completion",
      tone: utilizationRate > 100 ? "rose" : utilizationRate >= 80 ? "green" : "indigo",
      icon: "fe fe-trending-up",
      highlight: isCompleted,
    },
    {
      key: "checklist",
      label: "Checklist",
      value: checklistProgress.hasChecklist ? `${checklistProgress.percent}%` : checklistMeta.label,
      hint: checklistProgress.hasChecklist ? `${checklistProgress.answered}/${checklistProgress.total} done` : "Optional gate",
      tone: checklistMeta.tone,
      icon: "fe fe-check-square",
      highlight: checklistProgress.hasChecklist,
    },
  ];

  const visualCharts = buildWorkItemDetailVisuals(
    {
      statusMeta,
      priorityMeta,
      checklistMeta,
      checklistProgress,
      stages,
      estHours,
      actualHours,
      utilizationRate,
      hoursVarianceTone,
      isCompleted,
    },
    item
  );

  return {
    statusMeta,
    priorityMeta,
    checklistMeta,
    checklistProgress,
    dueMeta,
    isCompleted,
    estHours,
    actualHours,
    utilizationRate,
    hoursVarianceLabel,
    hoursVarianceTone,
    stages,
    timeline,
    kpis,
    sections,
    detailGroups,
    flatDetailTiles,
    insightStrip,
    visualCharts,
    projectLabel: item.projectName || item.taskName || "Non-project",
    ownerName: (item.ownerDetails && item.ownerDetails.name) || "Unassigned",
  };
}

function summaryHoursHint(item, fallback) {
  const est = dateUtils.minuteToHourString(item.estDurationInMins);
  return est && est !== "0h 0m" ? `Plan ${est}` : fallback;
}

export function buildWorkItemHoursMeter(summary, item) {
  if (!summary) return null;

  const plannedLabel = dateUtils.minuteToHourString(item.estDurationInMins) || "0h 0m";
  const loggedLabel = dateUtils.minuteToHourString(item.durationInMins) || "0h 0m";
  const plannedMins = Number(item.estDurationInMins) || 0;
  const loggedMins = Number(item.durationInMins) || 0;
  const barPct =
    plannedMins > 0
      ? Math.min(100, Math.round((loggedMins / plannedMins) * 100))
      : loggedMins > 0
        ? 100
        : 0;

  return {
    plannedLabel,
    loggedLabel,
    barPct,
    utilizationRate: summary.utilizationRate,
    varianceLabel: summary.hoursVarianceLabel,
    varianceTone: summary.hoursVarianceTone,
    isCompleted: summary.isCompleted,
    caption: summary.isCompleted
      ? `${summary.utilizationRate}% of planned time logged`
      : "Planned effort before work is completed",
  };
}

export function buildWorkItemChecklistMeter(summary) {
  if (!summary) return null;

  const progress = summary.checklistProgress;
  if (!progress.hasChecklist) {
    return {
      hasChecklist: false,
      label: summary.checklistMeta.label,
      hint: "No checklist on this activity",
      tone: summary.checklistMeta.tone,
      percent: 0,
    };
  }

  return {
    hasChecklist: true,
    label: `${progress.percent}% complete`,
    hint: `${progress.answered} of ${progress.total} items answered`,
    tone: progress.complete ? "green" : progress.percent > 0 ? "indigo" : "amber",
    percent: progress.percent,
    answered: progress.answered,
    total: progress.total,
  };
}

export function buildWorkItemDetailVisuals(summary, item) {
  const stageIndex = summary.stages.findIndex((s) => s.active);
  const lifecyclePct = stageIndex >= 0 ? Math.round(((stageIndex + 1) / summary.stages.length) * 100) : 0;
  const priorityMax = 4;
  const priorityPct = Math.round(((priorityMax - summary.priorityMeta.level + 1) / priorityMax) * 100);
  const scheduleInsight = getWorkItemScheduleInsight(item);

  return {
    lifecycle: {
      pct: lifecyclePct,
      label: summary.statusMeta.label,
      tone: summary.statusMeta.tone,
      segments: summary.stages.map((stage) => ({
        key: stage.key,
        label: stage.label,
        tone: stage.tone,
        active: stage.active,
        complete: stage.complete,
      })),
    },
    priority: {
      level: summary.priorityMeta.level,
      label: summary.priorityMeta.label,
      tone: summary.priorityMeta.tone,
      pct: priorityPct,
      max: priorityMax,
    },
    scope: {
      label: item.taskType === "PROJECT" ? "Billable project" : item.taskType === "NON_PROJECT" ? "Non-project" : item.taskType || "Other",
      tone: item.taskType === "PROJECT" ? "indigo" : "teal",
      category: item.taskActCategory || "Other",
      billablePct: item.taskType === "PROJECT" ? 100 : item.taskType === "NON_PROJECT" ? 0 : 50,
    },
    schedule: {
      label: scheduleInsight.value,
      hint: scheduleInsight.hint,
      tone: scheduleInsight.tone,
      pct: scheduleInsight.tone === "green" ? 100 : scheduleInsight.tone === "amber" ? 65 : scheduleInsight.tone === "sky" ? 85 : 40,
    },
    hoursSplit: {
      planned: summary.estHours,
      logged: summary.actualHours,
      plannedLabel: dateUtils.minuteToHourString(item.estDurationInMins) || "0h 0m",
      loggedLabel: dateUtils.minuteToHourString(item.durationInMins) || "0h 0m",
      utilization: summary.utilizationRate,
      tone: summary.hoursVarianceTone,
      isCompleted: summary.isCompleted,
    },
    checklist: {
      percent: summary.checklistProgress.hasChecklist ? summary.checklistProgress.percent : 0,
      label: summary.checklistMeta.label,
      tone: summary.checklistMeta.tone,
      hasChecklist: summary.checklistProgress.hasChecklist,
    },
  };
}

export function getWorkItemScheduleInsight(item) {
  const estStart = item.estStartTime ? moment(item.estStartTime) : null;
  const actualStart = item.actualStartTime ? moment(item.actualStartTime) : null;
  if (!estStart || !actualStart) {
    return { label: "Schedule", value: "—", hint: "Start times not fully recorded", tone: "slate" };
  }
  const diffMins = actualStart.diff(estStart, "minutes");
  if (Math.abs(diffMins) < 30) {
    return { label: "Schedule", value: "On time", hint: "Started close to plan", tone: "green" };
  }
  if (diffMins > 0) {
    const hrs = Math.round((diffMins / 60) * 10) / 10;
    return { label: "Schedule", value: `${hrs}h late`, hint: "Started after estimate", tone: "amber" };
  }
  const hrs = Math.round((Math.abs(diffMins) / 60) * 10) / 10;
  return { label: "Schedule", value: `${hrs}h early`, hint: "Started before estimate", tone: "sky" };
}
