import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import PageInnerHeaderTeamsSelectionMenu from "./fragments/PageInnerHeaderTeamsSelectionMenu";
import PageInnerHeaderFilterOptionsMenu from "./fragments/PageInnerHeaderFilterOptionsMenu";
import { validationUtils } from "_helpers";
import PageInnerHeaderSearchDateMenu from "./fragments/PageInnerHeaderSearchDateMenu";
import PageInnerHeaderActivityCalendarMenu from "./fragments/PageInnerHeaderActivityCalendarMenu";
import PageInnerHeaderEmployeesSelectionMenu from "./fragments/PageInnerHeaderEmployeesSelectionMenu";
import { commonUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";
import urlConfig from "url.config";

class PageInnerHeader extends PureComponent {
  onFilterTextChange = (value) => {
    const isValidChar = validationUtils.validateAlphaNumbericWithSpecial(value);
    if (isValidChar) {
      this.props.onFilterTextChange(value);
    }
  };

  onSearchChange = (event) => {
    this.onFilterTextChange(event.target.value);
  };

  clearSearch = () => {
    this.onFilterTextChange("");
  };

  renderListFilter = () => {
    const { showFilter, isLoading, filterOptions, listFilterPlaceholder } = this.props;
    if (!showFilter) return null;

    const searchValue = (filterOptions && filterOptions.filterText) || "";

    return (
      <label className="lux-page-header__list-filter" title="Filter the loaded list">
        <i className="fe fe-filter" aria-hidden="true" />
        <input
          type="search"
          disabled={isLoading}
          value={searchValue}
          onChange={this.onSearchChange}
          placeholder={listFilterPlaceholder || "Filter list…"}
          aria-label="Filter list"
        />
        {searchValue && (
          <button
            type="button"
            className="lux-page-header__list-filter-clear"
            onClick={this.clearSearch}
            aria-label="Clear list filter"
          >
            <i className="fe fe-x" aria-hidden="true" />
          </button>
        )}
      </label>
    );
  };

  downloadReport = (event) => {
    const userTeamIds = commonUtils.getSelectedUserTeamIds(this.props.userTeams);
    const startDate = this.props.filterOptions.dateRangeValue.start.format(
      dateUtils.SERVER_DATE_FORMAT
    );
    const endDate = this.props.filterOptions.dateRangeValue.end
      .endOf("day")
      .format(dateUtils.SERVER_DATE_FORMAT);
    let url =
      urlConfig.REPORT_DOWNLOAD +
      `/${this.props.filterOptions.REPORT.selected}/key?userTeamIds=${userTeamIds}&startDate=${startDate}&endDate=${endDate}`;
    if (
      this.props.filterOptions.REPORT.selected === "myUtilization" ||
      this.props.filterOptions.REPORT.selected === "myTimesheetData" ||
      this.props.filterOptions.REPORT.selected === "myTimesheetDataDump"
    ) {
      url = url + "&employeeIds=" + [commonUtils.getCurrentUserId()];
    }
    event.target.href = url;
  };

  renderCalendarControls = () => {
    if (!this.props.enableCalendarControl) return null;

    return (
      <div className="lux-page-header__calendar-nav" role="group" aria-label="Calendar navigation">
        <button
          type="button"
          className="lux-page-header__calendar-btn"
          onClick={this.props.calendarControls.goToBack}
          title="Previous"
        >
          <i className="fa fa-chevron-left" aria-hidden="true" />
        </button>
        <button
          type="button"
          className="lux-page-header__calendar-btn"
          onClick={this.props.calendarControls.goToCurrent}
          title="Today"
        >
          <i className="fa fa-home" aria-hidden="true" />
        </button>
        <button
          type="button"
          className="lux-page-header__calendar-btn"
          onClick={this.props.calendarControls.goToNext}
          title="Next"
        >
          <i className="fa fa-chevron-right" aria-hidden="true" />
        </button>
      </div>
    );
  };

  renderReportActions = () => {
    if (!this.props.showDateActionButtons || !this.props.filterOptions) return null;

    const reportConfig = this.props.filterOptions.REPORT;
    const selectedReport =
      reportConfig &&
      reportConfig.options.find((report) => report.name === reportConfig.selected);

    return (
      <div className="lux-page-header__extras">
        {selectedReport && selectedReport.viewEnabled === true && (
          <button
            type="button"
            onClick={this.props.handleView}
            className="lux-page-header__action-btn"
          >
            <i className="fa fa-list-alt" aria-hidden="true" />
            View
          </button>
        )}
        <a
          onClick={(event) => this.downloadReport(event)}
          target="_new"
          rel="noopener noreferrer"
          className="lux-page-header__action-btn lux-page-header__action-btn--accent"
        >
          <i className="fa fa-download" aria-hidden="true" />
          Download
        </a>
      </div>
    );
  };

  render() {
    const {
      stickytop,
      showUserTeamMenu,
      userTeams,
      handleUserTeamsSelection,
      isLoading,
      permission,
      enableUserTeamSingleSelection,
      showEmployeeMenu,
      employees,
      handleEmployeesSelection,
      employeeMenuEnabled,
      employeeEnableSingleSelection,
      showEmployeeNameDropDownLabel,
      applyEmployeeSelectionImmediately,
      selectedEmployeeId,
      allowAllTeamEmployees,
      filterOptions,
      handleFilterChange,
      showDateRangeSelector,
      handleDateRangeChange,
      showActivityCalendarMenu,
      activityCalendarProps,
      searchViewEnabled,
      handleSearchSubmit,
      searchViewOpitons,
      defaultSearchViewOpiton,
      showFilter,
      showGridListMenu,
      showGridDefault,
      gridClickHandler,
      listClickHandler,
      showCreateMenu,
      createItemHandler,
      showCreateMenuText,
      createMenuIcon,
      additionalButtons,
      employeeFilterSlot,
    } = this.props;

    const isSticky = stickytop === undefined || stickytop === true;

    return (
      <div
        className={classNames("lux-page-header", {
          "is-sticky": isSticky,
        })}
      >
        <div className="lux-page-header__toolbar">
          <div className="lux-page-header__group lux-page-header__group--filters">
            {showUserTeamMenu && userTeams && (
              <PageInnerHeaderTeamsSelectionMenu
                userTeams={userTeams}
                handleUserTeamsSelection={handleUserTeamsSelection}
                isLoading={isLoading}
                enabled={(permission && permission.switchUserTeamsEnabled) || false}
                enableSingleSelection={enableUserTeamSingleSelection}
              />
            )}

            {employeeFilterSlot}

            {showEmployeeMenu && employees && employees.length > 0 && (
              <PageInnerHeaderEmployeesSelectionMenu
                employees={employees}
                handleEmployeesSelection={handleEmployeesSelection}
                isLoading={isLoading}
                enabled={
                  employeeMenuEnabled != null
                    ? !!employeeMenuEnabled
                    : (permission && permission.switchEmployeesEnabled) || false
                }
                enableSingleSelection={
                  employeeEnableSingleSelection != null
                    ? !!employeeEnableSingleSelection
                    : !!enableUserTeamSingleSelection
                }
                showEmployeeNameDropDownLabel={showEmployeeNameDropDownLabel}
                applyEmployeeSelectionImmediately={applyEmployeeSelectionImmediately}
                selectedEmployeeId={selectedEmployeeId}
                allowAllTeamEmployees={allowAllTeamEmployees}
              />
            )}

            {filterOptions && (
              <PageInnerHeaderFilterOptionsMenu
                filterOptions={filterOptions}
                handleFilterChange={handleFilterChange}
                isLoading={isLoading}
              />
            )}

            {this.renderListFilter()}

            {this.renderCalendarControls()}
          </div>

          <div className="lux-page-header__spacer" aria-hidden="true" />

          <div className="lux-page-header__group lux-page-header__group--actions">
            {showActivityCalendarMenu && activityCalendarProps && (
              <div className="lux-page-header__query-tools">
                <PageInnerHeaderActivityCalendarMenu
                  {...activityCalendarProps}
                  isLoading={isLoading}
                />
              </div>
            )}

            {showDateRangeSelector && (
                <PageInnerHeaderSearchDateMenu
                  defaultDateRangeValue={filterOptions && filterOptions.dateRangeValue}
                  handleDateRangeChange={handleDateRangeChange}
                  searchViewEnabled={searchViewEnabled}
                  handleSearchSubmit={handleSearchSubmit}
                  searchViewOpitons={searchViewOpitons}
                  defaultSearchViewOpiton={defaultSearchViewOpiton}
                  isLoading={isLoading}
                />
            )}

            {this.renderReportActions()}

            {showGridListMenu && (
              <div className="lux-page-header__views" role="group" aria-label="View mode">
                <button
                  type="button"
                  className={classNames("lux-page-header__view-btn", {
                    "is-active": showGridDefault,
                  })}
                  onClick={gridClickHandler}
                  title="Grid view"
                  aria-pressed={showGridDefault}
                >
                  <i className="fe fe-grid" aria-hidden="true" />
                </button>
                <button
                  type="button"
                  className={classNames("lux-page-header__view-btn", {
                    "is-active": !showGridDefault,
                  })}
                  onClick={listClickHandler}
                  title="List view"
                  aria-pressed={!showGridDefault}
                >
                  <i className="fe fe-list" aria-hidden="true" />
                </button>
              </div>
            )}

            {showCreateMenu && (
              <button
                type="button"
                className="lux-page-header__create-btn"
                onClick={createItemHandler}
              >
                <i className={`fe ${createMenuIcon || "fe-plus"}`} aria-hidden="true" />
                <span>{showCreateMenuText || "Create"}</span>
              </button>
            )}

              {additionalButtons && (
              <div className="lux-page-header__extras">{additionalButtons}</div>
            )}
          </div>
        </div>
      </div>
    );
  }
}

export default PageInnerHeader;
