import dateUtils from "_helpers/date.utils";

export function getWorkItemChecklistMeta(checklistStatus, checklistData) {
  const status = (checklistStatus || "").toUpperCase();
  if (status === "COMPLETED") {
    return { label: "Done", tone: "green", icon: "fe fe-check-circle" };
  }
  if (status === "INPROGRESS") {
    return { label: "In progress", tone: "amber", icon: "fe fe-loader" };
  }
  if (checklistData && Object.keys(checklistData).length > 0) {
    return { label: "Not started", tone: "slate", icon: "fe fe-square" };
  }
  return { label: "None", tone: "muted", icon: "fe fe-minus" };
}

export function getWorkItemHoursMeta(item) {
  const isDone = item.status === "COMPLETED" || item.status === "CLOSED";
  const mins = isDone ? item.durationInMins : item.estDurationInMins;
  const value = dateUtils.minuteToHourString(mins) || "0h 0m";
  const tone = isDone ? "green" : item.status === "INPROGRESS" ? "amber" : "indigo";
  const label = isDone ? "Logged" : "Planned";
  return { value, tone, label, isDone };
}

export function formatWorkItemOwner(item) {
  return (item.ownerDetails && item.ownerDetails.name) || "Unassigned";
}

export function getWorkItemOwnerInitial(item) {
  const name = formatWorkItemOwner(item);
  return name ? name.charAt(0).toUpperCase() : "?";
}
