import React from "react";
import CustomInput from "views/common/fragments/formfields/CustomInput";
import ProjectTaskAccessRestrictionControlInput from "../fragments/ProjectTaskAccessRestrictionControlInput";
import ProjectServiceScopeField from "./ProjectServiceScopeField";
import { commonUtils } from "_helpers";
import { resolveProjectServiceLineOptions } from "./projectServiceLine.utils";
import { FormCluster, FieldGrid, FieldCell, gridCols } from "./createProjectFormLayout";

export {
  PROJECT_FORM_LEFT_SECTIONS,
  PROJECT_FORM_RIGHT_SECTIONS,
} from "./createProjectFormLayout";

const BILLING_TYPE_OPTIONS = [
  { value: "BILLABLE", label: "Billable" },
  { value: "BILLABLE_DA", label: "Billable DA" },
  { value: "NON_BILLABLE_PRODUCTIVE", label: "Non Billable Productive" },
  { value: "NON_BILLABLE", label: "Non Billable" },
];

const PROJECT_TYPE_OPTIONS = [
  { value: "ADHOC", label: "Adhoc" },
  { value: "FTEMS", label: "FTE-Managed Services" },
  { value: "FTESA", label: "FTE-Staff-Aug" },
  { value: "SERVICES", label: "Services" },
  { value: "PRODUCT", label: "Product" },
  { value: "TRACKER", label: "Tracker" },
  { value: "TMHB", label: "T & M (Hourly Billing)" },
];

function renderProjectBasics(ctx) {
  const { projectRequest, props, onChange, onFormError, onPurchaseOrderChange, getFieldConfig, isFullForm } = ctx;
  const cols = gridCols(isFullForm, 2, 4);
  const compact = isFullForm;
  const lockedByPo = projectRequest.purchaseOrderId;
  const dateMin =
    props.permission.projectDatesRestrictedByPurchaseOrderDates ? ctx.purchaseOrderStartTime : null;
  const dateMax =
    props.permission.projectDatesRestrictedByPurchaseOrderDates ? ctx.purchaseOrderCompletionTime : null;

  return (
    <>
      <FormCluster
        title="Project identity"
        hint="Name shown across the portfolio and dashboards."
        icon="fe fe-bookmark"
        compact={compact}
      >
        <FieldGrid cols={1}>
          <FieldCell span="full">
            <CustomInput
              inputtype="text"
              label="Project Name"
              name="name"
              autoComplete="on"
              fieldConfig={props.fieldConfig}
              mappingObject={projectRequest}
              onChange={onChange}
              onFormError={onFormError}
              placeholder="Project Name..."
              datatype="alpnumspl"
            />
          </FieldCell>
        </FieldGrid>
      </FormCluster>

      <FormCluster
        title="Contract & references"
        hint="Purchase contract link, commercial IDs, billing, and schedule."
        icon="fe fe-link"
        compact={compact}
      >
        <FieldGrid cols={cols}>
          <FieldCell span={isFullForm ? 2 : "full"}>
            <CustomInput
              type="select"
              label="Purchase Order"
              name="purchaseOrderId"
              editMode={props.editMode}
              fieldConfig={getFieldConfig()}
              mappingObject={projectRequest}
              onChange={onPurchaseOrderChange}
              onFormError={onFormError}
              placeholder="Select purchase contract…"
              options={
                props.purchaseOrders &&
                commonUtils.convertPurchaseOrderNameToSelectObject(props.purchaseOrders)
              }
            />
          </FieldCell>
          <FieldCell>
            <CustomInput
              inputtype="text"
              label="Order Book Ref"
              name="orderBookRef"
              fieldConfig={props.fieldConfig}
              mappingObject={projectRequest}
              onChange={onChange}
              onFormError={onFormError}
              placeholder="Order book ref…"
              datatype="alpnumspace"
            />
          </FieldCell>
          <FieldCell>
            <CustomInput
              inputtype="text"
              label="PO Number"
              name="purchaseOrderNumber"
              fieldConfig={props.fieldConfig}
              mappingObject={projectRequest}
              onChange={onChange}
              onFormError={onFormError}
              placeholder="PO number…"
              datatype="alpnumspace"
              readOnly={lockedByPo}
            />
          </FieldCell>
          <FieldCell>
            <CustomInput
              inputtype="text"
              label="Proposal Number"
              name="proposalNumber"
              fieldConfig={props.fieldConfig}
              mappingObject={projectRequest}
              onChange={onChange}
              onFormError={onFormError}
              placeholder="Proposal #…"
              datatype="alpnumspace"
              readOnly={lockedByPo}
            />
          </FieldCell>
          <FieldCell>
            <CustomInput
              inputtype="text"
              label="Project Code"
              name="code"
              fieldConfig={props.fieldConfig}
              mappingObject={projectRequest}
              onChange={onChange}
              onFormError={onFormError}
              placeholder="Project code…"
              datatype="alpnumspace"
            />
          </FieldCell>
          <FieldCell>
            <CustomInput
              type="select"
              label="Billing Type"
              name="type"
              fieldConfig={props.fieldConfig}
              mappingObject={projectRequest}
              onChange={onChange}
              placeholder="Type…"
              options={BILLING_TYPE_OPTIONS}
              onFormError={onFormError}
              readOnly={lockedByPo}
            />
          </FieldCell>
          <FieldCell>
            <CustomInput
              type="dateselect"
              label="Est. Start"
              name="estStartTime"
              fieldConfig={props.fieldConfig}
              mappingObject={projectRequest}
              onChange={onChange}
              time={false}
              datePortal={true}
              onFormError={onFormError}
              minDate={dateMin}
              maxDate={dateMax}
            />
          </FieldCell>
          <FieldCell>
            <CustomInput
              type="dateselect"
              label="Est. Completion"
              name="estCompletionTime"
              fieldConfig={props.fieldConfig}
              mappingObject={projectRequest}
              onChange={onChange}
              time={false}
              datePortal={true}
              onFormError={onFormError}
              minDate={dateMin}
              maxDate={dateMax}
            />
          </FieldCell>
        </FieldGrid>
      </FormCluster>
    </>
  );
}

function renderClientStudy(ctx) {
  const { projectRequest, props, onChange, onChangeCommaSeparatedValues, onFormError, isFullForm } = ctx;
  const cols = gridCols(isFullForm, 2, 3);
  const compact = isFullForm;
  const accountMappingEnabled = commonUtils.isAccountTeamClientMappingRelationshipEnabled(
    props.createConfig
  );
  const lockedByPo = projectRequest.purchaseOrderId;

  return (
    <>
      <FormCluster title="Account mapping" hint="Who the work is delivered for." icon="fe fe-briefcase" compact={compact}>
        <FieldGrid cols={cols}>
          <FieldCell>
            <CustomInput
              type="select"
              label="Account"
              name="accountName"
              fieldConfig={props.fieldConfig}
              mappingObject={projectRequest}
              onChange={onChange}
              placeholder="Account..."
              options={
                props.allProjectTeamAccounts &&
                commonUtils.getAccountOptions(props.allProjectTeamAccounts)
              }
              onFormError={onFormError}
              readOnly={lockedByPo}
            />
          </FieldCell>
          <FieldCell>
            {accountMappingEnabled ? (
              <CustomInput
                type="select"
                label="Team"
                name="teamName"
                fieldConfig={props.fieldConfig}
                mappingObject={projectRequest}
                onChange={onChange}
                placeholder="Team..."
                options={
                  props.allProjectTeamAccounts &&
                  commonUtils.getTeamOptions(
                    props.allProjectTeamAccounts,
                    projectRequest.accountName
                  )
                }
                onFormError={onFormError}
                readOnly={lockedByPo}
              />
            ) : (
              <CustomInput
                inputtype="text"
                label="Client"
                name="clientNames"
                fieldConfig={props.fieldConfig}
                mappingObject={projectRequest}
                onChange={onChangeCommaSeparatedValues}
                onFormError={onFormError}
                placeholder="Client..."
                datatype="alpnumspl"
              />
            )}
          </FieldCell>
          <FieldCell>
            {accountMappingEnabled ? (
              <CustomInput
                type="select"
                label="Client"
                name="clientNames"
                fieldConfig={props.fieldConfig}
                mappingObject={projectRequest}
                onChange={onChange}
                placeholder="Client..."
                options={
                  props.allProjectTeamAccounts &&
                  commonUtils.getClientsOptions(
                    props.allProjectTeamAccounts,
                    projectRequest.accountName,
                    projectRequest.teamName
                  )
                }
                onFormError={onFormError}
                multi={true}
              />
            ) : (
              <CustomInput
                inputtype="text"
                label="Client Email"
                name="clientEmails"
                fieldConfig={props.fieldConfig}
                mappingObject={projectRequest}
                onChange={onChangeCommaSeparatedValues}
                onFormError={onFormError}
                placeholder="Client emails…"
                datatype="alpnumspace"
              />
            )}
          </FieldCell>
          <FieldCell>
            {accountMappingEnabled && (
              <CustomInput
                inputtype="text"
                label="Client Email"
                name="clientEmails"
                fieldConfig={props.fieldConfig}
                mappingObject={projectRequest}
                onChange={onChangeCommaSeparatedValues}
                onFormError={onFormError}
                placeholder="Client emails…"
                datatype="alpnumspace"
              />
            )}
          </FieldCell>
          <FieldCell>
            <CustomInput
              inputtype="text"
              label="Client Partner"
              name="clientPartner"
              fieldConfig={props.fieldConfig}
              mappingObject={projectRequest}
              onChange={onChange}
              onFormError={onFormError}
              placeholder="Partner / sales…"
              datatype="alpnumspace"
            />
          </FieldCell>
          <FieldCell>
            <CustomInput
              type="select"
              label="Location"
              name="location"
              fieldConfig={props.fieldConfig}
              mappingObject={projectRequest}
              onChange={onChange}
              placeholder="Location..."
              options={[
                { value: "Offshore", label: "Offshore" },
                { value: "Onshore", label: "Onshore" },
              ]}
              onFormError={onFormError}
            />
          </FieldCell>
        </FieldGrid>
      </FormCluster>

      <FormCluster title="Study classification" hint="Inherited from the contract when linked to a PO." icon="fe fe-activity" compact={compact}>
        <FieldGrid cols={cols}>
          <FieldCell>
            <CustomInput
              type="select"
              label="Project Type"
              name="projectType"
              fieldConfig={props.fieldConfig}
              mappingObject={projectRequest}
              onChange={onChange}
              placeholder="Project Type..."
              options={PROJECT_TYPE_OPTIONS}
              onFormError={onFormError}
              disabled={true}
            />
          </FieldCell>
          <FieldCell>
            <CustomInput
              type="select"
              label="Service Category"
              name="serviceCategory"
              createConfig={props.createConfig}
              fieldConfig={props.fieldConfig}
              mappingObject={projectRequest}
              onChange={onChange}
              placeholder="Service Category..."
              isAppConfig={true}
              onFormError={onFormError}
              disabled={true}
            />
          </FieldCell>
          <FieldCell>
            <CustomInput
              type="select"
              label="Survey Type"
              name="surveyType"
              createConfig={props.createConfig}
              fieldConfig={props.fieldConfig}
              mappingObject={projectRequest}
              onChange={onChange}
              placeholder="Survey Type..."
              isAppConfig={true}
              onFormError={onFormError}
              disabled={true}
            />
          </FieldCell>
        </FieldGrid>
      </FormCluster>
    </>
  );
}

function renderServiceScope(ctx) {
  const { projectRequest, props, onChange, onFormError, purchaseOrderServiceLineEstimate, purchaseOrderServiceLines } = ctx;

  return (
    <ProjectServiceScopeField
      readOnly={props.readOnly}
      createConfig={props.createConfig}
      fieldConfig={props.fieldConfig}
      mappingObject={projectRequest}
      onChange={onChange}
      onFormError={onFormError}
      name="serviceLineEstimate"
      serviceLineEstimate={projectRequest.serviceLineEstimate}
      parentServiceLineEstimate={purchaseOrderServiceLineEstimate}
      purchaseOrderServiceLines={purchaseOrderServiceLines}
      serviceLineOptions={resolveProjectServiceLineOptions(ctx)}
      permission={props.permission}
    />
  );
}

