import React, { Component } from "react";
import { NavLink } from "react-router-dom";
import dateUtils from "_helpers/date.utils";
import classNames from "classnames/bind";
import LuxBackNav from "views/common/fragments/LuxBackNav";
import SelectInput from "views/common/fragments/formfields/SelectInput";
import ItemCommentsSection from "./fragments/ItemCommentsSection";
import ItemChecklistInput from "./fragments/ItemChecklistInput";
import ConfigureChecklistSidebar from "./modal/ConfigureChecklistSidebar";
import ProjectServiceLineView from "./fragments/ProjectServiceLineView";
import PurchaseOrderDetailStatistics from "./PurchaseOrderDetailStatistics";
import { connect } from "react-redux";
import { purchaseOrderActions, checklistActions } from "_actions";
import { store } from "_helpers";
import {
  getPoProjectTypeMeta,
  getPoStatusMeta,
  getPoStatusSelectValue,
} from "./purchaseOrderList.utils";
import {
  formatPoDetailField,
  PO_DETAIL_SECTIONS,
  PO_DETAIL_STATUS_OPTIONS,
} from "./purchaseOrderDetail.utils";

class PurchaseOrderDetailsGeneral extends Component {
  handleUpdateStatus = (purchaseOrderId, status) => {
    store.dispatch(this.props.updatePurchaseOrderStatus(purchaseOrderId, status));
  };

  handleUpdateChecklist = (checklistData) => {
    store.dispatch(
      this.props.updateItemChecklistData(checklistData, this.props.item.id, "PURCHASE_ORDER")
    );
  };

  renderFact = (icon, label, value) => {
    const iconClass = icon.startsWith("fe-") ? icon : icon.replace(/^fe /, "");
    return (
      <div className="lux-bid-detail__fact">
        <span className="lux-bid-detail__fact-icon" aria-hidden="true">
          <i className={`fe ${iconClass}`} />
        </span>
        <div>
          <span className="lux-bid-detail__fact-label">{label}</span>
          <strong className="lux-bid-detail__fact-value">{value || "—"}</strong>
        </div>
      </div>
    );
  };

  renderMetaCard = (title, children) => (
    <section className="lux-bid-detail__card">
      <header className="lux-bid-detail__card-head">
        <h2>{title}</h2>
      </header>
      <div className="lux-bid-detail__card-body">{children}</div>
    </section>
  );

  renderFieldSection = (section) => {
    const { item } = this.props;
    return (
      <section key={section.id} className="lux-bid-detail__section">
        <header className="lux-bid-detail__section-head">
          <div>
            <span className="lux-bid-detail__section-eyebrow">{section.eyebrow}</span>
            <h2 className="lux-bid-detail__section-title">{section.title}</h2>
          </div>
        </header>
        <div className="lux-po-detail__field-grid">
          {section.fields.map((field) =>
            this.renderFact(field.icon, field.label, formatPoDetailField(item, field))
          )}
        </div>
      </section>
    );
  };

  render() {
    const { item, permission, readOnly, compactView, projectStatistics, statisticsItemId } =
      this.props;
    if (!item) return null;

    const statusMeta = getPoStatusMeta(item.status);
    const typeMeta = getPoProjectTypeMeta(item.projectType);
    const teamName = item.ownerUserTeamDetails && item.ownerUserTeamDetails.name;
    const ownerName = item.ownerDetails && item.ownerDetails.name;
    const clientLine =
      item.clientNames && item.clientNames.length
        ? item.clientNames.join(", ")
        : null;

    return (
      <div
        className={classNames("lux-bid-detail lux-po-detail", {
          "lux-bid-detail--compact": compactView,
          [`is-status-${statusMeta.tone}`]: true,
        })}
      >
        {!compactView && (
          <LuxBackNav
            component={NavLink}
            to="/sales/purchaseorders"
            destinationLabel="Purchase contracts"
            currentLabel={item.itemIdUserTeamPrefix || item.purchaseOrderNumber}
            navClassName="lux-bid-detail__breadcrumb"
            aria-label="Breadcrumb"
          />
        )}

        <header className="lux-bid-detail__hero">
          <div className="lux-bid-detail__hero-glow" aria-hidden="true" />
          <div className="lux-bid-detail__hero-inner">
            <div className="lux-bid-detail__hero-main">
              <div className="lux-bid-detail__hero-badges">
                <span className="lux-bid-detail__ref-pill">
                  {item.itemIdUserTeamPrefix || item.purchaseOrderNumber}
                </span>
                <span className={classNames("lux-bid-detail__status-pill", `is-${statusMeta.tone}`)}>
                  {statusMeta.label}
                </span>
                {typeMeta && (
                  <span className={classNames("lux-bid-detail__type-pill", `is-${typeMeta.tone}`)}>
                    {typeMeta.label}
                  </span>
                )}
                {item.salesForceId && (
                  <span className="lux-bid-detail__flag-pill is-sky">
                    <i className="fe fe-cloud" aria-hidden="true" /> SF linked
                  </span>
                )}
                {item.deleted && (
                  <span className="lux-bid-detail__flag-pill is-danger">Deleted</span>
                )}
              </div>
              <h1 className="lux-bid-detail__title">{item.name}</h1>
              <p className="lux-bid-detail__subtitle">
                {teamName && (
                  <>
                    <i className="fe fe-layers" aria-hidden="true" />
                    {teamName}
                    <span className="lux-bid-detail__dot">·</span>
                  </>
                )}
                {item.accountName && (
                  <>
                    <i className="fe fe-briefcase" aria-hidden="true" />
                    {item.accountName}
                    <span className="lux-bid-detail__dot">·</span>
                  </>
                )}
                {ownerName && (
                  <>
                    <i className="fe fe-user" aria-hidden="true" />
                    {ownerName}
                  </>
                )}
              </p>
            </div>

            <div className="lux-bid-detail__hero-aside">
              <label className="lux-bid-detail__status-label">Contract status</label>
              <div className={classNames("lux-bid-detail__status-select", `is-${statusMeta.tone}`)}>
                <SelectInput
                  options={PO_DETAIL_STATUS_OPTIONS}
                  value={getPoStatusSelectValue(item.status)}
                  allowLevelDown={permission.allowStatusLevelDown}
                  changeableStatus={permission.changeableStatus}
                  isReadOnly={!permission.allowStatusChange || readOnly}
                  itemId={item.id}
                  onChange={this.handleUpdateStatus}
                  className="lux-bid-detail__status-input"
                />
              </div>
            </div>
          </div>

          {!compactView && (
            <div className="lux-bid-detail__facts">
              {this.renderFact(
                "fe-calendar",
                "Start date",
                dateUtils.convertDateFormat(item.estStartTime)
              )}
              {this.renderFact(
                "fe-flag",
                "Due date",
                dateUtils.convertDateFormat(item.estCompletionTime)
              )}
              {this.renderFact("fe-target", "Bid ID", item.bidId)}
              {this.renderFact("fe-cloud", "Salesforce", item.salesForceId)}
            </div>
          )}
        </header>

        <div className="lux-bid-detail__layout">
          <main className="lux-bid-detail__main">
            <section className="lux-bid-detail__section">
              <header className="lux-bid-detail__section-head">
                <div>
                  <span className="lux-bid-detail__section-eyebrow">Overview</span>
                  <h2 className="lux-bid-detail__section-title">Description</h2>
                </div>
              </header>
              <p className="lux-po-detail__description">
                {item.description || "No description provided for this contract."}
              </p>
            </section>

            {PO_DETAIL_SECTIONS.map((section) => this.renderFieldSection(section))}

            <section className="lux-bid-detail__section lux-po-detail__service-lines">
              <ProjectServiceLineView item={item} permission={permission} />
            </section>

            {permission.checklistEnabled && (
              <section className="lux-bid-detail__section">
                <header className="lux-bid-detail__section-head">
                  <div>
                    <span className="lux-bid-detail__section-eyebrow">Quality</span>
                    <h2 className="lux-bid-detail__section-title">Checklist</h2>
                  </div>
                </header>
                <ItemChecklistInput
                  handleUpdateChecklist={this.handleUpdateChecklist}
                  type="PURCHASE_ORDER"
                  permission={permission}
                  checklistData={item.checklistData}
                  itemUserTeamId={item.userTeamId}
                />
              </section>
            )}
          </main>

          {!compactView && (
            <aside className="lux-bid-detail__rail" aria-label="Contract metadata">
              {this.renderMetaCard(
                "Timeline",
                <>
                  {this.renderFact(
                    "fe-play-circle",
                    "Start",
                    dateUtils.convertDateFormat(item.estStartTime)
                  )}
                  {this.renderFact(
                    "fe-flag",
                    "Due",
                    dateUtils.convertDateFormat(item.estCompletionTime)
                  )}
                  {this.renderFact(
                    "fe-calendar",
                    "Created",
                    dateUtils.convertDateTimeFormat(item.createdDate)
                  )}
                  {item.lastModifiedDate &&
                    this.renderFact(
                      "fe-edit",
                      "Last updated",
                      dateUtils.convertDateTimeFormat(item.lastModifiedDate)
                    )}
                </>
              )}

              {this.renderMetaCard(
                "Ownership",
                <>
                  {this.renderFact("fe-user", "Contract owner", ownerName)}
                  {this.renderFact("fe-layers", "Team", teamName)}
                  {item.createdByDetails &&
                    this.renderFact("fe-user-check", "Created by", item.createdByDetails.name)}
                  {item.updatedByDetails &&
                    this.renderFact("fe-user-check", "Updated by", item.updatedByDetails.name)}
                </>
              )}

              {clientLine &&
                this.renderMetaCard(
                  "Clients",
                  <div className="lux-po-detail__client-line">{clientLine}</div>
                )}

              {projectStatistics != null && statisticsItemId && (
                <PurchaseOrderDetailStatistics
                  items={projectStatistics}
                  itemId={statisticsItemId}
                  loadData={this.props.loadProjectStatistics}
                />
              )}
            </aside>
          )}
        </div>

        {!compactView && (
          <section className="lux-bid-detail__comments-panel">
            <header className="lux-bid-detail__section-head">
              <div>
                <span className="lux-bid-detail__section-eyebrow">Collaboration</span>
                <h2 className="lux-bid-detail__section-title">Comments</h2>
              </div>
            </header>
            <div className="lux-bid-detail__comments-body">
              <ItemCommentsSection
                itemId={item.id}
                subType="PURCHASE_ORDER"
                isReadOnly={readOnly}
              />
            </div>
          </section>
        )}

        <ConfigureChecklistSidebar
          type="PURCHASE_ORDER"
          show={this.props.showChecklistModel}
          showConfigWindow={this.props.showChecklistModel}
          showChecklistQuestionsWindow={false}
        />
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  showChecklistModel: state.checklist.isShowConfigureChecklistSidebar,
});

const mapDispatchToProps = () => ({
  updatePurchaseOrderStatus: purchaseOrderActions.updatePurchaseOrderStatus,
  updateItemChecklistData: checklistActions.updateItemChecklistData,
});

export default connect(mapStateToProps, mapDispatchToProps)(PurchaseOrderDetailsGeneral);
