export function buildScheduleSummary(items) {
  const list = items || [];
  const enabled = list.filter((i) => i.enabled && !i.deleted).length;
  const disabled = list.filter((i) => !i.enabled && !i.deleted).length;
  const removed = list.filter((i) => i.deleted).length;

  return {
    total: list.length,
    enabled,
    disabled,
    removed,
    stats: [
      { key: "total", label: "Schedulers", value: list.length, hint: "Background jobs" },
      { key: "enabled", label: "Active", value: enabled, tone: "green", hint: "Running on cron" },
      { key: "disabled", label: "Paused", value: disabled, tone: "amber", hint: "Manually stopped" },
      { key: "removed", label: "Removed", value: removed, tone: removed > 0 ? "rose" : "slate", hint: "Marked deleted" },
    ],
  };
}

export function getScheduleStatusMeta(item) {
  if (item.deleted) {
    return { label: "Removed", tone: "rose", icon: "fe fe-trash-2" };
  }
  if (item.enabled) {
    return { label: "Active", tone: "green", icon: "fe fe-play-circle" };
  }
  return { label: "Paused", tone: "amber", icon: "fe fe-pause-circle" };
}

export function buildServiceHealthSummary(serviceHealth) {
  const servers = (serviceHealth && serviceHealth.healthStatusResponses) || [];
  const integrations = (serviceHealth && serviceHealth.serviceStatusResponses) || [];
  const all = [...servers, ...integrations];
  const up = all.filter((h) => h.status === "UP").length;
  const down = all.length - up;

  return {
    total: all.length,
    up,
    down,
    serverCount: servers.length,
    integrationCount: integrations.length,
    stats: [
      { key: "total", label: "Services", value: all.length, hint: "Monitored endpoints" },
      { key: "up", label: "Healthy", value: up, tone: "green", hint: "Reporting UP" },
      { key: "down", label: "Issues", value: down, tone: down > 0 ? "rose" : "slate", hint: "Needs attention" },
    ],
  };
}

export function getHealthStatusMeta(status) {
  if (status === "UP") {
    return { label: "Operational", tone: "green", icon: "fe fe-check-circle" };
  }
  return { label: "Degraded", tone: "rose", icon: "fe fe-alert-circle" };
}
