export const SEARCH_VIEWS = {
  ALL: "ALL",
  PROJECT: "PROJECT",
  TASK: "TASK",
};

export const SEARCH_PAGE_SIZE = 10;
export const SEARCH_PAGE_SIZE_OPTIONS = [10, 20, 50];

export function getSearchCounts(searchResults) {
  const projects = (searchResults && searchResults.projects) || [];
  const tasks = (searchResults && searchResults.tasks) || [];
  return {
    projects: projects.length,
    tasks: tasks.length,
    total: projects.length + tasks.length,
  };
}

export function getVisibleResults(searchResults, view) {
  if (!searchResults) {
    return { projects: [], tasks: [] };
  }

  const projects = searchResults.projects || [];
  const tasks = searchResults.tasks || [];

  if (view === SEARCH_VIEWS.PROJECT) {
    return { projects, tasks: [] };
  }
  if (view === SEARCH_VIEWS.TASK) {
    return { projects: [], tasks };
  }
  return { projects, tasks };
}

export function escapeRegExp(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

export function tokenizeQuery(query) {
  return String(query || "")
    .trim()
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean);
}

export function splitHighlight(text, query) {
  if (!text || !query || !String(query).trim()) {
    return [{ text: text || "", match: false }];
  }

  const parts = String(text).split(new RegExp(`(${escapeRegExp(query.trim())})`, "gi"));
  return parts.filter(Boolean).map((part) => ({
    text: part,
    match: part.toLowerCase() === String(query).trim().toLowerCase(),
  }));
}

function readBackendScore(item) {
  if (item == null) return null;
  if (item.relevanceScore != null && !Number.isNaN(Number(item.relevanceScore))) {
    return Number(item.relevanceScore);
  }
  if (item.score != null && !Number.isNaN(Number(item.score))) {
    return Number(item.score);
  }
  if (item.rank != null && !Number.isNaN(Number(item.rank))) {
    return Math.max(0, 1000 - Number(item.rank));
  }
  return null;
}

export function computeRelevanceScore(item, query) {
  const backendScore = readBackendScore(item);
  if (backendScore != null) return backendScore;

  const q = String(query || "").trim().toLowerCase();
  if (!q) return 0;

  const tokens = tokenizeQuery(query);
  const name = String(item.name || "").toLowerCase();
  const summary = String(item.summary || "").toLowerCase();
  const id = String(item.id || "").toLowerCase();
  const code = String(item.code || item.projectCode || item.taskCode || "").toLowerCase();

  let score = 0;

  if (id === q) score += 1000;
  if (code && code === q) score += 920;
  if (name === q) score += 850;
  if (name.startsWith(q)) score += 520;

  tokens.forEach((token) => {
    if (name === token) score += 220;
    else if (name.startsWith(token)) score += 140;
    else if (new RegExp(`\\b${escapeRegExp(token)}`, "i").test(name)) score += 90;
    else if (name.includes(token)) score += 55;

    if (summary.includes(token)) score += 28;
    if (id.includes(token)) score += 160;
    if (code && code.includes(token)) score += 110;
  });

  if (item.deleted === true) score *= 0.82;

  return score;
}

export function getMatchReasons(item, query) {
  const q = String(query || "").trim().toLowerCase();
  if (!q) return ["Related"];

  const tokens = tokenizeQuery(query);
  const name = String(item.name || "").toLowerCase();
  const summary = String(item.summary || "").toLowerCase();
  const id = String(item.id || "");
  const code = String(item.code || item.projectCode || item.taskCode || "").toLowerCase();
  const reasons = [];

  if (id === q || tokens.some((t) => id === t)) reasons.push("ID match");
  if (code && (code === q || tokens.some((t) => code.includes(t)))) reasons.push("Code match");
  if (name === q) reasons.push("Exact title");
  else if (name.startsWith(q)) reasons.push("Title prefix");
  else if (tokens.every((t) => name.includes(t))) reasons.push("Title match");
  if (summary && tokens.some((t) => summary.includes(t))) reasons.push("Summary match");

  return reasons.length ? reasons.slice(0, 3) : ["Related"];
}

export function getRelevanceLabel(relevancePct) {
  if (relevancePct >= 90) return "Top match";
  if (relevancePct >= 70) return "Strong match";
  if (relevancePct >= 45) return "Good match";
  return "Related";
}

export function buildRankedResults(searchResults, view, query) {
  const { projects, tasks } = getVisibleResults(searchResults, view);
  const entries = [
    ...projects.map((item) => ({
      type: "project",
      item,
      score: computeRelevanceScore(item, query),
    })),
    ...tasks.map((item) => ({
      type: "task",
      item,
      score: computeRelevanceScore(item, query),
    })),
  ];

  entries.sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    if (a.type !== b.type) return a.type === "project" ? -1 : 1;
    return String(a.item.name || "").localeCompare(String(b.item.name || ""));
  });

  const maxScore = entries.length ? entries[0].score : 0;

  return entries.map((entry, index) => {
    const relevancePct = maxScore > 0 ? Math.round((entry.score / maxScore) * 100) : 0;
    return {
      ...entry,
      rank: index + 1,
      relevancePct,
      relevanceLabel: getRelevanceLabel(relevancePct),
      matchReasons: getMatchReasons(entry.item, query),
    };
  });
}

export function paginateRankedResults(items, page, pageSize = SEARCH_PAGE_SIZE) {
  const total = items.length;
  const totalPages = Math.max(1, Math.ceil(total / pageSize));
  const safePage = Math.min(Math.max(1, page), totalPages);
  const start = (safePage - 1) * pageSize;

  return {
    items: items.slice(start, start + pageSize),
    page: safePage,
    pageSize,
    total,
    totalPages,
    rangeStart: total === 0 ? 0 : start + 1,
    rangeEnd: Math.min(start + pageSize, total),
  };
}

export function buildPageNumbers(currentPage, totalPages, maxVisible = 7) {
  if (totalPages <= maxVisible) {
    return Array.from({ length: totalPages }, (_, i) => i + 1);
  }

  const pages = new Set([1, totalPages, currentPage, currentPage - 1, currentPage + 1]);
  const sorted = [...pages].filter((p) => p >= 1 && p <= totalPages).sort((a, b) => a - b);
  const result = [];

  sorted.forEach((page, index) => {
    if (index > 0 && page - sorted[index - 1] > 1) {
      result.push("ellipsis");
    }
    result.push(page);
  });

  return result;
}

